  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (51, 'The Whisper Man', 'When his young son vanishes, a widower enlists help from his estranged father, a retired detective who put away the serial killer now linked to the case.', 'James Ashcroft', 111, '2026-08-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ndRs5lADYm0PeVjuOxaMcInY0o2.jpg', 'https://www.youtube.com/watch?v=ZHRR-1CKYIQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (52, 'Insidious: Out of the Further', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', 'Jacob Chase', 106, '2026-08-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 'https://www.youtube.com/watch?v=gXjurDkYnEM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (53, 'Spider-Man: Across the Spider-Verse', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', 'Joaquim Dos Santos, Justin K. Thompson, Kemp Powers', 140, '2023-05-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'https://www.youtube.com/watch?v=BbXJ3_AQE_o', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (54, 'Jurassic World Rebirth', 'Five years after the events of Jurassic World Dominion, covert operations expert Zora Bennett is contracted to lead a skilled team on a top-secret mission to secure genetic material from the world''s three most massive dinosaurs. When Zora''s operation intersects with a civilian family whose boating expedition was capsized, they all find themselves stranded on an island where they come face-to-face with a sinister, shocking discovery that''s been hidden from the world for decades.', 'Gareth Edwards', 134, '2025-06-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', 'https://www.youtube.com/watch?v=2ZhB-YO5Tnk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (55, 'Scary Movie', 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', 'Michael Tiddes', 96, '2026-06-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/znHT8peERZRWG1ME3r0Db0EV8k8.jpg', 'https://www.youtube.com/watch?v=0fZ58S-7QP0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (56, 'Michael', 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', 'Antoine Fuqua', 128, '2026-04-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dueFqKLvjftnELZaGYwY7xinfaI.jpg', 'https://www.youtube.com/watch?v=k-YAcjaLuSI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (57, 'Dark Nuns', 'Desperation drives two nuns to perform an exorcism no nun should attempt. With a possessed child at the mercy of evil and the opposition of the Catholic Church, they take on the dangerous forbidden rituals themselves, putting their immortal souls in grave danger. They must confront the terrifying cost of their sacrilegious actions, but one goal remains: the boy must be saved at all costs.', 'Kwon Hyeok-jae', 115, '2025-01-24', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/2Abt2GgscAGtGAXTrhH44qPhugI.jpg', 'https://www.youtube.com/watch?v=YdOQ0kKtyrY', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (58, 'Rage of Stars', 'A story about a woman from the International Special Forces Unit, who has a premonition about the impending end of humanity.', 'Łukasz Róg', 106, '2026-08-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oLld47ZT1I3iecM3OWhIphohQUJ.jpg', 'https://www.youtube.com/watch?v=F5bYhuO2Rkg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (59, 'Masters of the Universe', 'After being separated for 15 years, the Sword of Power leads Prince Adam back to Eternia, where he discovers his home shattered under the fiendish rule of Skeletor. To save his family and his world, Adam must join forces with his closest allies, Teela and Duncan/Man-At-Arms, and embrace his true destiny as He-Man — the most powerful man in the universe.', 'Travis Knight', 141, '2026-06-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oRuyGUHdoaQxWP3SDfafGkStxTC.jpg', 'https://www.youtube.com/watch?v=RZ4dblwZ2TY', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (60, 'Batman: Knightfall Part 1: Knightfall', 'Arkham Asylum has been destroyed, and all its inmates have been unleashed upon Gotham City. As Batman races to round up some of his greatest enemies, he is pushed to his physical and mental limits and into a final confrontation with a new threat: the man called Bane!', 'Jeff Wamester', 79, '2026-06-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/360qdtu2hLnqMu8SVHMywn420w1.jpg', 'https://www.youtube.com/watch?v=90HAqMk7qv0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (61, 'False Positive', 'After months of trying and failing to get pregnant, Lucy and Adrian finally find their dream fertility doctor in the illustrious Dr. Hindle. But after becoming pregnant with a healthy baby girl, Lucy begins to notice something sinister through Hindle''s gleaming charm, and she sets out to uncover the unsettling truth about him.', 'John Lee', 93, '2021-06-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3HSov8EW2fI3oQbUJxOvnf684ej.jpg', 'https://www.youtube.com/watch?v=-B6u2eJLuH8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (62, 'Hoppers', 'Scientists have discovered how to ''hop'' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.', 'Daniel Chong', 104, '2026-03-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', 'https://www.youtube.com/watch?v=PypDSyIRRSs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (63, 'The Dog Stars', 'After the world''s population has been ravaged by a pandemic, a man lives a lonesome existence in a Colorado airplane hangar with his dog and a dour gunman he has befriended. When a mysterious transmission comes through on the radio while he’s flying his old Cessna, it sparks a hunt for the provenance of the sound.', 'Ridley Scott', 119, '2026-08-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/A7i16oDi03qrKep5pBfuTWNUTb.jpg', 'https://www.youtube.com/watch?v=-xSxaE1ClEE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (64, 'Strung', 'A talented violinist''s prestigious new role as a music tutor for an enigmatic, elite family spirals into a psychological battle for her safety and sanity.', 'Malcolm D. Lee', 119, '2026-06-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/exO0gvoZUXERxUaejyDchobOvjD.jpg', 'https://www.youtube.com/watch?v=DT_i0aq-vPs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (65, 'Top Gun: Maverick', 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', 'Joseph Kosinski', 131, '2022-05-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', 'https://www.youtube.com/watch?v=Klc__shdj88', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (66, 'Dune', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', 'Denis Villeneuve', 155, '2021-09-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', 'https://www.youtube.com/watch?v=8g18jFHCLXk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (67, 'Oppenheimer', 'The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.', 'Christopher Nolan', 181, '2023-07-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', 'https://www.youtube.com/watch?v=bK6ldnjE3Y0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (68, 'The Batman', 'In his second year of fighting crime, Batman uncovers corruption in Gotham City that connects to his own family while facing a serial killer known as the Riddler.', 'Matt Reeves', 177, '2022-03-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/74xTEgt7R36Fpooo50r9T25onhq.jpg', 'https://www.youtube.com/watch?v=mqqft2x_Aa4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (69, 'The Housemaid', 'Trying to escape her past, Millie Calloway accepts a job as a live-in housemaid for the wealthy Nina and Andrew Winchester. But what begins as a dream job quickly unravels into something far more dangerous—a sexy, seductive game of secrets, scandal, and power.', 'Paul Feig', 131, '2025-12-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cWsBscZzwu5brg9YjNkGewRUvJX.jpg', 'https://www.youtube.com/watch?v=48CtX6OgU3s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (70, 'Superman', 'Superman, a journalist in Metropolis, embarks on a journey to reconcile his Kryptonian heritage with his human upbringing as Clark Kent.', 'James Gunn', 130, '2025-07-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', 'https://www.youtube.com/watch?v=MikgqM0LXr4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (71, 'Coco', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', 'Lee Unkrich', 105, '2017-10-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', 'https://www.youtube.com/watch?v=Rvr68u6k5sI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (72, 'The Devil Wears Prada 2', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', 'David Frankel', 119, '2026-04-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xTI42pmsP5EDnvsNJPEDubwWBQO.jpg', 'https://www.youtube.com/watch?v=PMd1at7OwiE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (73, 'Practical Magic 2', 'The Owens sisters must confront the dark curse that threatens to unravel their family once and for all.', 'Susanne Bier', 130, '2026-09-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ogwQOLbCfncjvBhFb5l0OmQH8KC.jpg', 'https://www.youtube.com/watch?v=Ho10_4IX1jE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (74, 'Hope', 'In the remote South Korean village of Hope Harbor, police chief Bum-seok and officer Sung-ae are called to investigate a mysterious creature wreaking havoc on the community. But all is not as it seems, and perceptions can be misleading. What begins as ignorance plants the seed of disaster, escalating through human conflict into a tragedy of cosmic proportions.', 'Na Hong-jin', 157, '2026-07-15', 'T13', 'ko', 'https://image.tmdb.org/t/p/w500/1n37BJchWHLiSYQkuFxe5KjB951.jpg', 'https://www.youtube.com/watch?v=ODnHr2Emnf0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (75, 'Lucky Strike', 'A wounded American soldier fights to survive behind enemy lines during WWII''s Battle of the Bulge against the Germans, relying on his instinct, spy craft and a hand-radio to evade capture and find his way back to his unit.', 'Rod Lurie', 102, '2026-06-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', 'https://www.youtube.com/watch?v=vtEnjikCXyA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (76, 'Avatar: The Way of Water', 'Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure.', 'James Cameron', 192, '2022-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', 'https://www.youtube.com/watch?v=a8Gx8wiNbs8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (77, 'My Fault', 'Noah must leave her city, boyfriend, and friends to move into William Leister''s mansion, the flashy and wealthy husband of her mother Rafaela. As a proud and independent 17 year old, Noah resists living in a mansion surrounded by luxury. However, it is there where she meets Nick, her new stepbrother, and the clash of their strong personalities becomes evident from the very beginning.', 'Domingo González', 116, '2023-06-08', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/w46Vw536HwNnEzOa7J24YH9DPRS.jpg', 'https://www.youtube.com/watch?v=xY-qRGC6Yu0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (78, 'F1', 'Racing legend Sonny Hayes is coaxed out of retirement to lead a struggling Formula 1 team—and mentor a young hotshot driver—while chasing one more chance at glory.', 'Joseph Kosinski', 156, '2025-06-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9PXZIUsSDh4alB80jheWX4fhZmy.jpg', 'https://www.youtube.com/watch?v=8yh9BPUBbbQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (79, 'Shelter', 'A man living in self-imposed exile on a remote island rescues a young girl from a violent storm, setting off a chain of events that forces him out of seclusion to protect her from enemies tied to his past.', 'Ric Roman Waugh', 107, '2026-01-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cv7DeQQ7TOozPoTCBdNJIvWKhU1.jpg', 'https://www.youtube.com/watch?v=PPMawzJxKF4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (80, 'Swapped', 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', 'Nathan Greno', 102, '2026-05-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', 'https://www.youtube.com/watch?v=glgmAwRDP8s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (81, 'KPop Demon Hunters', 'When K-pop superstars Rumi, Mira and Zoey aren''t selling out stadiums, they''re using their secret powers to protect their fans from supernatural threats.', 'Chris Appelhans, Maggie Kang', 96, '2025-06-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zT7Lhw3BhJbMkRqm9Zlx2YGMsY0.jpg', 'https://www.youtube.com/watch?v=AzCAwdp1uIQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (82, 'Deep Water', 'A group of international passengers on a flight from Los Angeles to Shanghai is forced to make an emergency landing in shark-infested waters. The terrified group is forced to work together and overcome their differences if they hope to escape their sinking plane and the frenzy of sharks drawn to the wreckage.', 'Renny Harlin', 107, '2026-04-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ZWHxL2ETItcZzeVsVfs6gv3SZ7.jpg', 'https://www.youtube.com/watch?v=f0ptq0Lzdh8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (83, 'Inside Out 2', 'Teenager Riley''s mind headquarters is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who’ve long been running a successful operation by all accounts, aren’t sure how to feel when Anxiety shows up. And it looks like she’s not alone.', 'Kelsey Mann', 97, '2024-06-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', 'https://www.youtube.com/watch?v=L4DrolmDxmw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (84, 'War Machine', 'On one last grueling mission during Army Ranger training, a combat engineer must lead his unit in a fight against a giant otherworldly killing machine.', 'Patrick Hughes', 110, '2026-02-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ril8yx5SOmj0KjNlftsdfIp00fr.jpg', 'https://www.youtube.com/watch?v=AFuE1LRxm80', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (85, 'The Invite', 'Joe and Angela''s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?', 'Olivia Wilde', 107, '2026-06-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'https://www.youtube.com/watch?v=OJ19I9q_hOQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (86, 'Guardians of the Galaxy Vol. 3', 'Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.', 'James Gunn', 150, '2023-05-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', 'https://www.youtube.com/watch?v=AAE5VZktooM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (87, 'Fast X', 'Over many missions and against impossible odds, Dom Toretto and his family have outsmarted, out-nerved and outdriven every foe in their path. Now, they confront the most lethal opponent they''ve ever faced: A terrifying threat emerging from the shadows of the past who''s fueled by blood revenge, and who is determined to shatter this family and destroy everything—and everyone—that Dom loves, forever.', 'Louis Leterrier', 142, '2023-05-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fiVW06jE7z9YnO4trhaMEdclSiC.jpg', 'https://www.youtube.com/watch?v=32RAq6JzY-w', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (88, 'Spider-Man: Into the Spider-Verse', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.', 'Bob Persichetti, Peter Ramsey, Rodney Rothman', 117, '2018-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', 'https://www.youtube.com/watch?v=g4Hbz2jLxvQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (89, 'Lee Cronin''s The Mummy', 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.', 'Lee Cronin', 133, '2026-04-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1q308iixueCU4pFtSYugNOevtNx.jpg', 'https://www.youtube.com/watch?v=6wbMsDmJLCs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (90, 'Moana 2', 'After receiving an unexpected call from her wayfinding ancestors, Moana journeys alongside Maui and a new crew to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', 'Dana Ledoux Miller, David G. Derrick Jr., Jason Hand', 100, '2024-11-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aLVkiINlIeCkcZIzb7XHzPYgO6L.jpg', 'https://www.youtube.com/watch?v=JdSl4RMNtGE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (91, 'Mortal Kombat II', 'The fan favorite champions—now joined by Johnny Cage himself—are pitted against one another in the ultimate, no-holds barred, gory battle to defeat the dark rule of Shao Kahn that threatens the very existence of the Earthrealm and its defenders.', 'Simon McQuoid', 116, '2026-05-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hwRdDFIhaEmpRgoki805YvyyjZf.jpg', 'https://www.youtube.com/watch?v=ZdC5mFHPldg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (92, 'GOAT', 'A small goat with big dreams gets a once-in-a-lifetime shot to join the pros and play roarball, a high-intensity, co-ed, full-contact sport dominated by the fastest, fiercest animals in the world.', 'Tyree Dillihay', 100, '2026-02-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/wfuqMlaExcoYiUEvKfVpUTt1v4u.jpg', 'https://www.youtube.com/watch?v=5r-7eWDBc40', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (93, 'Parasite', 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.', 'Bong Joon Ho', 133, '2019-05-30', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', 'https://www.youtube.com/watch?v=PhPROyE0OaM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (94, 'Weapons', 'When all but one child from the same class mysteriously vanish on the same night at exactly the same time, a community is left questioning who or what is behind their disappearance.', 'Zach Cregger', 129, '2025-08-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg', 'https://www.youtube.com/watch?v=OpThntO9ixc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (95, 'Mission: Impossible - The Final Reckoning', 'Ethan Hunt and team continue their search for the terrifying AI known as the Entity — which has infiltrated intelligence networks all over the globe — with the world''s governments and a mysterious ghost from Hunt''s past on their trail. Joined by new allies and armed with the means to shut the Entity down for good, Hunt is in a race against time to prevent the world as we know it from changing forever.', 'Christopher McQuarrie', 170, '2025-05-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iKPsC9EFUafRP9SrUznI61getVP.jpg', 'https://www.youtube.com/watch?v=G1VBfMCZVkw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (96, 'Amazon Hot Box', 'An innocent college student must fight for her life inside a jungle prison with an evil wardress who uses voodoo experiments and a torture machine.', 'James Bickert', 85, '2018-06-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/i5sG67f8SgyjegxPO27S9C7czsK.jpg', 'https://www.youtube.com/watch?v=0CuNUEbtK10', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (97, 'PAW Patrol: The Mighty Movie', 'A magical meteor crash lands in Adventure City and gives the PAW Patrol pups superpowers, transforming them into The Mighty Pups.', 'Cal Brunker', 88, '2023-09-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/aTvePCU7exLepwg5hWySjwxojQK.jpg', 'https://www.youtube.com/watch?v=UDgjJ9XzgHk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (98, 'The Fantastic 4: First Steps', 'Against the vibrant backdrop of a 1960s-inspired, retro-futuristic world, Marvel''s First Family is forced to balance their roles as heroes with the strength of their family bond, while defending Earth from a ravenous space god called Galactus and his enigmatic Herald, Silver Surfer.', 'Matt Shakman', 115, '2025-07-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nf5qaSEvyYSNeFH0YhSs5EsBLX9.jpg', 'https://www.youtube.com/watch?v=0uDUlDmGhUo', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (99, 'Thunderbolts*', 'After finding themselves ensnared in a death trap, seven disillusioned castoffs must embark on a dangerous mission that will force them to confront the darkest corners of their pasts.', 'Jake Schreier', 127, '2025-04-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hqcexYHbiTBfDIdDWxrxPtVndBX.jpg', 'https://www.youtube.com/watch?v=-sAOWhvheK8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (100, 'Sinners', 'Trying to leave their troubled lives behind, twin brothers return to their hometown to start again, only to discover that an even greater evil is waiting to welcome them back.', 'Ryan Coogler', 138, '2025-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', 'https://www.youtube.com/watch?v=7joulECTx_U', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
