INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (101, 'Predator: Badlands', 'Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.', 'Dan Trachtenberg', 107, '2025-11-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg', 'https://www.youtube.com/watch?v=43R9l7EkJwE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (102, 'In the Grey', 'A covert team of elite operatives are living in the shadows. When a ruthless despot steals a billion-dollar fortune, they''re sent to take it back—an impossible heist that erupts into a deadly game of strategy, deception and survival.', 'Guy Ritchie', 97, '2026-05-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dQgIcW6Th08kMRf2HBoYWoFE6OD.jpg', 'https://www.youtube.com/watch?v=nufP15iN4GE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (103, 'Venom: The Last Dance', 'Eddie and Venom are on the run. Hunted by both of their worlds and with the net closing in, the duo are forced into a devastating decision that will bring the curtains down on Venom and Eddie''s last dance.', 'Kelly Marcel', 109, '2024-10-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vGXptEdgZIhPg3cGlc7e8sNPC2e.jpg', 'https://www.youtube.com/watch?v=FKBN1qAzW3s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (104, 'Kraken', 'A marine biologist is doing research on a fish farm when she encounters several strange occurrences. Along with the brutal deaths of two teenagers, all signs point to the deep fjord; can there be more to the depths than the eye can see?', 'Pål Øie', 94, '2026-02-06', 'T16', 'no', 'https://image.tmdb.org/t/p/w500/snjASPpfqpkmA7lVXDo24rA8I0z.jpg', 'https://www.youtube.com/watch?v=EUTatY1-oBI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (105, 'Everything Everywhere All at Once', 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', 'Daniel Kwan, Daniel Scheinert', 140, '2022-03-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', 'https://www.youtube.com/watch?v=wxN1T1uxQ2g', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (106, 'The Substance', 'A fading celebrity decides to use a black market drug, a cell-replicating substance that temporarily creates a younger, better version of herself.', 'Coralie Fargeat', 141, '2024-09-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lqoMzCcZYEFK729d6qzt349fB4o.jpg', 'https://www.youtube.com/watch?v=LNlrGhBpYjc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (107, 'Once Upon a Time... in Hollywood', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…', 'Quentin Tarantino', 162, '2019-07-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', 'https://www.youtube.com/watch?v=ELeMaP8EPAA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (108, 'A Minecraft Movie', 'Four misfits find themselves struggling with ordinary problems when they are suddenly pulled through a mysterious portal into the Overworld: a bizarre, cubic wonderland that thrives on imagination. To get back home, they''ll have to master this world while embarking on a magical quest with an unexpected, expert crafter, Steve.', 'Jared Hess', 101, '2025-03-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yFHHfHcUgGAxziP1C3lLt0q2T4s.jpg', 'https://www.youtube.com/watch?v=8B1EtVPBSMw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (109, 'Sonic the Hedgehog 3', 'Sonic, Knuckles, and Tails reunite against a powerful new adversary, Shadow, a mysterious villain with powers unlike anything they have faced before. With their abilities outmatched in every way, Team Sonic must seek out an unlikely alliance in hopes of stopping Shadow and protecting the planet.', 'Jeff Fowler', 110, '2024-12-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/d8Ryb8AunYAuycVKDp5HpdWPKgC.jpg', 'https://www.youtube.com/watch?v=LH1J1EbqCaI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (110, 'Captain America: Civil War', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.', 'Anthony Russo, Joe Russo', 147, '2016-04-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', 'https://www.youtube.com/watch?v=43NWzay3W4s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (111, 'Perfect Days', 'Hirayama is content with his life as a toilet cleaner in Tokyo. Outside of his structured routine, he cherishes music on cassette tapes, books, and taking photos of trees. Through unexpected encounters, he reflects on finding beauty in the world.', 'Wim Wenders', 124, '2023-11-10', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/tvUHVSTJV9ITON3oyHaWp7oaAc8.jpg', 'https://www.youtube.com/watch?v=HTgWYojq-z8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (112, 'Puss in Boots: The Last Wish', 'Puss in Boots discovers that his passion for adventure has taken its toll: He has burned through eight of his nine lives, leaving him with only one life left. Puss sets out on an epic journey to find the mythical Last Wish and restore his nine lives.', 'Joel Crawford', 103, '2022-12-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kuf6dutpsT0vSVehic3EZIqkOBt.jpg', 'https://www.youtube.com/watch?v=RqrXhwS33yc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (113, 'The Sheep Detectives', 'George Hardy is a shepherd who reads detective novels to his beloved sheep every night, assuming they can''t possibly understand. But when a mysterious incident disrupts life on the farm, the sheep realize they must become the detectives. As they follow the clues and investigate human suspects, they prove that even sheep can be brilliant crime-solvers.', 'Kyle Balda', 109, '2026-04-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iKy5460GdsoknM8ppmGlJbKxAKa.jpg', 'https://www.youtube.com/watch?v=826SRt1CFbg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (114, 'The Wrecking Crew', 'Estranged half-brothers Jonny and James reunite after their father''s mysterious death. As they search for the truth, buried secrets reveal a conspiracy threatening to tear their family apart.', 'Ángel Manuel Soto', 125, '2026-01-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gbVwHl4YPSq6BcC92TQpe7qUTh6.jpg', 'https://www.youtube.com/watch?v=v8R0xDczERo', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (115, 'How to Train Your Dragon', 'On the rugged isle of Berk, where Vikings and dragons have been bitter enemies for generations, Hiccup stands apart, defying centuries of tradition when he befriends Toothless, a feared Night Fury dragon. Their unlikely bond reveals the true nature of dragons, challenging the very foundations of Viking society.', 'Dean DeBlois', 125, '2025-06-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', 'https://www.youtube.com/watch?v=22w7z_lT6YM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (116, 'The Brutalist', 'When an innovative modern architect flees post-war Europe, he is given the opportunity to rebuild his legacy. Set during the dawn of the modern United States (in Pennsylvania), his wife joins him, and their lives are forever changed by a demanding, wealthy patron.', 'Brady Corbet', 215, '2024-12-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vP7Yd6couiAaw9jgMd5cjMRj3hQ.jpg', 'https://www.youtube.com/watch?v=6d7yU379Ur0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (117, 'The Super Mario Bros. Movie', 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.', 'Aaron Horvath, Michael Jelenic', 93, '2023-04-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qNBAXBIQlnOThrVvA6mA2B5ggV6.jpg', 'https://www.youtube.com/watch?v=KydqdKKyGEk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (118, 'Crime 101', 'When an elusive thief whose high-stakes heists unfold along the iconic 101 freeway in Los Angeles eyes the score of a lifetime, with hopes of this being his final job, his path collides with a disillusioned insurance broker who is facing her own crossroads. Determined to crack the case, a relentless detective closes in on the operation, raising the stakes even higher.', 'Bart Layton', 141, '2026-02-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tVvpFIoteRHNnoZMhdnwIVwJpCA.jpg', 'https://www.youtube.com/watch?v=KeEHsuZ4Ja4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (119, 'Alien: Covenant', 'The crew of the colony ship Covenant, bound for a remote planet on the far side of the galaxy, discovers what they think is an uncharted paradise but is actually a dark, dangerous world.', 'Ridley Scott', 122, '2017-05-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zecMELPbU5YMQpC81Z8ImaaXuf9.jpg', 'https://www.youtube.com/watch?v=H0VW6sg50Pk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (120, 'John Wick: Chapter 4', 'With the price on his head ever increasing, John Wick uncovers a path to defeating The High Table. But before he can earn his freedom, Wick must face off against a new enemy with powerful alliances across the globe and forces that turn old friends into foes.', 'Chad Stahelski', 170, '2023-03-21', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/vZloFAK7NmvMGKE7VkF5UHaz0I.jpg', 'https://www.youtube.com/watch?v=qEVUtrk8_B4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (121, 'The Suicide Squad', 'Supervillains Harley Quinn, Bloodsport, Peacemaker and a collection of nutty cons at Belle Reve prison join the super-secret, super-shady Task Force X as they are dropped off at the remote, enemy-infused island of Corto Maltese.', 'James Gunn', 132, '2021-07-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/q61qEyssk2ku3okWICKArlAdhBn.jpg', 'https://www.youtube.com/watch?v=PDARAdc04oM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (122, 'Lilo & Stitch', 'The wildly funny and touching story of a lonely Hawaiian girl and the fugitive alien who helps to mend her broken family.', 'Dean Fleischer Camp', 108, '2025-05-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ckQzKpQJO4ZQDCN5evdpKcfm7Ys.jpg', 'https://www.youtube.com/watch?v=VWqJifMMgZE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (123, 'Kraven the Hunter', 'Kraven Kravinoff''s complex relationship with his ruthless gangster father, Nikolai, starts him down a path of vengeance with brutal consequences, motivating him to become not only the greatest hunter in the world, but also one of its most feared.', 'J.C. Chandor', 127, '2024-12-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1GvBhRxY6MELDfxFrete6BNhBB5.jpg', 'https://www.youtube.com/watch?v=hR1-ihzff3I', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (124, 'Tom Clancy''s Jack Ryan: Ghost War', 'Jack Ryan is reluctantly pulled back into espionage when an international covert mission unravels a deadly conspiracy. Racing against time, he joins CIA allies Mike November & James Greer and sharp MI6 officer Emma Marlowe to battle a rogue black-ops unit in a high-stakes, deeply personal fight.', 'Andrew Bernstein', 107, '2026-05-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/8ehYxUh5MWE41AeE9gkHE8DKzvB.jpg', 'https://www.youtube.com/watch?v=-4ZVFspRn3M', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (125, 'Jungle', 'In 1981, an enthusiastic young adventurer follows his dreams into the Bolivian Amazon jungle with two friends and a guide with a mysterious past. Their journey quickly turns into a terrifying ordeal as the darkest elements of human nature and the deadliest threats of the wilderness lead to an all-out fight for survival.', 'Greg McLean', 115, '2017-06-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tDgxknTVwrScxpCYyGUjXSn5NRk.jpg', 'https://www.youtube.com/watch?v=ADjYDl1RCGs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (126, 'The Running Man', 'Desperate to save his sick daughter, working-class Ben Richards is convinced by The Running Man''s charming but ruthless producer to enter the deadly competition game as a last resort. But Ben''s defiance, instincts, and grit turn him into an unexpected fan favorite — and a threat to the entire system. As ratings skyrocket, so does the danger, and Ben must outwit not just the Hunters, but a nation addicted to watching him fall.', 'Edgar Wright', 133, '2025-11-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dKL78O9zxczVgjtNcQ9UkbYLzqX.jpg', 'https://www.youtube.com/watch?v=KD18ddeFuyM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (127, 'Wrath of Man', 'A cold and mysterious new security guard for a Los Angeles cash truck company surprises his co-workers when he unleashes precision skills during a heist. The crew is left wondering who he is and where he came from. Soon, the marksman''s ultimate motive becomes clear as he takes dramatic and irrevocable steps to settle a score.', 'Guy Ritchie', 119, '2021-04-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/M7SUK85sKjaStg4TKhlAVyGlz3.jpg', 'https://www.youtube.com/watch?v=EFYEni2gsK0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (128, 'I Want Your Sex', 'When a naive young man becomes the sexual muse for a renowned and provocative artist, his dream job quickly turns dangerous as he is drawn into an obsessive world of power, betrayal, and murder.', 'Gregg Araki', 90, '2026-07-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pR7SIX3AwqdoD96OI44oLG98e7g.jpg', 'https://www.youtube.com/watch?v=kjkTmTmC1iA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (129, 'Barbie', 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.', 'Greta Gerwig', 114, '2023-07-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', 'https://www.youtube.com/watch?v=8zIf0XvoL9Y', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (130, 'Spider-Man: Far From Home', 'Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.', 'Jon Watts', 129, '2019-06-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', 'https://www.youtube.com/watch?v=DYYtuKyMtY8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (131, 'Greenland 2: Migration', 'Having found the safety of the Greenland bunker after the comet Clarke decimated the Earth, the Garrity family must now risk everything to embark on a perilous journey across the wasteland of Europe to find a new home.', 'Ric Roman Waugh', 98, '2026-01-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/z2tqCJLsw6uEJ8nJV8BsQXGa3dr.jpg', 'https://www.youtube.com/watch?v=H8ieN10lX40', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (132, 'Thor: Ragnarok', 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.', 'Taika Waititi', 131, '2017-10-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', 'https://www.youtube.com/watch?v=ue80QwXMRHg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (133, 'The Beekeeper', 'One man''s campaign for vengeance takes on national stakes after he is revealed to be a former operative of a powerful and clandestine organization known as Beekeepers.', 'David Ayer', 106, '2024-01-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/A7EByudX0eOzlkQ2FIbogzyazm2.jpg', 'https://www.youtube.com/watch?v=CHKn-yDCE2w', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (134, 'Ghost in the Cell', 'In a notorious prison, an invisible force begins killing inmates brutally, compelling enemy gangs and corrupt guards to work together as they try to survive the mounting bloodshed.', 'Joko Anwar', 106, '2026-04-16', 'T16', 'id', 'https://image.tmdb.org/t/p/w500/zxcMdx0w5Zmg8yZuuiS7CJ8vOea.jpg', 'https://www.youtube.com/watch?v=57BSZWpCi3E', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (135, 'Hacksaw Ridge', 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.', 'Mel Gibson', 139, '2016-10-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', 'https://www.youtube.com/watch?v=s2-1hz1juBI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (136, 'Captain America: Brave New World', 'After meeting with newly elected U.S. President Thaddeus Ross, Sam finds himself in the middle of an international incident. He must discover the reason behind a nefarious global plot before the true mastermind has the entire world seeing red.', 'Julius Onah', 119, '2025-02-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pzIddUEMWhWzfvLI3TwxUG2wGoi.jpg', 'https://www.youtube.com/watch?v=1pHDWnXmK7Y', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (137, 'Onslaught', 'When a rogue squad of genetically engineered super soldiers break loose in the desert, a badass Army sniper must unleash hell to protect her young daughter.', 'Adam Wingard', 92, '2026-09-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cOGtvhc6Ij9KvzM6jZsfQyg0B0O.jpg', 'https://www.youtube.com/watch?v=06hhVL13HEw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (138, 'Killers of the Flower Moon', 'When oil is discovered in 1920s Oklahoma under Osage Nation land, the Osage people are murdered one by one—until the FBI steps in to unravel the mystery.', 'Martin Scorsese', 206, '2023-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dB6Krk806zeqd0YNp2ngQ9zXteH.jpg', 'https://www.youtube.com/watch?v=1oZUCkJEuvo', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (139, 'Babylon', 'A tale of outsized ambition and outrageous excess, tracing the rise and fall of multiple characters in an era of unbridled decadence and depravity during Hollywood''s transition from silent films to sound films in the late 1920s.', 'Damien Chazelle', 189, '2022-12-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wjOHjWCUE0YzDiEzKv8AfqHj3ir.jpg', 'https://www.youtube.com/watch?v=5muQK7CuFtY', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (140, 'Fall', 'For best friends Becky and Hunter, life is all about conquering fears and pushing limits. But after they climb 2,000 feet to the top of a remote, abandoned radio tower, they find themselves stranded with no way down. Now Becky and Hunter''s expert climbing skills will be put to the ultimate test as they desperately fight to survive the elements, a lack of supplies, and vertigo-inducing heights.', 'Scott Mann', 107, '2022-08-11', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/spCAxD99U1A6jsiePFoqdEcY0dG.jpg', 'https://www.youtube.com/watch?v=FNk7Cu4sJOs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (141, 'The Gorge', 'Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.', 'Scott Derrickson', 128, '2025-02-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', 'https://www.youtube.com/watch?v=rUSdnuOLebE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (142, 'Scream 7', 'When a new Ghostface killer emerges in the quiet town where Sidney Prescott has built a new life, her darkest fears are realized as her daughter becomes the next target. Determined to protect her family, Sidney must face the horrors of her past to put an end to the bloodshed once and for all.', 'Kevin Williamson', 114, '2026-02-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jjyuk0edLiW8vOSnlfwWCCLpbh5.jpg', 'https://www.youtube.com/watch?v=4g8OciWNJn4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (143, 'Toy Story 4', 'Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called "Forky", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy.', 'Josh Cooley', 100, '2019-06-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', 'https://www.youtube.com/watch?v=LDXYRzerjzU', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (144, 'The Drama', 'A happily engaged couple is put to the test when an unexpected turn sends their wedding week off the rails.', 'Kristoffer Borgli', 105, '2026-04-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rnIOUhzwJDfgQakx8EjoNyItKgs.jpg', 'https://www.youtube.com/watch?v=0ZDzsH3XGFA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (145, 'Doctor Strange in the Multiverse of Madness', 'Doctor Strange, with the help of mystical allies both old and new, traverses the mind-bending and dangerous alternate realities of the Multiverse to confront a mysterious new adversary.', 'Sam Raimi', 126, '2022-05-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', 'https://www.youtube.com/watch?v=Rf8LAYJSOL8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (146, 'Ne Zha 2', 'After a catastrophic event leaves their bodies destroyed, Ne Zha and Ao Bing are granted a fragile second chance at life. As tensions rise between the dragon clans and celestial forces, the two must undergo a series of perilous trials that will test their bond, challenge their identities, and decide the fate of both mortals and immortals.', 'Jiao Zi', 144, '2025-01-29', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/293Mo4GWf7Tl0TfAr5NFghqeMy7.jpg', 'https://www.youtube.com/watch?v=ETlOSBR92Fs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (147, 'Cars 3', 'Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen finds himself pushed to the brink—and suddenly, the champion who once ruled the track is fighting just to stay in the race. With his career hanging in the balance, McQueen must turn to an ambitious young race technician with a plan of her own, draw strength from the legacy of the late Fabulous Hudson Hornet, and risk everything on one last shot at glory.', 'Brian Fee', 102, '2017-06-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zg5RDxvIIAKsucjuU2EZJIHEIvz.jpg', 'https://www.youtube.com/watch?v=2LeOH9AGJQM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (148, 'Apex', 'A grieving woman pushing her limits on a solo adventure in the Australian wild is ensnared in a twisted game with a cunning killer who thinks she''s prey.', 'Baltasar Kormákur', 96, '2026-04-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/eTp7gSPkSF3Aw79mNx1NkBP1PZT.jpg', 'https://www.youtube.com/watch?v=kgv8jf_8dm0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (149, 'Deadpool', 'The origin story of former Special Forces operative turned mercenary Wade Wilson, who, after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', 'Tim Miller', 108, '2016-02-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', 'https://www.youtube.com/watch?v=9vN6DHB6bJc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (150, 'The Conjuring 2', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.', 'James Wan', 134, '2016-06-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', 'https://www.youtube.com/watch?v=VFsmuRPClr4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
