  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (201, 'Alien: Romulus', 'While scavenging the deep ends of a derelict space station, a group of young space colonizers come face to face with the most terrifying life form in the universe.', 'Fede Álvarez', 119, '2024-08-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', 'https://www.youtube.com/watch?v=OzY2r2JXsDM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (202, 'Train to Busan', 'When a zombie virus pushes Korea into a state of emergency, those trapped on an express train to Busan must fight for their own survival.', 'Yeon Sang-ho', 118, '2016-07-20', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/vNVFt6dtcqnI7hqa6LFBUibuFiw.jpg', 'https://www.youtube.com/watch?v=0_sV9luPnMk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (203, 'Logan', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', 'James Mangold', 137, '2017-02-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', 'https://www.youtube.com/watch?v=Div0iP65aZo', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (204, 'The Equalizer 3', 'Robert McCall finds himself at home in Southern Italy but he discovers his friends are under the control of local crime bosses. As events turn deadly, McCall knows what he has to do: become his friends'' protector by taking on the mafia.', 'Antoine Fuqua', 109, '2023-08-30', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/b0Ej6fnXAP8fK75hlyi2jKqdhHz.jpg', 'https://www.youtube.com/watch?v=19ikl8vy4zs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (205, 'Transformers: Rise of the Beasts', 'When a new threat capable of destroying the entire planet emerges, Optimus Prime and the Autobots must team up with a powerful faction known as the Maximals. With the fate of humanity hanging in the balance, humans Noah and Elena will do whatever it takes to help the Transformers as they engage in the ultimate battle to save Earth.', 'Steven Caple Jr.', 127, '2023-06-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', 'https://www.youtube.com/watch?v=WWWDskI46Js', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (206, 'Sonic the Hedgehog', 'Powered with incredible speed, Sonic The Hedgehog embraces his new home on Earth. That is, until Sonic sparks the attention of super-uncool evil genius Dr. Robotnik. Now it’s super-villain vs. super-sonic in an all-out race across the globe to stop Robotnik from using Sonic’s unique power for world domination.', 'Jeff Fowler', 99, '2020-02-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aQvJ5WPzZgYVDrxLX4R6cLJCEaQ.jpg', 'https://www.youtube.com/watch?v=szby7ZHLnkA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (207, 'Seven Snipers', 'When a former elite sniper is hunted down by the ruthless warlord who once held her captive, she must fight to the death to protect the daughter she has raised in hiding, on a remote Australian farm.', 'Sandra Sciberras', 87, '2026-04-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qvcq0thb9oPwv6JG2nsTgr9LlLb.jpg', 'https://www.youtube.com/watch?v=-r-HtsJPgto', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (208, 'Batman v Superman: Dawn of Justice', 'Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.', 'Zack Snyder', 152, '2016-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5UsK3grJvtQrtzEgqNlDljJW96w.jpg', 'https://www.youtube.com/watch?v=0WWzgGyAH6Y', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (209, 'John Wick: Chapter 2', 'John Wick is forced out of retirement by a former associate looking to seize control of a shadowy international assassins’ guild. Bound by a blood oath to aid him, Wick travels to Rome and does battle against some of the world’s most dangerous killers.', 'Chad Stahelski', 122, '2017-02-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', 'https://www.youtube.com/watch?v=ChpLV9AMqm4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (210, 'Road House', 'Ex-UFC fighter Dalton takes a job as a bouncer at a Florida Keys roadhouse, only to discover that this paradise is not all it seems.', 'Doug Liman', 121, '2024-03-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fDEdtS4P0gJsxHDIt8dG8TR5dx1.jpg', 'https://www.youtube.com/watch?v=Y0ZsLudtfjI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (211, 'Jurassic World: Fallen Kingdom', 'Three years after Jurassic World was destroyed, Isla Nublar now sits abandoned. When the island''s dormant volcano begins roaring to life, Owen and Claire mount a campaign to rescue the remaining dinosaurs from this extinction-level event.', 'J. A. Bayona', 129, '2018-06-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/x2Us3jR6ToMJjbcPbLimYoxf6xr.jpg', 'https://www.youtube.com/watch?v=1FJD7jZqZEk', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (212, 'De Gaulle: Résistance', 'June, 1940. France collapses and signs the armistice. In the midst of the chaos, one man refuses to give up. Alone against the odds, this unknown general flees to London to save what remains of freedom.', 'Antonin Baudry', 160, '2026-06-03', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/4ri8KO5i7ldQiS3807KXn6awQEs.jpg', 'https://www.youtube.com/watch?v=dKUArYoZ_0U', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (213, 'Star Wars: The Rise of Skywalker', 'The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.', 'J.J. Abrams', 142, '2019-12-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/db32LaOibwEliAmSL2jjDF6oDdj.jpg', 'https://www.youtube.com/watch?v=8Qn_spdM5Zg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (214, 'The Bad Guys', 'When the Bad Guys, a crew of criminal animals, are finally caught after years of heists and being the world’s most-wanted villains, Mr. Wolf brokers a deal to save them all from prison.', 'Pierre Perifel', 100, '2022-03-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7qop80YfuO0BwJa1uXk1DXUUEwv.jpg', 'https://www.youtube.com/watch?v=m8Xt0yXaDPU', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (215, 'Ice Age: Collision Course', 'Set after the events of Continental Drift, Scrat''s epic pursuit of his elusive acorn catapults him outside of Earth, where he accidentally sets off a series of cosmic events that transform and threaten the planet. To save themselves from peril, Manny, Sid, Diego, and the rest of the herd leave their home and embark on a quest full of thrills and spills, highs and lows, laughter and adventure while traveling to exotic new lands and locations.', 'Michael Thurmeier', 95, '2016-06-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tFzUkdhPOForVrEfvxydXfPLrZR.jpg', 'https://www.youtube.com/watch?v=Ohq6NmKMja8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (216, 'Migration', 'After a migrating duck family alights on their pond with thrilling tales of far-flung places, the Mallard family embarks on a family road trip, from New England, to New York City, to tropical Jamaica.', 'Benjamin Renner', 83, '2023-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ldfCF9RhR40mppkzmftxapaHeTo.jpg', 'https://www.youtube.com/watch?v=UkHxhPGpRuA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (217, 'The Handmaiden', '1930s Korea, in the period of Japanese occupation, a new girl, Sook-hee, is hired as a handmaiden to a Japanese heiress, Hideko, who lives a secluded life on a large countryside estate with her domineering Uncle Kouzuki. But the maid has a secret. She is a pickpocket recruited by a swindler posing as a Japanese Count to help him seduce the Lady to steal her fortune.', 'Park Chan-wook', 145, '2016-06-01', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/dLlH4aNHdnmf62umnInL8xPlPzw.jpg', 'https://www.youtube.com/watch?v=6sVYumzrKvs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (218, 'Turning Red', 'Thirteen-year-old Mei is experiencing the awkwardness of being a teenager with a twist – when she gets too excited, she transforms into a giant red panda.', 'Domee Shi', 100, '2022-03-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qsdjk9oAKSQMWs0Vt5Pyfh6O4GZ.jpg', 'https://www.youtube.com/watch?v=XdKzUbAiswE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (219, 'Gladiator II', 'Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.', 'Ridley Scott', 148, '2024-11-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', 'https://www.youtube.com/watch?v=4rgYUipGJNo', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (220, 'The Bad Guys 2', 'The now-reformed Bad Guys are trying (very, very hard) to be good, but instead find themselves hijacked into a high-stakes, globe-trotting heist, masterminded by a new team of criminals they never saw coming: The Bad Girls.', 'Pierre Perifel', 104, '2025-07-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/26oSPnq0ct59l07QOXZKyzsiRtN.jpg', 'https://www.youtube.com/watch?v=HvLHYox_Vq8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (221, 'Mission: Impossible - Dead Reckoning Part One', 'Ethan Hunt and his IMF team embark on their most dangerous mission yet: To track down a terrifying new weapon that threatens all of humanity before it falls into the wrong hands. With control of the future and the world''s fate at stake and dark forces from Ethan''s past closing in, a deadly race around the globe begins. Confronted by a mysterious, all-powerful enemy, Ethan must consider that nothing can matter more than his mission—not even the lives of those he cares about most.', 'Christopher McQuarrie', 164, '2023-07-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/NNxYkU70HPurnNCSiCjYAmacwm.jpg', 'https://www.youtube.com/watch?v=2m1drlOZSDw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (222, 'Hidden Figures', 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.', 'Theodore Melfi', 127, '2016-12-10', 'K', 'en', 'https://image.tmdb.org/t/p/w500/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg', 'https://www.youtube.com/watch?v=5wfrDhgUMGI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (223, 'Zack Snyder''s Justice League', 'Determined to ensure Superman''s ultimate sacrifice was not in vain, Bruce Wayne aligns forces with Diana Prince with plans to recruit a team of metahumans to protect the world from an approaching threat of catastrophic proportions.', 'Zack Snyder', 242, '2021-03-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tnAuB8q5vv7Ax9UAEje5Xi4BXik.jpg', 'https://www.youtube.com/watch?v=ZrdQSAX2kyw', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (224, 'The Rip', 'Trust frays when a team of Miami cops discovers millions in cash inside a run-down stash house, calling everyone — and everything — into question.', 'Joe Carnahan', 113, '2026-01-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4wsYWH73Hb1B6noGIFaRQSAkuXj.jpg', 'https://www.youtube.com/watch?v=yeR5bcbRPak', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (225, 'Shang-Chi and the Legend of the Ten Rings', 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.', 'Destin Daniel Cretton', 132, '2021-09-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9f2Q0U3IOsLgrI2HkvldwSABZy5.jpg', 'https://www.youtube.com/watch?v=8YjFbMbfXaQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (226, 'Incredibles 2', 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.', 'Brad Bird', 118, '2018-06-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', 'https://www.youtube.com/watch?v=YBpdL9hSac4', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (227, 'Furiosa: A Mad Max Saga', 'As the world falls, young Furiosa is snatched from the Green Place of Many Mothers into the hands of a great biker horde led by the warlord Dementus. Sweeping through the wasteland, they encounter the citadel presided over by Immortan Joe. The two tyrants wage war for dominance, and Furiosa must survive many trials as she puts together the means to find her way home.', 'George Miller', 149, '2024-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg', 'https://www.youtube.com/watch?v=FVswuip0-co', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (228, 'Evil Dead Rise', 'A reunion between two estranged sisters gets cut short by the rise of flesh-possessing demons, thrusting them into a primal battle for survival as they face the most nightmarish version of family imaginable.', 'Lee Cronin', 96, '2023-04-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5ik4ATKmNtmJU6AYD0bLm56BCVM.jpg', 'https://www.youtube.com/watch?v=BqQNO7BzN08', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (229, 'The Ministry of Ungentlemanly Warfare', 'During World War II, the British Army assigns a group of competent soldiers to carry out a mission against the Nazi forces behind enemy lines... A true story about a secret British WWII organization — the Special Operations Executive. Founded by Winston Churchill, their irregular warfare against the Germans helped to change the course of the war, and gave birth to modern black operations.', 'Guy Ritchie', 120, '2024-04-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8aF0iAKH9MJMYAZdi0Slg77RYa2.jpg', 'https://www.youtube.com/watch?v=zvwDen1Wrx8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (230, 'Transformers One', 'The untold origin story of Optimus Prime and Megatron, better known as sworn enemies, but once were friends bonded like brothers who changed the fate of Cybertron forever.', 'Josh Cooley', 104, '2024-09-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iRCgqpdVE4wyLQvGYU3ZP7pAtUc.jpg', 'https://www.youtube.com/watch?v=5a09yJU-mCI', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (231, 'Fifty Shades Freed', 'Believing they have left behind shadowy figures from their past, newlyweds Christian and Ana fully embrace an inextricable connection and shared life of luxury. But just as she steps into her role as Mrs. Grey and he relaxes into an unfamiliar stability, new threats could jeopardize their happy ending before it even begins.', 'James Foley', 110, '2018-01-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jjPJ4s3DWZZvI4vw8Xfi4Vqa1Q8.jpg', 'https://www.youtube.com/watch?v=nJCc5HRPxYA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (232, 'Pretty Lethal', 'A troupe of ballerinas find themselves fighting for survival as they attempt to escape from a remote inn after their bus breaks down on the way to a dance competition.', 'Vicky Jewson', 89, '2026-03-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/znTPnXCK3lEQJgqXCvP7e5FUz6f.jpg', 'https://www.youtube.com/watch?v=MpNobYCw0mg', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (233, 'Finding Emily', 'When a lovesick musician is given the wrong number for his dream girl, he teams up with a driven psychology student to find her. Together, they spark a hilarious campus-wide frenzy that tests their own hearts and ambitions along the way.', 'Alicia MacDonald', 111, '2026-05-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bfEQ6C702oPsN4kzIiY7n4JsrxF.jpg', 'https://www.youtube.com/watch?v=-OGuJf70S0s', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (234, 'John Wick: Chapter 3 - Parabellum', 'Super-assassin John Wick returns with a $14 million price tag on his head and an army of bounty-hunting killers on his trail. After killing a member of the shadowy international assassin’s guild, the High Table, John Wick is excommunicado, but the world’s most ruthless hit men and women await his every turn.', 'Chad Stahelski', 131, '2019-05-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ziEuG1essDuWuC5lpWUaw1uXY2O.jpg', 'https://www.youtube.com/watch?v=M7XM597XO94', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (235, 'Beauty and the Beast', 'A live-action adaptation of Disney''s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.', 'Bill Condon', 129, '2017-03-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hKegSKIDep2ewJWPUQD7u0KqFIp.jpg', 'https://www.youtube.com/watch?v=Fp0DE1hyO6o', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (236, 'Tuner', 'A gifted piano tuner''s meticulous skills for tuning pianos lead him to discover an unexpected aptitude for cracking safes, turning his life upside down.', 'Daniel Roher', 108, '2026-05-21', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5OvA3i9wZs5jHu0DCrfmXlzAM67.jpg', 'https://www.youtube.com/watch?v=XiehvETTjTQ', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (237, 'The Secret Life of Pets 2', 'Max the terrier must cope with some major life changes when his owner gets married and has a baby. When the family takes a trip to the countryside, nervous Max has numerous run-ins with canine-intolerant cows, hostile foxes and a scary turkey. Luckily for Max, he soon catches a break when he meets Rooster, a gruff farm dog who tries to cure the lovable pooch of his neuroses.', 'Chris Renaud', 86, '2019-05-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/s9xg4V5EDKiphgIksVJ9gewBM11.jpg', 'https://www.youtube.com/watch?v=U_8cQYEXEZE', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (238, 'Pirates of the Caribbean: Dead Men Tell No Tales', 'Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil''s Triangle. Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.', 'Espen Sandberg, Joachim Rønning', 129, '2017-05-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', 'https://www.youtube.com/watch?v=jnVk2C2YrSA', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (239, 'Fantastic Beasts and Where to Find Them', 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.', 'David Yates', 133, '2016-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h6NYfVUyM6CDURtZSnBpz647Ldd.jpg', 'https://www.youtube.com/watch?v=ViuDsy7yb8M', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (240, 'Civil War', 'In the near future, a group of war journalists attempt to survive while reporting the truth as the United States stands on the brink of civil war.', 'Alex Garland', 109, '2024-04-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sh7Rg8Er3tFcN9BpKIPOMvALgZd.jpg', 'https://www.youtube.com/watch?v=aDyQxtg0V2w', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (241, 'The Fall Guy', 'Fresh off an almost career-ending accident, stuntman Colt Seavers has to track down a missing movie star, solve a conspiracy and try to win back the love of his life while still doing his day job.', 'David Leitch', 127, '2024-04-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e7olqFmzcIX5c23kX4zSmLPJi8c.jpg', 'https://www.youtube.com/watch?v=EySdVK0NK1Y', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (242, 'Ant-Man and the Wasp: Quantumania', 'Super-Hero partners Scott Lang and Hope van Dyne, along with with Hope''s parents Janet van Dyne and Hank Pym, and Scott''s daughter Cassie Lang, find themselves exploring the Quantum Realm, interacting with strange new creatures and embarking on an adventure that will push them beyond the limits of what they thought possible.', 'Peyton Reed', 125, '2023-02-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qnqGbB22YJ7dSs4o6M7exTpNxPz.jpg', 'https://www.youtube.com/watch?v=5WfTEZJnv_8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (243, 'Green Book', 'Tony Lip, a bouncer in 1962, is hired to drive pianist Don Shirley on a tour through the Deep South in the days when African Americans, forced to find alternate accommodations and services due to segregation laws below the Mason-Dixon Line, relied on a guide called The Negro Motorist Green Book.', 'Peter Farrelly', 130, '2018-11-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7BsvSuDQuoqhWmU2fL7W2GOcZHU.jpg', 'https://www.youtube.com/watch?v=QkZxoko_HC0', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (244, 'Wicked', 'In the land of Oz, ostracized and misunderstood green-skinned Elphaba is forced to share a room with the popular aristocrat Glinda at Shiz University, and the two''s unlikely friendship is tested as they begin to fulfill their respective destinies as Glinda the Good and the Wicked Witch of the West.', 'Jon M. Chu', 162, '2024-10-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', 'https://www.youtube.com/watch?v=6COmYeLsz4c', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (245, '28 Years Later: The Bone Temple', 'Dr. Kelson finds himself in a shocking new relationship - with consequences that could change the world as they know it - and Spike''s encounter with Jimmy Crystal becomes a nightmare he can''t escape.', 'Nia DaCosta', 109, '2026-01-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kK1BGkG3KAvWB0WMV1DfOx9yTMZ.jpg', 'https://www.youtube.com/watch?v=EOwTdTZA8D8', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (246, 'The Devil''s Mouth', 'A group of college friends'' Thailand adventure turns deadly when they become trapped in submerged caves with a dangerous predator. As oxygen runs low, past conflicts emerge in their desperate fight for survival.', 'Jeff Wadlow', 106, '2026-07-29', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/lH8k9uCWYn2b2gsYleqYBDPbWa8.jpg', 'https://www.youtube.com/watch?v=2bp4Viru6Xc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (247, 'Marty Supreme', 'Marty Mauser, a young man with a dream no one respects, goes to hell and back in pursuit of greatness.', 'Josh Safdie', 150, '2025-12-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg', 'https://www.youtube.com/watch?v=s9gSuKaKcqM', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (248, 'The Equalizer 2', 'Robert McCall, who serves an unflinching justice for the exploited and oppressed, embarks on a relentless, globe-trotting quest for vengeance when his former partner is murdered.', 'Antoine Fuqua', 121, '2018-07-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cQvc9N6JiMVKqol3wcYrGshsIdZ.jpg', 'https://www.youtube.com/watch?v=EiaVnU18pcs', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (249, 'The Flash', 'When his attempt to save his family inadvertently alters the future, Barry Allen becomes trapped in a reality in which General Zod has returned and there are no Super Heroes to turn to. In order to save the world that he is in and return to the future that he knows, Barry''s only hope is to race for his life. But will making the ultimate sacrifice be enough to reset the universe?', 'Andy Muschietti', 144, '2023-06-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rktDFPbfHfUbArZ6OOOKsXcv0Bm.jpg', 'https://www.youtube.com/watch?v=hebWYacbdvc', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (250, 'Companion', 'During a weekend getaway at a secluded lakeside estate, a group of friends finds themselves entangled in a web of secrets, deception, and advanced technology. As tensions rise and loyalties are tested, they uncover unsettling truths about themselves and the world around them.', 'Drew Hancock', 97, '2025-01-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oCoTgC3UyWGfyQ9thE10ulWR7bn.jpg', 'https://www.youtube.com/watch?v=PhcLjiVtgco', 'NOW_SHOWING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (251, 'The Hunger Games: The Ballad of Songbirds & Snakes', '64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.', 'Francis Lawrence', 157, '2023-11-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', 'https://www.youtube.com/watch?v=NxW_X4kzeus', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (252, 'The Conjuring: Last Rites', 'Paranormal investigators Ed and Lorraine Warren take on one last terrifying case involving mysterious entities they must confront.', 'Michael Chaves', 136, '2025-09-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/byWgphT74ClOVa8EOGzYDkl8DVL.jpg', 'https://www.youtube.com/watch?v=bMgfsdYoEEo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (253, 'Final Destination Bloodlines', 'Plagued by a violent recurring nightmare, college student Stefanie heads home to track down the one person who might be able to break the cycle and save her family from the grisly demise that inevitably awaits them all.', 'Adam Stein, Zach Lipovsky', 110, '2025-05-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', 'https://www.youtube.com/watch?v=KnWzz0n60pE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (254, 'Spa Weekend', 'Four lifelong friends realize that somewhere between careers, relationships, families, and everyday responsibilities, they’ve forgotten how to take care of themselves and each other. Burned out and overdue for a break, the women escape to a luxury spa retreat for an unforgettable weekend dedicated to fun, laughter, and a lot of really bad decisions.', 'Jon Lucas, Scott Moore', 97, '2026-08-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uhx4YjT9YbSxrKVE7GWJdjI412J.jpg', 'https://www.youtube.com/watch?v=9p7j3UvpEQQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (255, 'Uncharted', 'A young street-smart, Nathan Drake and his wisecracking partner Victor “Sully” Sullivan embark on a dangerous pursuit of “the greatest treasure never found” while also tracking clues that may lead to Nathan’s long-lost brother.', 'Ruben Fleischer', 116, '2022-02-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rJHC1RUORuUhtfNb4Npclx0xnOf.jpg', 'https://www.youtube.com/watch?v=4wCH1K-ckZw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (256, 'Black Bag', 'When intelligence agent Kathryn Woodhouse is suspected of betraying the nation, her husband – also a legendary agent – faces the ultimate test of whether to be loyal to his marriage, or his country.', 'Steven Soderbergh', 94, '2025-03-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/hHPovtU4b96LHcoeEwRkGHI5btw.jpg', 'https://www.youtube.com/watch?v=Du0Xp8WX_7I', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (257, 'The Naked Gun', 'Only one man has the particular set of skills... to lead Police Squad and save the world: Lt. Frank Drebin Jr. Following in his father''s footsteps, he must solve a murder case to prevent Police Squad from closure.', 'Akiva Schaffer', 85, '2025-07-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rwla9vqzrKVVKVKiOuROTIXGsxj.jpg', 'https://www.youtube.com/watch?v=uLguU7WLreA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (258, 'The Marvels', 'When her duties send her to an anomalous wormhole linked to a Kree revolutionary, Carol''s powers become entangled with that of Jersey City super-fan Kamala Khan, aka Ms. Marvel, and Carol''s estranged niece, now S.A.B.E.R. astronaut Captain Monica Rambeau. Together, this unlikely trio must team up and learn to work in concert to save the universe.', 'Nia DaCosta', 105, '2023-11-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9GBhzXMFjgcZ3FdR9w3bUMMTps5.jpg', 'https://www.youtube.com/watch?v=iuk77TjvfmE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (259, 'X-Men: Apocalypse', 'After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.', 'Bryan Singer', 144, '2016-05-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ikA8UhYdTGpqbatFa93nIf6noSr.jpg', 'https://www.youtube.com/watch?v=COvnHv42T-A', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (260, 'Insidious: The Red Door', 'To put their demons to rest once and for all, Josh Lambert and a college-aged Dalton Lambert must go deeper into The Further than ever before, facing their family''s dark past and a host of new and more horrifying terrors that lurk behind the red door.', 'Patrick Wilson', 107, '2023-07-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/d07phJqCx6z5wILDYqkyraorDPi.jpg', 'https://www.youtube.com/watch?v=ZuQuOnYnr3Q', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (261, 'Frankenstein', 'Dr. Victor Frankenstein, a brilliant but egotistical scientist, brings a creature to life in a monstrous experiment that ultimately leads to the undoing of both the creator and his tragic creation.', 'Guillermo del Toro', 150, '2025-10-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', 'https://www.youtube.com/watch?v=8aulMPhE12g', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (262, 'Little Women', 'Four sisters come of age in America in the aftermath of the Civil War.', 'Greta Gerwig', 135, '2019-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yn5ihODtZ7ofn8pDYfxCmxh8AXI.jpg', 'https://www.youtube.com/watch?v=AST2-4db4ic', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (263, 'Soul', 'Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.', 'Pete Docter', 101, '2020-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hm58Jw4Lw8OIeECIq5qyPYhAeRJ.jpg', 'https://www.youtube.com/watch?v=4TojlZYqPUo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (264, 'Tony', 'A 19-year-old Anthony Bourdain travels to Provincetown and stumbles into the chaotic world of a restaurant kitchen, setting off a summer that will shape the course of his life.', 'Matt Johnson', 107, '2026-08-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uwZF5guNR5EnXkjIVTk4UPTVGiS.jpg', 'https://www.youtube.com/watch?v=k1MVnzd2aVc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (265, 'Anora', 'A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.', 'Sean Baker', 139, '2024-10-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', 'https://www.youtube.com/watch?v=8m6UrWMl18M', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (266, 'Aquaman and the Lost Kingdom', 'Black Manta seeks revenge on Aquaman for his father''s death. Wielding the Black Trident''s power, he becomes a formidable foe. To defend Atlantis, Arthur (Aquaman) forges an alliance with his imprisoned brother. They must protect the kingdom.', 'James Wan', 124, '2023-12-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7lTnXOy0iNtBAdRP3TZvaKJ77F6.jpg', 'https://www.youtube.com/watch?v=4cSkHPW-MPE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (267, 'Ice Road: Vengeance', 'Big rig ice road driver Mike McCann travels to Nepal to scatter his late brother’s ashes on Mt. Everest. While on a packed tour bus traversing the deadly 12,000 ft. terrain of the infamous Road to the Sky, McCann and his mountain guide encounter a group of mercenaries and must fight to save themselves, the busload of innocent travelers, and the local villagers’ homeland.', 'Jonathan Hensleigh', 113, '2025-06-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cQN9rZj06rXMVkk76UF1DfBAico.jpg', 'https://www.youtube.com/watch?v=K6lJh9ADfbQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (268, 'Our Fault', 'Jenna and Lion''s wedding brings about the long-awaited reunion between Noah and Nick after their breakup. Nick''s inability to forgive Noah stands as an insurmountable barrier. He, heir to his grandfather''s businesses, and she, starting her professional life, resist fueling a flame that''s still alive. But now that their paths have crossed again, will love be stronger than resentment?', 'Domingo González', 110, '2025-10-15', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/yzqHt4m1SeY9FbPrfZ0C2Hi9x1s.jpg', 'https://www.youtube.com/watch?v=4ZDvKct1U4s', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (269, 'Barbarian', 'In town for a job interview, a young woman arrives at her Airbnb late at night only to find that it has been mistakenly double-booked and a strange man is already staying there. Against her better judgement, she decides to stay the night anyway.', 'Zach Cregger', 103, '2022-08-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/idT5mnqPcJgSkvpDX7pJffBzdVH.jpg', 'https://www.youtube.com/watch?v=Dr89pmKrqkI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (270, 'Fantastic Beasts: The Secrets of Dumbledore', 'Professor Albus Dumbledore knows the powerful, dark wizard Gellert Grindelwald is moving to seize control of the wizarding world. Unable to stop him alone, he entrusts magizoologist Newt Scamander to lead an intrepid team of wizards and witches. They soon encounter an array of old and new beasts as they clash with Grindelwald''s growing legion of followers.', 'David Yates', 142, '2022-04-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3c5GNLB4yRSLBby0trHoA1DSQxQ.jpg', 'https://www.youtube.com/watch?v=DaM_wL1ZOM4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (271, 'Me Before You', 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.', 'Thea Sharrock', 110, '2016-06-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg', 'https://www.youtube.com/watch?v=T0MmkG_nG1U', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (272, 'Ant-Man and the Wasp', 'Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.', 'Peyton Reed', 119, '2018-07-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cFQEO687n1K6umXbInzocxcnAQz.jpg', 'https://www.youtube.com/watch?v=8_rTIAOohas', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (273, '“Wuthering Heights”', 'Tragedy strikes when Heathcliff falls in love with Catherine Earnshaw, a woman from a wealthy family in 18th-century England.', 'Emerald Fennell', 136, '2026-02-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3YBce6dTh1D5oCMITXk2S5QhPt.jpg', 'https://www.youtube.com/watch?v=3fLCdIYShEQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (274, 'Ready or Not', 'A young bride''s wedding night turns into her worst nightmare when her ridiculously rich in-laws force her to play a gruesome game of hide-and-seek.', 'Matt Bettinelli-Olpin, Tyler Gillett', 96, '2019-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', 'https://www.youtube.com/watch?v=LBwfO9Hj6oQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (275, 'Return to Silent Hill', 'When James receives a mysterious letter from his lost love Mary, he is drawn to Silent Hill—a once-familiar town now consumed by darkness. As he searches for her, James faces monstrous creatures and unravels a terrifying truth that will push him to the edge of his sanity.', 'Christophe Gans', 106, '2026-01-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mdw7bSnE11WpwWf3ViXtnavuqiT.jpg', 'https://www.youtube.com/watch?v=WHz68ffYJ0s', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (276, 'Ford v Ferrari', 'American car designer Carroll Shelby and the British-born driver Ken Miles work together to battle corporate interference, the laws of physics, and their own personal demons to build a revolutionary race car for Ford Motor Company and take on the dominating race cars of Enzo Ferrari at the 24 Hours of Le Mans in France in 1966.', 'James Mangold', 153, '2019-11-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dR1Ju50iudrOh3YgfwkAU1g2HZe.jpg', 'https://www.youtube.com/watch?v=I3h9Z89U9ZA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (277, 'Call Me by Your Name', 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', 'Luca Guadagnino', 132, '2017-10-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gXiE0WveDnT0n5J4sW9TMxXF4oT.jpg', 'https://www.youtube.com/watch?v=Z9AYPxH5NTM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (278, 'The Creator', 'Amid a future war between the human race and the forces of artificial intelligence, a hardened ex-special forces agent grieving the disappearance of his wife, is recruited to hunt down and kill the Creator, the elusive architect of advanced AI who has developed a mysterious weapon with the power to end the war—and mankind itself.', 'Gareth Edwards', 134, '2023-09-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3dSivDtOuyxLDxPH4v2tcNG1fP7.jpg', 'https://www.youtube.com/watch?v=573GCxqkYEg', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (279, 'X', 'In 1979, a group of young filmmakers set out to make an adult film in rural Texas, but when their reclusive, elderly hosts catch them in the act, the cast find themselves fighting for their lives.', 'Ti West', 106, '2022-03-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/lopZSVtXzhFY603E9OqF7O1YKsh.jpg', 'https://www.youtube.com/watch?v=Awg3cWuHfoc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (280, 'The Meg', 'A deep sea submersible pilot revisits his past fears in the Mariana Trench, and accidentally unleashes the seventy foot ancestor of the Great White Shark believed to be extinct.', 'Jon Turteltaub', 113, '2018-08-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/eyWICPcxOuTcDDDbTMOZawoOn8d.jpg', 'https://www.youtube.com/watch?v=X_HfzGwzVP8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (281, 'The Amateur', 'After his life is turned upside down when his wife is killed in a London terrorist attack, a brilliant but introverted CIA decoder takes matters into his own hands when his supervisors refuse to take action.', 'James Hawes', 123, '2025-04-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/SNEoUInCa5fAgwuEBMIMBGvkkh.jpg', 'https://www.youtube.com/watch?v=DCWcK4c-F8Q', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (282, 'Free Guy', 'A bank teller discovers he is actually a background player in an open-world video game, and decides to become the hero of his own story. Now, in a world where there are no limits, he is determined to be the guy who saves his world his way before it''s too late.', 'Shawn Levy', 115, '2021-08-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dxraF0qPr1OEgJk17ltQTO84kQF.jpg', 'https://www.youtube.com/watch?v=JORN2hkXLyM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (283, 'Ready Player One', 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.', 'Steven Spielberg', 140, '2018-03-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', 'https://www.youtube.com/watch?v=1hrwbc5qCZ4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (284, 'Smile 2', 'About to embark on a new world tour, global pop sensation Skye Riley begins experiencing increasingly terrifying and inexplicable events. Overwhelmed by the escalating horrors and the pressures of fame, Skye is forced to face her dark past to regain control of her life before it spirals out of control.', 'Parker Finn', 127, '2024-10-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ht8Uv9QPv9y7K0RvUyJIaXOZTfd.jpg', 'https://www.youtube.com/watch?v=0HY6QFlBzUY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (285, 'Tenet', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.', 'Christopher Nolan', 150, '2020-08-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', 'https://www.youtube.com/watch?v=AZGcmvrTX9M', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (286, 'It Chapter Two', '27 years after overcoming the malevolent supernatural entity Pennywise, the former members of the Losers'' Club, who have grown up and moved away from Derry, are brought back together by a devastating phone call.', 'Andy Muschietti', 169, '2019-09-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zfE0R94v1E8cuKAerbskfD3VfUt.jpg', 'https://www.youtube.com/watch?v=xhJ5P7Up3jA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (287, 'Poor Things', 'Brought back to life by an unorthodox scientist, a young woman runs off with a lawyer on a whirlwind adventure across the continents. Free from the prejudices of her times, she grows steadfast in her purpose to stand for equality and liberation.', 'Yorgos Lanthimos', 141, '2023-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kCGlIMHnOm8JPXq3rXM6c5wMxcT.jpg', 'https://www.youtube.com/watch?v=-EfYJWRw2FM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (288, 'The Conjuring: The Devil Made Me Do It', 'Paranormal investigators Ed and Lorraine Warren encounter what would become one of the most sensational cases from their files. The fight for the soul of a young boy takes them beyond anything they''d ever seen before, to mark the first time in U.S. history that a murder suspect would claim demonic possession as a defense.', 'Michael Chaves', 111, '2021-05-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/xbSuFiJbbBWCkyCCKIMfuDCA4yV.jpg', 'https://www.youtube.com/watch?v=5FEdg3FhiGc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (289, 'Justice League', 'Fuelled by his restored faith in humanity and inspired by Superman''s selfless act, Bruce Wayne and Diana Prince assemble a team of metahumans consisting of Barry Allen, Arthur Curry and Victor Stone to face the catastrophic threat of Steppenwolf and the Parademons who are on the hunt for three Mother Boxes on Earth.', 'Joss Whedon, Zack Snyder', 120, '2017-11-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eifGNCSDuxJeS1loAXil5bIGgvC.jpg', 'https://www.youtube.com/watch?v=3cxixDgHUYw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (290, 'The Little Mermaid', 'The youngest of King Triton’s daughters, and the most defiant, Ariel longs to find out more about the world beyond the sea, and while visiting the surface, falls for the dashing Prince Eric. With mermaids forbidden to interact with humans, Ariel makes a deal with the evil sea witch, Ursula, which gives her a chance to experience life on land, but ultimately places her life – and her father’s crown – in jeopardy.', 'Rob Marshall', 135, '2023-05-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ym1dxyOk4jFcSl4Q2zmRrA5BEEN.jpg', 'https://www.youtube.com/watch?v=0-wPm99PF9U', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (291, 'Play Dirty', 'Expert thief Parker gets a shot at a major heist, but to pull it off he and his team must outsmart a South American dictator, the New York mob, and the world''s richest man.', 'Shane Black', 128, '2025-09-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ovZ0zq0NwRghtWI1oLaM0lWuoEw.jpg', 'https://www.youtube.com/watch?v=6paP2-ry-QY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (292, 'Sing 2', 'Buster and his new cast now have their sights set on debuting a new show at the Crystal Tower Theater in glamorous Redshore City. But with no connections, he and his singers must sneak into the Crystal Entertainment offices, run by the ruthless wolf mogul Jimmy Crystal, where the gang pitches the ridiculous idea of casting the lion rock legend Clay Calloway in their show. Buster must embark on a quest to find the now-isolated Clay and persuade him to return to the stage.', 'Garth Jennings', 110, '2021-12-01', 'K', 'en', 'https://image.tmdb.org/t/p/w500/aWeKITRFbbwY8txG5uCj4rMCfSP.jpg', 'https://www.youtube.com/watch?v=EPZu5MA2uqI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (293, 'The Bride!', 'A lonely Frankenstein travels to 1930s Chicago to ask groundbreaking scientist Dr. Euphronious to create a companion for him. The two revive a murdered young woman and The Bride is born. But what ensues is beyond what either of them imagined.', 'Maggie Gyllenhaal', 127, '2026-03-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lV8YHwGkYZsm6EfIqnhaSz2avKt.jpg', 'https://www.youtube.com/watch?v=-oLJmEFK14k', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (294, 'Five Nights at Freddy''s', 'Recently fired and desperate for work, a troubled young man named Mike agrees to take a position as a night security guard at an abandoned theme restaurant: Freddy Fazbear''s Pizzeria. But he soon discovers that nothing at Freddy''s is what it seems.', 'Emma Tammi', 110, '2023-10-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/7BpNtNfxuocYEVREzVMO75hso1l.jpg', 'https://www.youtube.com/watch?v=9fJtM5z0g7M', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (295, 'Your Fault', 'The love between Noah and Nick seems unwavering despite their parents'' attempts to separate them. But his job and her entry into college open up their lives to new relationships that will shake the foundations of both their relationship and the Leister family itself.', 'Domingo González', 117, '2024-12-26', 'P', 'es', 'https://image.tmdb.org/t/p/w500/1sQA7lfcF9yUyoLYC0e6Zo3jmxE.jpg', 'https://www.youtube.com/watch?v=QT5j0Uf-rdM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (296, 'Nosferatu', 'A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.', 'Robert Eggers', 133, '2024-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5qGIxdEO841C0tdY8vOdLoRVrr0.jpg', 'https://www.youtube.com/watch?v=b59rxDB_JRg', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (297, '365 Days: This Day', 'Laura and Massimo are back and hotter than ever. But the reunited couple''s new beginning is complicated by Massimo’s family ties and a mysterious man who enters Laura’s life to win her heart and trust, at any cost.', 'Barbara Białowąs, Tomasz Mandes', 110, '2022-04-26', 'P', 'pl', 'https://image.tmdb.org/t/p/w500/7qU0SOVcQ8BTJLodcAlulUAG16C.jpg', 'https://www.youtube.com/watch?v=pyM3z73oMAk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (298, 'The Lion King', 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub''s arrival. Scar, Mufasa''s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba''s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.', 'Jon Favreau', 118, '2019-07-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dzBtMocZuJbjLOXvrl4zGYigDzh.jpg', 'https://www.youtube.com/watch?v=7TavVZMewpY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (299, 'Bad Boys: Ride or Die', 'After their late former Captain is framed, Lowrey and Burnett try to clear his name, only to end up on the run themselves.', 'Adil El Arbi, Bilall Fallah', 116, '2024-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oGythE98MYleE6mZlGs5oBGkux1.jpg', 'https://www.youtube.com/watch?v=ZTQyMmz-cQE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (300, 'Bring Her Back', 'Following the death of their father, a brother and sister are sent to live with a foster mother, only to learn that she is hiding a terrifying secret.', 'Danny Philippou, Michael Philippou', 104, '2025-05-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/1Q3GlCXGYWELifxANYZ5OVMRVZl.jpg', 'https://www.youtube.com/watch?v=1I15ttCedfY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
