INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (301, 'The Monkey', 'When twin brothers find a mysterious wind-up monkey, a series of outrageous deaths tear their family apart. Twenty-five years later, the monkey begins a new killing spree forcing the estranged brothers to confront the cursed toy.', 'Osgood Perkins', 97, '2025-02-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aGDekyIb0yfmnuLZciCozRPk2TE.jpg', 'https://www.youtube.com/watch?v=KPxmK_ihDO8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (302, 'The Nun', 'A priest with a dark past and a novice nearing her final vows are sent by the Vatican to Romania to investigate a nun''s death and face a demonic force.', 'Corin Hardy', 96, '2018-09-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sFC1ElvoKGdHJIWRpNB3xWJ9lJA.jpg', 'https://www.youtube.com/watch?v=UvMVjwwZOF4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (303, 'xXx: Return of Xander Cage', 'Xander Cage is left for dead after an incident, though he secretly returns to action for a new, tough assignment with his handler Augustus Gibbons.', 'D.J. Caruso', 107, '2017-01-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hba8zREJpP1AYhaXgb2oJLQeO0K.jpg', 'https://www.youtube.com/watch?v=-ziu6JzJTZ0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (304, 'Now You See Me 2', 'One year after outwitting the FBI and winning the public’s adulation with their mind-bending spectacles, the Four Horsemen resurface only to find themselves face to face with a new enemy who enlists them to pull off their most dangerous heist yet.', 'Jon M. Chu', 129, '2016-06-02', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/A81kDB6a1K86YLlcOtZB27jriJh.jpg', 'https://www.youtube.com/watch?v=AuEjHzOIgBE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (305, 'Dark Phoenix', 'The X-Men face their most formidable and powerful foe when one of their own, Jean Grey, starts to spiral out of control. During a rescue mission in outer space, Jean is nearly killed when she''s hit by a mysterious cosmic force. Once she returns home, this force not only makes her infinitely more powerful, but far more unstable. The X-Men must now band together to save her soul and battle aliens that want to use Grey''s new abilities to rule the galaxy.', 'Simon Kinberg', 114, '2019-06-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cCTJPelKGLhALq3r51A9uMonxKj.jpg', 'https://www.youtube.com/watch?v=1-q8C_c-nlM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (306, 'The Mummy', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', 'Alex Kurtzman', 110, '2017-06-06', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg', 'https://www.youtube.com/watch?v=GzorZUuZqEI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (307, 'Pressure', 'In the tense 72 hours before D-Day, and the fate of the free world hanging in the balance, General Dwight D. Eisenhower and Captain James Stagg face an impossible choice—launch the largest and most dangerous seaborne invasion in history or risk losing the war altogether.', 'Anthony Maras', 101, '2026-05-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gFjEggtrejCN79r6SXRjM269OtG.jpg', 'https://www.youtube.com/watch?v=EBh1LGRwiis', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (308, 'Wonder Woman', 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.', 'Patty Jenkins', 141, '2017-05-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', 'https://www.youtube.com/watch?v=1Q8fG0TtVAY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (309, 'Heads of State', 'The UK Prime Minister and US President have a public rivalry that risks their countries'' alliance. But when they become targets of a powerful enemy, they''re forced to rely on each other as they go on a wild, multinational run. Allied with Noel, a brilliant MI6 agent, they must find a way to thwart a conspiracy that threatens the free world.', 'Ilya Naishuller', 117, '2025-06-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lVgE5oLzf7ABmzyASEVcjYyHI41.jpg', 'https://www.youtube.com/watch?v=8J646zM7UM8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (310, 'Super Troopers 3', 'When Farva’s wildly over-the-top Indian engagement to Thorny’s sister spirals into chaos, the Super Troopers must navigate Thorny’s schemes to break up the relationship, while trying to crack a pernicious new drug ring — all to save the day and maybe the wedding itself.', 'Jay Chandrasekhar', 104, '2026-08-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/VVU42nqsEmUtFpH1d9MHj5BIpF.jpg', 'https://www.youtube.com/watch?v=cYFevn5frf0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (311, 'Passenger', 'After a young couple witnesses a gruesome highway accident, they soon realize they did not leave the crash scene alone, as a demonic presence called the Passenger that won''t stop until it claims them both turns their van life adventure into a nightmare.', 'André Øvredal', 94, '2026-05-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/svrAzMTif4OmIjGJzC0W92d5O1o.jpg', 'https://www.youtube.com/watch?v=eNIn8kW1kyE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (312, 'Midsommar', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', 'Ari Aster', 147, '2019-07-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'https://www.youtube.com/watch?v=1Vnghdsjmd0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (313, 'Hokum', 'When novelist Ohm Bauman retreats to a remote inn to scatter his parents'' ashes, he is consumed by tales of a witch haunting the honeymoon suite. Disturbing visions and a shocking disappearance forces him to confront dark corners of his past.', 'Damian McCarthy', 108, '2026-04-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/x6rHcQFiYcczLQPrmxXPAicm54E.jpg', 'https://www.youtube.com/watch?v=jP2nDyQWBOU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (314, 'Karate Kid: Legends', 'After a family tragedy, kung fu prodigy Li Fong is uprooted from his home in Beijing and forced to move to New York City with his mother. When a new friend needs his help, Li enters a karate competition – but his skills alone aren''t enough. Li''s kung fu teacher Mr. Han enlists original Karate Kid Daniel LaRusso for help, and Li learns a new way to fight, merging their two styles into one for the ultimate martial arts showdown.', 'Jonathan Entwistle', 94, '2025-05-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/c90Lt7OQGsOmhv6x4JoFdoHzw5l.jpg', 'https://www.youtube.com/watch?v=LhRXf-yEQqA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (315, 'Encanto', 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family''s last hope.', 'Byron Howard, Jared Bush', 102, '2021-10-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', 'https://www.youtube.com/watch?v=CaimKeDcudo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (316, 'A Star Is Born', 'Seasoned musician Jackson Maine discovers — and falls in love with — struggling artist Ally. She has just about given up on her dream to make it big as a singer — until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', 'Bradley Cooper', 136, '2018-10-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', 'https://www.youtube.com/watch?v=-KT3J1VsMec', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (317, 'Trolls World Tour', 'Queen Poppy and Branch make a surprising discovery — there are other Troll worlds beyond their own, and their distinct differences create big clashes between these various tribes. When a mysterious threat puts all of the Trolls across the land in danger, Poppy, Branch, and their band of friends must embark on an epic quest to create harmony among the feuding Trolls to unite them against certain doom.', 'Walt Dohrn', 91, '2020-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7W0G3YECgDAfnuiHG91r8WqgIOe.jpg', 'https://www.youtube.com/watch?v=08AExF6dETA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (318, 'The Greatest Showman', 'The story of American showman P.T. Barnum, founder of the circus that became the famous traveling Ringling Bros. and Barnum & Bailey Circus.', 'Michael Gracey', 105, '2017-12-20', 'K', 'en', 'https://image.tmdb.org/t/p/w500/b9CeobiihCx1uG1tpw8hXmpi7nm.jpg', 'https://www.youtube.com/watch?v=EodWwczRIe4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (319, 'The Accountant²', 'When an old acquaintance is murdered, Wolff is compelled to solve the case. Realizing more extreme measures are necessary, Wolff recruits his estranged and highly lethal brother, Brax, to help. In partnership with Marybeth Medina, they uncover a deadly conspiracy, becoming targets of a ruthless network of killers who will stop at nothing to keep their secrets buried.', 'Gavin O''Connor', 133, '2025-04-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lUvfTcOZiK0sdcX0WNLPbMyKjGm.jpg', 'https://www.youtube.com/watch?v=3wRCOqyDI6E', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (320, 'Nobody 2', 'Former assassin Hutch Mansell takes his family on a nostalgic vacation to a small-town theme park, only to be pulled back into violence when they clash with a corrupt operator, a crooked sheriff, and a ruthless crime boss.', 'Timo Tjahjanto', 89, '2025-08-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/svXVRoRSu6zzFtCzkRsjZS7Lqpd.jpg', 'https://www.youtube.com/watch?v=-5X2pt95cIo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (321, 'Death on the Nile', 'Belgian sleuth Hercule Poirot''s Egyptian vacation aboard a glamorous river steamer turns into a terrifying search for a murderer when a picture-perfect couple''s idyllic honeymoon is tragically cut short.', 'Kenneth Branagh', 127, '2022-02-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kVr5zIAFSPRQ57Y1zE7KzmhzdMQ.jpg', 'https://www.youtube.com/watch?v=JM1U-Whb-P0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (322, 'Beetlejuice Beetlejuice', 'After a family tragedy, three generations of the Deetz family return home to Winter River. Still haunted by Betelgeuse, Lydia''s life is turned upside down when her teenage daughter, Astrid, accidentally opens the portal to the Afterlife.', 'Tim Burton', 105, '2024-09-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kKgQzkUCnQmeTPkyIwHly2t6ZFI.jpg', 'https://www.youtube.com/watch?v=As-vKW4ZboU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (323, 'Toxic: A Fairy Tale for Grown-ups', 'A powerful drug cartel pulls the strings behind a facade of sun-soaked beaches as a gritty, violent underworld power struggle emerges during the crumbling of Portuguese colonial rule.', 'Geetu Mohandas', 192, '2026-08-26', 'T16', 'kn', 'https://image.tmdb.org/t/p/w500/tZ8eSBXbza96vzCYeVTG9RBJ78E.jpg', 'https://www.youtube.com/watch?v=EfluEyQ5QIA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (324, 'Dungeons & Dragons: Honor Among Thieves', 'A charming thief and a band of unlikely adventurers undertake an epic heist to retrieve a lost relic, but things go dangerously awry when they run afoul of the wrong people.', 'John Francis Daley, Jonathan Goldstein', 134, '2023-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v7UF7ypAqjsFZFdjksjQ7IUpXdn.jpg', 'https://www.youtube.com/watch?v=9LLOLEBlVIA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (325, 'The Legend of Ochi', 'In a remote village on the island of Carpathia, a shy farm girl named Yuri is raised to fear an elusive animal species known as ochi. But when Yuri discovers a wounded baby ochi has been left behind, she escapes on a quest to bring him home.', 'Isaiah Saxon', 95, '2025-04-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qYyEelO4JfOwE0Ui5KsrCE0O8UA.jpg', 'https://www.youtube.com/watch?v=_jTFLg3arYU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (326, 'Eternals', 'The Eternals are a team of ancient aliens who have been living on Earth in secret for thousands of years. When an unexpected tragedy forces them out of the shadows, they are forced to reunite against mankind’s most ancient enemy, the Deviants.', 'Chloé Zhao', 156, '2021-11-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/lFByFSLV5WDJEv3KabbdAF959F2.jpg', 'https://www.youtube.com/watch?v=0WVDKZJkGlY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (327, 'The Get Out', 'A nightclub owner is on the verge of leaving his dangerous past behind for retirement with his girlfriend. When masked gunmen rob him and he finds himself squeezed by ruthless cartels, a mysterious newcomer arrives with an interest in buying the business. With danger closing in from all sides, he must navigate a deadly web of deception, power, and survival - where escape may no longer be an option.', 'Derrick Borte', 111, '2026-06-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zlkeH0s7dDxcnuPcHBqAyXFUxqN.jpg', 'https://www.youtube.com/watch?v=oB6HNuKxLmo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (328, 'War for the Planet of the Apes', 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind. As the journey finally brings them face to face, Caesar and the Colonel are pitted against each other in an epic battle that will determine the fate of both their species and the future of the planet.', 'Matt Reeves', 140, '2017-07-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3vYhLLxrTtZLysXtIWktmd57Snv.jpg', 'https://www.youtube.com/watch?v=1TxqmlIv1Iw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (329, 'Bohemian Rhapsody', 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock ''n'' roll band Queen in 1970. Hit songs become instant classics. When Mercury''s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.', 'Bryan Singer', 135, '2018-10-24', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', 'https://www.youtube.com/watch?v=27zlBpzdOZg', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (330, 'Kingsman: The Golden Circle', 'When an attack on the Kingsman headquarters takes place and a new villain rises, Eggsy and Merlin are forced to work together with the American agency known as the Statesman to save the world.', 'Matthew Vaughn', 141, '2017-09-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', 'https://www.youtube.com/watch?v=0fvqnGmr9S8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (331, 'Venom: Let There Be Carnage', 'After finding a host body in investigative reporter Eddie Brock, the alien symbiote must face a new enemy, Carnage, the alter ego of serial killer Cletus Kasady.', 'Andy Serkis', 97, '2021-09-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pzKsRuKLFmYrW5Q0q8E8G78Tcgo.jpg', 'https://www.youtube.com/watch?v=-FmWuCgJmxo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (332, 'Scream VI', 'Following the latest Ghostface killings, the four survivors leave Woodsboro behind and start a fresh chapter.', 'Matt Bettinelli-Olpin, Tyler Gillett', 123, '2023-03-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wDWwtvkRRlgTiUr6TyLSMX8FCuZ.jpg', 'https://www.youtube.com/watch?v=1Ie2qmAOc6Q', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (333, 'Insidious: The Last Key', 'Parapsychologist Elise Rainier and her team travel to Five Keys, NM, to investigate a man’s claim of a haunting. Terror soon strikes when Rainier realizes that the house he lives in was her family’s old home.', 'Adam Robitel', 103, '2018-01-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6c9ti2JcR3dHyR3qFXoZqVMx0SH.jpg', 'https://www.youtube.com/watch?v=acQyrwQyCOk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (334, 'Bad Boys for Life', 'Marcus and Mike are forced to confront new threats, career changes, and midlife crises as they join the newly created elite team AMMO of the Miami police department to take down the ruthless Armando Armas, the vicious leader of a Miami drug cartel.', 'Adil El Arbi, Bilall Fallah', 124, '2020-01-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/y95lQLnuNKdPAzw9F9Ab8kJ80c3.jpg', 'https://www.youtube.com/watch?v=R228yPrwqTo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (335, 'Despicable Me 3', 'Gru and his wife Lucy must stop former ''80s child star Balthazar Bratt from achieving world domination.', 'Kyle Balda, Pierre Coffin', 90, '2017-06-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg', 'https://www.youtube.com/watch?v=6DBi41reeF0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (336, 'Glass Onion: A Knives Out Mystery', 'World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.', 'Rian Johnson', 140, '2022-11-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg', 'https://www.youtube.com/watch?v=-xR_lBtEvSc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (337, 'Jackass: Best and Last', 'The fifth and final installment to Jackass franchise where the crew go on one last insane crusade.', 'Jeff Tremaine', 92, '2026-06-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/tfgccePxnswMqhmtxafliLlcCVR.jpg', 'https://www.youtube.com/watch?v=sNwzFhGwA94', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (338, 'The Accountant', 'As a math savant uncooks the books for a new client, the Treasury Department closes in on his activities and the body count starts to rise.', 'Gavin O''Connor', 128, '2016-10-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fceheXB5fC4WrLVuWJ6OZv9FXYr.jpg', 'https://www.youtube.com/watch?v=0KHOVlEpMyY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (339, 'The Nun II', 'In 1956 France, a priest is violently murdered, and Sister Irene begins to investigate. She once again comes face-to-face with a powerful evil.', 'Michael Chaves', 110, '2023-09-06', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5gzzkR7y3hnY8AD1wXjCnVlHba5.jpg', 'https://www.youtube.com/watch?v=QF-oyCwaArU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (340, 'Voicemails for Isabelle', 'A young woman''s hilariously confessional voicemails to her late sister are unknowingly redirected to a stranger, who begins to fall in love from afar.', 'Leah McKendrick', 119, '2026-06-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/canZTWSxACSnAluir3dCtMxKpA1.jpg', 'https://www.youtube.com/watch?v=9mi3YVYm3ZU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (341, 'Subservience', 'With his wife out sick, a struggling father brings home a lifelike AI, only to have his self-aware new help want everything her new family has to offer... Like the affection of her owner and she''ll kill to get it.', 'S.K. Dale', 105, '2024-08-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gBenxR01Uy0Ev9RTIw6dVBPoyQU.jpg', 'https://www.youtube.com/watch?v=z6DLdqf0Bs0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (342, 'Jumanji: The Next Level', 'As the gang return to Jumanji to rescue one of their own, they discover that nothing is as they expect. The players will have to brave parts unknown and unexplored in order to escape the world’s most dangerous game.', 'Jake Kasdan', 123, '2019-12-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jyw8VKYEiM1UDzPB7NsisUgBeJ8.jpg', 'https://www.youtube.com/watch?v=F6QaLsw8EWY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (343, 'Nobody', 'Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a "nobody." When two thieves break into his home one night, Hutch''s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind.', 'Ilya Naishuller', 91, '2021-03-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg', 'https://www.youtube.com/watch?v=wZti8QKBWPo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (344, 'The Idea of You', '40-year-old single mom Solène begins an unexpected romance with 24-year-old Hayes Campbell, the lead singer of August Moon, the hottest boy band on the planet. As they begin a whirlwind romance, it isn''t long before Hayes'' superstar status poses unavoidable challenges to their relationship, and Solène soon discovers that life in the glare of his spotlight might be more than she bargained for.', 'Michael Showalter', 116, '2024-05-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/Y5P4Q3q8nrruZ9aD3wXeJS2Plg.jpg', 'https://www.youtube.com/watch?v=pz6qx4n2Ewc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (345, 'Hereditary', 'Following the death of the Leigh family matriarch, Annie and her children uncover disturbing secrets about their heritage. Their daily lives are not only impacted, but they also become entangled in a chilling fate from which they cannot escape, driving them to the brink of madness.', 'Ari Aster', 128, '2018-06-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4GFPuL14eXi66V96xBWY73Y9PfR.jpg', 'https://www.youtube.com/watch?v=MJNR58zaStE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (346, 'The Jungle Book', 'After a threat from the tiger Shere Khan, Mowgli, a man-cub fostered by wolves, is forced to flee the jungle, and he embarks on a journey of self-discovery with the help of the panther, Bagheera, and the free-spirited bear, Baloo.', 'Jon Favreau', 106, '2016-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2Epx7F9X7DrFptn4seqn4mzBVks.jpg', 'https://www.youtube.com/watch?v=YW97nCUE3ZA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (347, 'Elemental', 'In a city where fire, water, land and air residents live together, a fiery young woman and a go-with-the-flow guy will discover something elemental: how much they have in common.', 'Peter Sohn', 102, '2023-06-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4Y1WNkd88JXmGfhtWR7dmDAo1T2.jpg', 'https://www.youtube.com/watch?v=-cT495xKvvs', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (348, 'Challengers', 'Tennis player turned coach Tashi has taken her husband, Art, and transformed him into a world-famous Major champion. To jolt him out of his recent losing streak, she signs him up for a "Challenger" event — close to the lowest level of pro tournament — where he finds himself standing across the net from his former best friend and Tashi''s former boyfriend.', 'Luca Guadagnino', 132, '2024-04-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/H6vke7zGiuLsz4v4RPeReb9rsv.jpg', 'https://www.youtube.com/watch?v=-2N3hmRmwHQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (349, 'Baby Driver', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.', 'Edgar Wright', 113, '2017-06-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', 'https://www.youtube.com/watch?v=YR8cerFfWZo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (350, 'Don''t Look Up', 'Two astronomers go on a media tour to warn humankind of a planet-killing comet hurtling toward Earth. The response from a distracted world: Meh.', 'Adam McKay', 138, '2021-12-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/th4E1yqsE8DGpAseLiUrI60Hf8V.jpg', 'https://www.youtube.com/watch?v=RbIxYm3mKzI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
