  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (351, 'Terminator: Dark Fate', 'Decades after Sarah Connor prevented Judgment Day, a lethal new Terminator is sent to eliminate the future leader of the resistance. In a fight to save mankind, battle-hardened Sarah Connor teams up with an unexpected ally and an enhanced super soldier to stop the deadliest Terminator yet.', 'Tim Miller', 128, '2019-10-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vqzNJRH4YyquRiWxCCOH0aXggHI.jpg', 'https://www.youtube.com/watch?v=8CjYw1hARhY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (352, 'Aftersun', 'Sophie reflects on the shared joy and private melancholy of a holiday she took with her father twenty years earlier. Memories fill the gaps between camcorder footages as she tries to reconcile the father she knew with the troubled man she didn''t.', 'Charlotte Wells', 101, '2022-10-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/evKz85EKouVbIr51zy5fOtpNRPg.jpg', 'https://www.youtube.com/watch?v=4A34B1DIGl8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (353, 'Mission: Impossible - Fallout', 'When an IMF mission ends badly, the world is faced with dire consequences. As Ethan Hunt takes it upon himself to fulfill his original briefing, the CIA begin to question his loyalty and his motives. The IMF team find themselves in a race against time, hunted by assassins while trying to prevent a global catastrophe.', 'Christopher McQuarrie', 147, '2018-07-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AkJQpZp9WoNdj7pLYSj1L0RcMMN.jpg', 'https://www.youtube.com/watch?v=MEOOas3JZt0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (354, 'The King''s Man', 'As a collection of history''s worst tyrants and criminal masterminds gather to plot a war to wipe out millions, one man must race against time to stop them.', 'Matthew Vaughn', 131, '2021-12-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iMjSfMUuCkCE7z5fzGtjeDusPD3.jpg', 'https://www.youtube.com/watch?v=0pbLPOrTSsI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (355, 'Descendants: Wicked Wonderland', 'Now that the Queen of Hearts is nice and Cinderella is safe, things seem perfect for Red and Chloe… But little do they know that changing the past created a new villain — Maddox Hatter. When Maddox captures the Queen of Hearts, Red and Chloe must work alongside Red’s new sister Pink, Luisa Madrigal’s son Luis, and Maddox’s son Max to save her and Wonderland.', 'Kimmy Gatewood', 98, '2026-07-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xdhLAADGSse8KCrsDLBuM5b68Cg.jpg', 'https://www.youtube.com/watch?v=0Gg7x3xBqBU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (356, 'Kong: Skull Island', 'Explore the mysterious and dangerous home of the king of the apes as a team of explorers ventures deep inside the treacherous, primordial island.', 'Jordan Vogt-Roberts', 118, '2017-03-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/r2517Vz9EhDhj88qwbDVj8DCRZN.jpg', 'https://www.youtube.com/watch?v=44LdLqgOpjo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (357, 'Venom', 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.', 'Ruben Fleischer', 112, '2018-09-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'https://www.youtube.com/watch?v=27ykcO79F-Y', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (358, 'The Long Walk', 'In a dystopian 1970s America, fifty teenage boys take part in a deadly annual walking contest, forced to maintain a minimum pace or be executed, until only one survivor remains.', 'Francis Lawrence', 108, '2025-09-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wobVTa99eW0ht6c1rNNzLkazPtR.jpg', 'https://www.youtube.com/watch?v=Toj3Zxun7aQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (359, 'Blue Moon', 'On the evening of March 31, 1943, legendary lyricist Lorenz Hart confronts his shattered self-confidence in Sardi’s bar as his former collaborator, Richard Rodgers, celebrates the opening night of his ground-breaking hit musical, “Oklahoma!”', 'Richard Linklater', 101, '2025-10-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dVU7SNc6dgStTVdtbPLQncWxsyZ.jpg', 'https://www.youtube.com/watch?v=qo7gRHip0lI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (360, 'Smile', 'After witnessing a bizarre, traumatic incident involving a patient, Dr. Rose Cotter starts experiencing frightening occurrences that she can''t explain.', 'Parker Finn', 115, '2022-09-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/aPqcQwu4VGEewPhagWNncDbJ9Xp.jpg', 'https://www.youtube.com/watch?v=-8d987Wtkxs', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (361, 'Godzilla: King of the Monsters', 'Follows the heroic efforts of the crypto-zoological agency Monarch as its members face off against a battery of god-sized monsters, including the mighty Godzilla, who collides with Mothra, Rodan, and his ultimate nemesis, the three-headed King Ghidorah. When these ancient super-species, thought to be mere myths, rise again, they all vie for supremacy, leaving humanity''s very existence hanging in the balance.', 'Michael Dougherty', 132, '2019-05-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mzOHg7Q5q9yUmY0b9Esu8Qe6Nnm.jpg', 'https://www.youtube.com/watch?v=KDnKuFtdc7A', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (362, 'Wake Up Dead Man: A Knives Out Mystery', 'When young priest Jud Duplenticy is sent to assist charismatic firebrand Monsignor Jefferson Wicks, it’s clear that all is not well in the pews. After a sudden and seemingly impossible murder rocks the town, the lack of an obvious suspect prompts local police chief Geraldine Scott to join forces with renowned detective Benoit Blanc to unravel a mystery that defies all logic.', 'Rian Johnson', 145, '2025-11-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iV9LM8aUb83BjCCx2RUnKE5sSQg.jpg', 'https://www.youtube.com/watch?v=0hc8yz5-d5Y', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (363, 'The Northman', 'Prince Amleth is on the verge of becoming a man when his father is brutally murdered by his uncle, who kidnaps the boy''s mother. Two decades later, Amleth is now a Viking who''s on a mission to save his mother, kill his uncle and avenge his father.', 'Robert Eggers', 137, '2022-04-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aSSJMnHknzKjlZ6zybwD7eyJ4Po.jpg', 'https://www.youtube.com/watch?v=6WrpvCmv0hk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (364, 'The Master and Margarita', 'A struggling writer in 1930s Soviet Moscow finds his life transformed when a mysterious professor arrives with his bizarre entourage, including a wisecracking trickster, a deadly assassin, a vampire maid, and a giant talking black cat, turning the city upside down while exposing the hypocrisy of those in power.', 'Michael Lockshin', 157, '2024-01-25', 'T13', 'ru', 'https://image.tmdb.org/t/p/w500/jw172VAlwfYtWNWvhVrXZPW3jGT.jpg', 'https://www.youtube.com/watch?v=4ms2zEv1xH4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (365, 'It', 'In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.', 'Andy Muschietti', 135, '2017-09-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg', 'https://www.youtube.com/watch?v=FnCdOQsX5kc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (366, 'Minions: The Rise of Gru', 'A fanboy of a supervillain supergroup known as the Vicious 6, Gru hatches a plan to become evil enough to join them, with the backup of his followers, the Minions.', 'Kyle Balda', 87, '2022-06-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wKiOkZTN9lUUUNZLmtnwubZYONg.jpg', 'https://www.youtube.com/watch?v=6DxjJzmYsXo', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (367, 'Red, White & Royal Blue', 'After an altercation between Alex, the president''s son, and Britain''s Prince Henry at a royal event becomes tabloid fodder, their long-running feud now threatens to drive a wedge in U.S./British relations. When the rivals are forced into a staged truce, their icy relationship begins to thaw and the friction between them sparks something deeper than they ever expected.', 'Matthew López', 118, '2023-07-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dD3vhyDRCCT90hf4rldHU6Wu3Va.jpg', 'https://www.youtube.com/watch?v=pt56IC8gDZ4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (368, 'Elio', 'Elio, a space fanatic with an active imagination, finds himself on a cosmic misadventure where he must form new bonds with eccentric alien lifeforms, navigate a crisis of intergalactic proportions and somehow discover who he is truly meant to be.', 'Adrian Molina, Domee Shi, Madeline Sharafian', 98, '2025-06-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7z8jDiTZZco9moIKpTUImFtTy7o.jpg', 'https://www.youtube.com/watch?v=2w_K3CB8PuE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (369, 'Over Your Dead Body', 'A dysfunctional couple head to a remote cabin to "reconnect", but each has secret intentions to kill the other.', 'Jorma Taccone', 105, '2026-03-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kZCauMzAt9eMAhLMopCqnFw1Q5k.jpg', 'https://www.youtube.com/watch?v=pGxKTIegUZ4', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (370, 'Alita: Battle Angel', 'When Alita awakens with no memory of who she is in a future world she does not recognize, she is taken in by Ido, a compassionate doctor who realizes that somewhere in this abandoned cyborg shell is the heart and soul of a young woman with an extraordinary past.', 'Robert Rodriguez', 122, '2019-01-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xRWht48C2V8XNfzvPehyClOvDni.jpg', 'https://www.youtube.com/watch?v=U3D2vmWD88w', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (371, 'TRON: Ares', 'A highly sophisticated Program called Ares is sent from the digital world into the real world on a dangerous mission, marking humankind''s first encounter with A.I. beings.', 'Joachim Rønning', 119, '2025-10-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/chpWmskl3aKm1aTZqUHRCtviwPy.jpg', 'https://www.youtube.com/watch?v=9KVG_X_7Naw', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (372, 'Prey', 'When danger threatens her camp, the fierce and highly skilled Comanche warrior Naru sets out to protect her people. But the prey she stalks turns out to be a highly evolved alien predator with a technically advanced arsenal.', 'Dan Trachtenberg', 100, '2022-08-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2FKjLRt7oK1bRRIrxgWmthbBdFh.jpg', 'https://www.youtube.com/watch?v=wZ7LytagKlc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (373, 'Deep Cover', 'Kat is an improv comedy teacher beginning to question if she’s missed her shot at success. When an undercover cop offers her the role of a lifetime, she recruits two of her students to infiltrate London’s gangland by impersonating dangerous criminals.', 'Tom Kingsley', 99, '2025-06-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/yYfaChljpg6eo9ZlFyTmI81PMZC.jpg', 'https://www.youtube.com/watch?v=1x--MaHsbEc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (374, 'Good Luck, Have Fun, Don''t Die', 'A ''Man from the Future'' arrives at an LA diner where he must recruit the precise combination of disgruntled patrons to join him on a one-night quest to save the world from the terminal threat of a rogue artificial intelligence.', 'Gore Verbinski', 134, '2026-02-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rWcfOdY7TU6lTdazWj0ebDZnAfO.jpg', 'https://www.youtube.com/watch?v=CaSxNAZUKsM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (375, 'Anyone but You', 'After an amazing first date, Bea and Ben’s fiery attraction turns ice cold — until they find themselves unexpectedly reunited at a destination wedding in Australia. So they do what any two mature adults would do: pretend to be a couple.', 'Will Gluck', 103, '2023-12-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5qHoazZiaLe7oFBok7XlUhg96f2.jpg', 'https://www.youtube.com/watch?v=UtjH6Sk7Gxs', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (376, 'The Mitchells vs. the Machines', 'A quirky, dysfunctional family''s road trip is upended when they find themselves in the middle of the robot apocalypse and suddenly become humanity''s unlikeliest last hope.', 'Mike Rianda', 110, '2021-04-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/mI2Di7HmskQQ34kz0iau6J1vr70.jpg', 'https://www.youtube.com/watch?v=9c52Z5sMuTQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (377, 'The Grinch', 'The Grinch hatches a scheme to ruin Christmas when the residents of Whoville plan their annual holiday celebration. But a certain little who might change things.', 'Scott Mosier, Yarrow Cheney', 85, '2018-11-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/Al7DMUp8bqUN4JwXVNxfJYyv5cH.jpg', 'https://www.youtube.com/watch?v=L8LWUyUy7jM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (378, 'Exit 8', 'A man trapped in an endless sterile subway passageway sets out to find Exit 8. The rules of his quest are simple: do not overlook anything out of the ordinary. If you discover an anomaly, turn back immediately. If you don’t, carry on. Then leave from Exit 8. But even a single oversight will send him back to the beginning. Will he ever reach his goal and escape this infinite corridor?', 'Genki Kawamura', 95, '2025-08-03', 'T18', 'ja', 'https://image.tmdb.org/t/p/w500/nQXYTvm6AY4WmtcPskroqC7Skh.jpg', 'https://www.youtube.com/watch?v=DlRQ1oatOt8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (379, 'Ghostbusters: Afterlife', 'When single mom Callie and her two kids Trevor and Phoebe arrive in a small Oklahoma town, they begin to discover their connection to the original Ghostbusters and the secret legacy their grandfather left behind.', 'Jason Reitman', 124, '2021-11-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sg4xJaufDiQl7caFEskBtQXfD4x.jpg', 'https://www.youtube.com/watch?v=G_ua10EMbSg', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (380, 'Mercy', 'In the near future, a detective stands on trial accused of murdering his wife. He has ninety minutes to prove his innocence to the advanced AI Judge he once championed, before it determines his fate.', 'Timur Bekmambetov', 100, '2026-01-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pyok1kZJCfyuFapYXzHcy7BLlQa.jpg', 'https://www.youtube.com/watch?v=7H7Djx17l8Y', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (381, 'Extraction 2', 'Back from the brink of death, highly skilled commando Tyler Rake takes on another dangerous mission: saving the imprisoned family of a ruthless gangster.', 'Sam Hargrave', 122, '2023-06-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7gKI9hpEMcZUQpNgKrkDzJpbnNS.jpg', 'https://www.youtube.com/watch?v=Y274jZs5s7s', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (382, 'Ne Zha', 'A young boy is born as the reincarnation of a demonic power, into a society that hates and fears him. Destined by prophecy to bring destruction to the world, Nezha must choose between good and evil to see if he can change his fate.', 'Jiao Zi', 110, '2019-07-26', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/phM9bb6s9c60LA8qwsdk7U1N2cS.jpg', 'https://www.youtube.com/watch?v=0S7_LgTiHnA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (383, 'Godzilla Minus One', 'In postwar Japan, Godzilla brings new devastation to an already scorched landscape. With no military intervention or government help in sight, the survivors must join together in the face of despair and fight back against an unrelenting horror.', 'Takashi Yamazaki', 125, '2023-11-03', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/2E2WTX0TJEflAged6kzErwqX1kt.jpg', 'https://www.youtube.com/watch?v=MSp68m8OJus', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (384, 'The Gangster, the Cop, the Devil', 'After barely surviving a brutal attack by a sadistic serial killer, crime boss Jang Dong-su is left humiliated. Determined to catch the killer known as K, he forms an uneasy alliance with Jung Tae-seok, a relentless and incorruptible detective who often disrupts his illegal business. However, while Jang Dong-su wants K dead, Jung Tae-suk is determined to bring him to justice. With a deal in place—whoever finds K first will decide his fate—the hunt begins, blurring the lines between crime and law.', 'Lee Won-tae', 110, '2019-05-15', 'T18', 'ko', 'https://image.tmdb.org/t/p/w500/oHlM4abRm6BzrRcz9Nup1uidw9H.jpg', 'https://www.youtube.com/watch?v=D1XANQUYSvk', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (385, 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'Harley Quinn joins forces with a singer, an assassin and a police detective to help a young girl who had a hit placed on her after she stole a rare diamond from a crime lord.', 'Cathy Yan', 109, '2020-02-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/h4VB6m0RwcicVEZvzftYZyKXs6K.jpg', 'https://www.youtube.com/watch?v=kGM4uYZzfu0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (386, 'Freakier Friday', 'Years after Tess and Anna endured an identity crisis, Anna now has a daughter of her own and a soon-to-be stepdaughter. As they navigate the myriad challenges that come when two families merge, Tess and Anna discover lightning might indeed strike twice.', 'Nisha Ganatra', 110, '2025-08-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9wV65OmsjLAqBfDnYTkMPutXH8j.jpg', 'https://www.youtube.com/watch?v=IyJzhtJEtoU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (387, 'The Breadwinner', 'After his wife Katie lands a once-in-a-lifetime deal on Shark Tank that takes her on a prolonged business trip - lifelong breadwinner Nate Wilcox now has to fend for his family as a first-time stay-at-home dad.', 'Eric Appel', 100, '2026-05-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4apG9Xk6HQvV48JKEjSUeiebju7.jpg', 'https://www.youtube.com/watch?v=19PLc6hpTvA', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (388, 'Peaky Blinders: The Immortal Man', 'After his estranged son gets embroiled in a Nazi plot, self-exiled gangster Tommy Shelby must return to Birmingham to save his family — and his nation.', 'Tom Harper', 112, '2026-03-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/gRMalasZEzsZi4w2VFuYusfSfqf.jpg', 'https://www.youtube.com/watch?v=lcvUGs3xaDM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (389, 'Joker: Folie à Deux', 'While struggling with his dual identity, Arthur Fleck not only stumbles upon true love, but also finds the music that''s always been inside him.', 'Todd Phillips', 138, '2024-10-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/if8QiqCI7WAGImKcJCfzp6VTyKA.jpg', 'https://www.youtube.com/watch?v=_OKAwz2MsJs', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (390, 'Sonic the Hedgehog 2', 'After settling in Green Hills, Sonic is eager to prove he has what it takes to be a true hero. His test comes when Dr. Robotnik returns, this time with a new partner, Knuckles, in search for an emerald that has the power to destroy civilizations. Sonic teams up with his own sidekick, Tails, and together they embark on a globe-trotting journey to find the emerald before it falls into the wrong hands.', 'Jeff Fowler', 123, '2022-03-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6DrHO1jr3qVrViUO6s6kFiAGM7.jpg', 'https://www.youtube.com/watch?v=47r8FXYZWNU', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (391, 'The Shape of Water', 'An other-worldly story, set against the backdrop of Cold War era America circa 1962, where a mute janitor working at a lab falls in love with an amphibious man being held captive there and devises a plan to help him escape.', 'Guillermo del Toro', 123, '2017-12-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9zfwPffUXpBrEP26yp0q1ckXDcj.jpg', 'https://www.youtube.com/watch?v=368_ovPsJk8', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (392, 'It Ends with Us', 'When a woman''s first love suddenly reenters her life, her relationship with a charming, but abusive neurosurgeon is upended, and she realizes she must learn to rely on her own strength to make an impossible choice for her future.', 'Justin Baldoni', 131, '2024-08-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AjV6jFJ2YFIluYo4GQf13AA1tqu.jpg', 'https://www.youtube.com/watch?v=DLET_u31M4M', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (393, 'Terrifier 3', 'Five years after surviving Art the Clown''s Halloween massacre, Sienna and Jonathan are still struggling to rebuild their shattered lives. As the holiday season approaches, they try to embrace the Christmas spirit and leave the horrors of the past behind. But just when they think they''re safe, Art returns, determined to turn their holiday cheer into a new nightmare. The festive season quickly unravels as Art unleashes his twisted brand of terror, proving that no holiday is safe.', 'Damien Leone', 125, '2024-10-09', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ju10W5gl3PPK3b7TjEmVOZap51I.jpg', 'https://www.youtube.com/watch?v=0EDDtgWnSeY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (394, 'Guy Ritchie''s The Covenant', 'After an ambush, Afghan interpreter Ahmed goes to Herculean lengths to save US Army Sergeant John Kinley''s life. When Kinley learns that Ahmed and his family were not given safe passage to America as promised, he must return to the war zone and repay his debt.', 'Guy Ritchie', 123, '2023-04-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kVG8zFFYrpyYLoHChuEeOGAd6Ru.jpg', 'https://www.youtube.com/watch?v=02PPMPArNEQ', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (395, 'How to Make a Killing', 'Disowned at birth by his obscenely wealthy family, blue-collar Becket Redfellow will stop at nothing to reclaim his inheritance, no matter how many relatives stand in his way.', 'John Patton Ford', 105, '2026-02-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vxMeKC7o5Gi8IHMi6lUgsdprTqv.jpg', 'https://www.youtube.com/watch?v=B7RslMKZ2Yc', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (396, 'Black Phone 2', 'Four years after defeating The Grabber, Finney Blake is struggling with life after captivity. When his younger sister Gwen begins receiving calls in her dreams from the Black Phone and seeing disturbing visions of three boys being stalked at a winter camp, the siblings become determined to solve the mystery and confront a killer who has grown more powerful in death and more significant to them than either could imagine.', 'Scott Derrickson', 114, '2025-10-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/vBOpqxW0SDhACwEO2LZT29DuNG2.jpg', 'https://www.youtube.com/watch?v=FCHsEEen4HM', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (397, 'Indiana Jones and the Dial of Destiny', 'Finding himself in a new era, and approaching retirement, Indy wrestles with fitting into a world that seems to have outgrown him. But as the tentacles of an all-too-familiar evil return in the form of an old rival, Indy must don his hat and pick up his whip once more to make sure an ancient and powerful artifact doesn''t fall into the wrong hands.', 'James Mangold', 155, '2023-06-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg', 'https://www.youtube.com/watch?v=ZfVYgWYaHmE', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (398, 'Godzilla vs. Kong', 'In a time when monsters walk the Earth, humanity’s fight for its future sets Godzilla and Kong on a collision course that will see the two most powerful forces of nature on the planet collide in a spectacular battle for the ages.', 'Adam Wingard', 114, '2021-03-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pgqgaUx1cJb5oZQQ5v0tNARCeBp.jpg', 'https://www.youtube.com/watch?v=odM92ap8_c0', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (399, 'King Arthur: Legend of the Sword', 'When the child Arthur’s father is murdered, Vortigern, Arthur’s uncle, seizes the crown. Robbed of his birthright and with no idea who he truly is, Arthur comes up the hard way in the back alleys of the city. But once he pulls the sword Excalibur from the stone, his life is turned upside down and he is forced to acknowledge his true legacy... whether he likes it or not.', 'Guy Ritchie', 126, '2017-05-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9kKXH6eJpzoFGhCbTN3FVwSQK3n.jpg', 'https://www.youtube.com/watch?v=6rbPTQIdjmY', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (400, 'Past Lives', 'After decades apart, childhood friends Nora and Hae Sung are reunited in New York for one fateful weekend as they confront notions of destiny, love, and the choices that make a life.', 'Celine Song', 106, '2023-06-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/k3waqVXSnvCZWfJYNtdamTgTtTA.jpg', 'https://www.youtube.com/watch?v=kA244xewjcI', 'COMING_SOON', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (401, 'Blades of the Guardians', 'Dao Ma, the "second most wanted fugitive," is entrusted by his benefactor, the chief of Mo family clan, to take on a mysterious escort mission-escorting the "most wanted fugitive" to Chang''an.', 'Yuen Woo-ping', 126, '2026-02-17', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/R84km7PJ0frFSNPmvIjG6LV1kg.jpg', 'https://www.youtube.com/watch?v=7jkL4-uYriY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (402, 'Cruella', 'In 1970s London amidst the punk rock revolution, a young grifter named Estella is determined to make a name for herself with her designs. She befriends a pair of young thieves who appreciate her appetite for mischief, and together they are able to build a life for themselves on the London streets. One day, Estella’s flair for fashion catches the eye of the Baroness von Hellman, a fashion legend who is devastatingly chic and terrifyingly haute. But their relationship sets in motion a course of events and revelations that will cause Estella to embrace her wicked side and become the raucous, fashionable and revenge-bent Cruella.', 'Craig Gillespie', 134, '2021-05-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hjS9mH8KvRiGHgjk6VUZH7OT0Ng.jpg', 'https://www.youtube.com/watch?v=gmRKv7n2If8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (403, 'Dunkirk', 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.', 'Christopher Nolan', 107, '2017-07-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/b4Oe15CGLL61Ped0RAS9JpqdmCt.jpg', 'https://www.youtube.com/watch?v=F-eMt3SrfFU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (404, 'Kung Fu Panda 3', 'While Po and his father are visiting a secret panda village, an evil spirit threatens all of China, forcing Po to form a ragtag army to fight back.', 'Alessandro Carloni, Jennifer Yuh Nelson', 95, '2016-01-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oajNi4Su39WAByHI6EONu8G8HYn.jpg', 'https://www.youtube.com/watch?v=10r9ozshGVE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (405, 'Good Boy', 'Tommy, a volatile 19-year-old, revels in drugs, parties and violence. After getting separated from his friends on a drunken bender, he is abducted by a shadowy figure. He wakes to find himself imprisoned in the basement of a remote Yorkshire house, inhabited by a very strange family. But what unfolds is not what he could possibly expect.', 'Jan Komasa', 110, '2026-03-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/eWb841fMkSNly5gfL9J1N0xzVYI.jpg', 'https://www.youtube.com/watch?v=Qhe6GNgW8uI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (406, 'A Quiet Place Part II', 'Following the events at home, the Abbott family now face the terrors of the outside world. Forced to venture into the unknown, they realize that the creatures that hunt by sound are not the only threats that lurk beyond the sand path.', 'John Krasinski', 97, '2021-05-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', 'https://www.youtube.com/watch?v=BpdDN9d9Jio', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (407, 'Nirvanna the Band the Show the Movie', 'When their plan to book a show at the Rivoli goes horribly wrong, Matt and Jay accidentally travel back to the year 2008.', 'Matt Johnson', 100, '2026-02-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/sm5TGX8WbnCd9Uo26cLyTxVwA1n.jpg', 'https://www.youtube.com/watch?v=y2K9ccMREOI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (408, 'Dracula', 'In late 15th-century Eastern Europe, Prince Vlad II’s bride is brutally murdered. As a result, he renounces God and damns Heaven itself. Cursed with eternal life, Vlad is reborn as Dracula, an immortal warlord who defies fate in a blood-soaked crusade to wrench his lost love back from death.', 'Luc Besson', 130, '2025-07-30', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/ykyRfv7JDofLxXLAwtLXaSuaFfM.jpg', 'https://www.youtube.com/watch?v=3OBLPpuOM10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (409, 'The Witch', 'In 1630, a farmer relocates his family to a remote plot of land on the edge of a forest where strange, unsettling things happen. With suspicion and paranoia mounting, each family member''s faith, loyalty and love are tested in shocking ways.', 'Robert Eggers', 92, '2016-02-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg', 'https://www.youtube.com/watch?v=97OQ7MQC5Ck', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (410, 'The Garfield Movie', 'Garfield, the world-famous, Monday-hating, lasagna-loving indoor cat, is about to have a wild outdoor adventure! After an unexpected reunion with his long-lost father – scruffy street cat Vic – Garfield and his canine friend Odie are forced from their perfectly pampered life into joining Vic in a hilarious, high-stakes heist.', 'Mark Dindal', 101, '2024-04-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/p6AbOJvMQhBmffd0PIv0u8ghWeY.jpg', 'https://www.youtube.com/watch?v=IeFWNtMo1Fs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (411, 'Bugonia', 'Two conspiracy obsessed young men kidnap the high-powered CEO of a major company, convinced that she is an alien intent on destroying planet Earth.', 'Yorgos Lanthimos', 119, '2025-10-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rSdOua3wKMEaFWDcKAYWRjXQWOt.jpg', 'https://www.youtube.com/watch?v=7VBigr-JHB0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (412, 'Suicide Squad', 'From DC Comics comes the Suicide Squad, an antihero team of incarcerated supervillains who act as deniable assets for the United States government, undertaking high-risk black ops missions in exchange for commuted prison sentences.', 'David Ayer', 122, '2016-08-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sk3FZgh3sRrmr8vyhaitNobMcfh.jpg', 'https://www.youtube.com/watch?v=5AwUdTIbA8I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (413, 'Talk to Me', 'When a group of friends discover how to conjure spirits using an embalmed hand, they become hooked on the new thrill, until one of them goes too far and unleashes terrifying supernatural forces.', 'Danny Philippou, Michael Philippou', 95, '2023-07-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kdPMUMJzyYAc4roD52qavX0nLIC.jpg', 'https://www.youtube.com/watch?v=PGo4wfCejsk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (414, 'Balls Up', 'Two marketing executives go "balls out" and pitch a bold full‑coverage condom sponsorship with the World Cup. After their drunken celebration in Brazil sparks a global scandal, they must outrun furious fans, criminals, and power-hungry officials to salvage their careers and make it home alive.', 'Peter Farrelly', 104, '2026-04-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xwvJ3WzdJ1OCuDoY8LAxBUlQyig.jpg', 'https://www.youtube.com/watch?v=zgzxY4RtxBg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (415, 'Space Jam: A New Legacy', 'When LeBron and his young son Dom are trapped in a digital space by a rogue A.I., LeBron must get them home safe by leading Bugs, Lola Bunny and the whole gang of notoriously undisciplined Looney Tunes to victory over the A.I.''s digitized champions on the court. It''s Tunes versus Goons in the highest-stakes challenge of his life.', 'Malcolm D. Lee', 115, '2021-07-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/5bFK5d3mVTAvBCXi5NPWH0tYjKl.jpg', 'https://www.youtube.com/watch?v=RCsEKvz2mxs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (416, 'All Quiet on the Western Front', 'Paul Baumer and his friends Albert and Muller, egged on by romantic dreams of heroism, voluntarily enlist in the German army. Full of excitement and patriotic fervour, the boys enthusiastically march into a war they believe in. But once on the Western Front, they discover the soul-destroying horror of World War I.', 'Edward Berger', 147, '2022-10-07', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/2IRjbi9cADuDMKmHdLK7LaqQDKA.jpg', 'https://www.youtube.com/watch?v=hf8EYbVxtCY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (417, 'The Croods: A New Age', 'Searching for a safer habitat, the prehistoric Crood family discovers an idyllic, walled-in paradise that meets all of its needs. Unfortunately, they must also learn to live with the Bettermans -- a family that''s a couple of steps above the Croods on the evolutionary ladder. As tensions between the new neighbors start to rise, a new threat soon propels both clans on an epic adventure that forces them to embrace their differences, draw strength from one another, and survive together.', 'Joel Crawford', 95, '2020-11-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tbVZ3Sq88dZaCANlUcewQuHQOaE.jpg', 'https://www.youtube.com/watch?v=GkXeVIfbJOw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (418, 'Speak No Evil', 'When an American family is invited to spend the weekend at the idyllic country estate of a charming British family they befriended on vacation, what begins as a dream holiday soon warps into a snarled psychological nightmare.', 'James Watkins', 110, '2024-09-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dA4N6uWOnEMgbxXwFX7qX7adzs8.jpg', 'https://www.youtube.com/watch?v=FjzxI6uf8H8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (419, 'The Nice Guys', 'A private eye investigates the apparent suicide of a fading porn star in 1970s Los Angeles and uncovers a conspiracy.', 'Shane Black', 116, '2016-05-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg', 'https://www.youtube.com/watch?v=GQR5zsLHbYw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (420, 'No Hard Feelings', 'On the brink of losing her childhood home, Maddie discovers an intriguing job listing: wealthy helicopter parents looking for someone to “date” their introverted 19-year-old son, Percy, before he leaves for college. To her surprise, Maddie soon discovers the awkward Percy is no sure thing.', 'Gene Stupnitsky', 103, '2023-06-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gD72DhJ7NbfxvtxGiAzLaa0xaoj.jpg', 'https://www.youtube.com/watch?v=7psP7xBEa28', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (421, 'Anaconda', 'A group of friends facing mid-life crises head to the rainforest with the intention of remaking their favorite movie from their youth, only to find themselves in a fight for their lives against natural disasters, giant snakes and violent criminals.', 'Tom Gormican', 100, '2025-12-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hBxN6dwrANN1ic3a4G9x6JZcR3C.jpg', 'https://www.youtube.com/watch?v=LFLyvzIZjK4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (422, 'Aladdin', 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.', 'Guy Ritchie', 127, '2019-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', 'https://www.youtube.com/watch?v=foyufD52aog', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (423, '1917', 'At the height of the First World War, two young British soldiers must cross enemy territory and deliver a message that will stop a deadly attack on hundreds of soldiers.', 'Sam Mendes', 119, '2019-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iZf0KyrE25z1sage4SYFLCCrMi9.jpg', 'https://www.youtube.com/watch?v=UcmZN0Mbl04', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (424, 'Aquaman', 'Half-human, half-Atlantean Arthur Curry is taken on the journey of his lifetime to discover if he is worth of being a king.', 'James Wan', 143, '2018-12-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', 'https://www.youtube.com/watch?v=2wcj6SrX4zw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (425, 'Sing', 'A koala named Buster recruits his best friend to help him drum up business for his theater by hosting a singing competition.', 'Garth Jennings', 108, '2016-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rwopfpHqPCYBSgBuZwkaXXqHp14.jpg', 'https://www.youtube.com/watch?v=GIgXWuLQPFY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (426, 'Quantum Supremacy', 'In a future threatened by rogue robots and an all-powerful AI, Captain Monroe and his crew race to prevent humanity''s downfall in Quantum Supremacy.', 'Jesse Baget', 77, '2026-02-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oU9td2mvEu04rLGlynziVmNo16b.jpg', 'https://www.youtube.com/watch?v=0WRbz8XMHpg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (427, 'My Fault: London', '18-year-old Noah moves from America to London, with her mother who''s recently fallen in love with William, a wealthy British businessman. Noah meets William’s son, bad-boy Nick, and soon discovers there is an attraction between them neither can avoid. As Noah spends the summer adjusting to her new life, her devastating past will catch up with her while falling in love for the first time.', 'Charlotte Fassler, Dani Girdwood', 119, '2025-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ttN5D6GKOwKWHmCzDGctAvaNMAi.jpg', 'https://www.youtube.com/watch?v=14z9L_MwH5s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (428, 'Jack Reacher: Never Go Back', 'Years after resigning command of an elite military police unit, the nomadic, righter-of-wrongs Reacher is drawn back into the life he left behind when his friend and successor, Major Susan Turner is framed for espionage. Reacher will stop at nothing to prove her innocence and to expose the real perpetrators behind the killings of his former soldiers.', 'Edward Zwick', 118, '2016-10-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cOg3UT2NYWHZxp41vpxAnVCOC4M.jpg', 'https://www.youtube.com/watch?v=DTBcGQWmQ1c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (429, 'The Salt Path', 'The profound story of husband and wife Raynor and Moth Winn, who embark on a 630-mile trek after being forcibly removed from their home. Hoping that in nature they will find solace and a sense of acceptance, they walk through the beautiful but rugged coastlines of South West England - a journey that is exhilarating, challenging, and liberating in equal measure. THE SALT PATH is a powerful portrayal of home, and how it can be lost and rediscovered in the most unexpected ways.', 'Marianne Elliott', 115, '2025-05-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yBtmFkjzPzd6KvNgoJwwsm1nyXL.jpg', 'https://www.youtube.com/watch?v=TK5j6lQk7CE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (430, 'Anatomy of a Fall', 'A woman is suspected of her husband''s murder, and their blind son faces a moral dilemma as the sole witness.', 'Justine Triet', 151, '2023-08-23', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/kQs6keheMwCxJxrzV83VUwFtHkB.jpg', 'https://www.youtube.com/watch?v=FUXawkH-ONM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (431, 'Caught Stealing', 'Burned-out ex-baseball player Hank Thompson unexpectedly finds himself embroiled in a dangerous struggle for survival amidst the criminal underbelly of late 1990s New York City, forced to navigate a treacherous underworld he never imagined.', 'Darren Aronofsky', 107, '2025-08-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cvda8s5J8YaHjTyEyXQpvD6f3iV.jpg', 'https://www.youtube.com/watch?v=6mIvD-GN-p4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (432, 'Trap', 'A father and teen daughter attend a pop concert, where they realize they''re at the center of a dark and sinister event.', 'M. Night Shyamalan', 105, '2024-07-31', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/jwoaKYVqPgYemFpaANL941EF94R.jpg', 'https://www.youtube.com/watch?v=hJiPAJKjUVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (433, 'The Family Plan 2', 'Now that Dan''s assassin days are behind him, all he wants for Christmas is quality time with his kids. But when he learns his daughter has her own plans, he books a family trip to London—putting them all in the crosshairs of an unexpected enemy.', 'Simon Cellan Jones', 106, '2025-11-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/semFxuYx6HcrkZzslgAkBqfJvZk.jpg', 'https://www.youtube.com/watch?v=dqolYtJGuf4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (434, 'Elize: Shadows of a Woman', 'In this retelling of a real case, a former escort discovers her wealthy husband''s infidelity and struggles to cope as betrayal poisons their marriage.', 'Vellas', 93, '2026-07-22', 'T16', 'pt', 'https://image.tmdb.org/t/p/w500/l3wevYWTpiZSUEM5B0Q8c21ALAD.jpg', 'https://www.youtube.com/watch?v=KiKnd3cusPo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (435, 'The Irishman', 'Pennsylvania, 1956. Frank Sheeran, a war veteran of Irish origin who works as a truck driver, accidentally meets mobster Russell Bufalino. Once Frank becomes his trusted man, Bufalino sends him to Chicago with the task of helping Jimmy Hoffa, a powerful union leader related to organized crime, with whom Frank will maintain a close friendship for nearly twenty years.', 'Martin Scorsese', 209, '2019-11-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mbm8k3GFhXS0ROd9AD1gqYbIFbM.jpg', 'https://www.youtube.com/watch?v=RS3aHkkfuEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (436, 'Angel Has Fallen', 'After a treacherous attack, Secret Service agent Mike Banning is charged with attempting to assassinate President Trumbull. Chased by his own colleagues and the FBI, Banning begins a race against the clock to clear his name.', 'Ric Roman Waugh', 122, '2019-08-21', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/fapXd3v9qTcNBTm39ZC4KUVQDNf.jpg', 'https://www.youtube.com/watch?v=5U2AJvU3bl4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (437, 'Regretting You', 'Morgan Grant and her daughter Clara explore what''s left behind after a devastating accident reveals a shocking betrayal and forces them to confront family secrets, redefine love, and rediscover each other.', 'Josh Boone', 116, '2025-10-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/z4gVnxTaks3anTycwKjDmvQSuWt.jpg', 'https://www.youtube.com/watch?v=qub8lZlVlho', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (438, 'Mortal Engines', 'Many thousands of years in the future, Earth’s cities roam the globe on huge wheels, devouring each other in a struggle for ever diminishing resources. On one of these massive traction cities, the old London, Tom Natsworthy has an unexpected encounter with a mysterious young woman from the wastelands who will change the course of his life forever.', 'Christian Rivers', 128, '2018-11-27', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gLhYg9NIvIPKVRTtvzCWnp1qJWG.jpg', 'https://www.youtube.com/watch?v=IRsFc2gguEg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (439, 'The Voyeurs', 'When Pippa and Thomas move into their dream apartment, they notice that their windows look directly into the apartment opposite – inviting them to witness the volatile relationship of the attractive couple across the street. But what starts as a simple curiosity turns into full-blown obsession with increasingly dangerous consequences.', 'Michael Mohan', 117, '2021-08-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8Y4XOIWhpOvSOEn8XrxbkH9yAXO.jpg', 'https://www.youtube.com/watch?v=_fiCdELSwwI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (440, 'The Whale', 'A reclusive English teacher suffering from severe obesity attempts to reconnect with his estranged teenage daughter for one last chance at redemption.', 'Darren Aronofsky', 117, '2022-12-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jQ0gylJMxWSL490sy0RrPj1Lj7e.jpg', 'https://www.youtube.com/watch?v=D30r0CwtIKc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (441, 'After We Fell', 'Just as Tessa''s life begins to become unglued, nothing is what she thought it would be. Not her friends nor her family. The only person that she should be able to rely on is Hardin, who is furious when he discovers the massive secret that she''s been keeping. Before Tessa makes the biggest decision of her life, everything changes because of revelations about her family.', 'Castille Landon', 99, '2021-09-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dU4HfnTEJDf9KvxGS9hgO7BVeju.jpg', 'https://www.youtube.com/watch?v=NYdNN6C9hfI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (442, 'Isle of Dogs', 'In the future, an outbreak of canine flu leads the mayor of a Japanese city to banish all dogs to an island used as a garbage dump. The outcasts must soon embark on an epic journey when a 12-year-old boy arrives on the island to find his beloved pet.', 'Wes Anderson', 101, '2018-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4C7ZHv5LUPq7XzxC3nq8mBr77sP.jpg', 'https://www.youtube.com/watch?v=dt__kig8PVU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (443, 'They Will Kill You', 'A woman answers a help wanted ad to be a housekeeper in a mysterious New York City high-rise, unaware that she is entering a community that has seen a number of disappearances over the years and may be under the grip of a Satanic cult.', 'Kirill Sokolov', 94, '2026-03-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6oI4oQKTWMVUlr8Ivqydp28Ruu6.jpg', 'https://www.youtube.com/watch?v=AqNFJUihSHg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (444, 'Heretic', 'Two young missionaries are forced to prove their faith when they knock on the wrong door and are greeted by a diabolical Mr. Reed, becoming ensnared in his deadly game of cat-and-mouse.', 'Bryan Woods, Scott Beck', 111, '2024-10-31', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/fr96XzlzsONrQrGfdLMiwtQjott.jpg', 'https://www.youtube.com/watch?v=O9i2vmFhSSY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (445, 'Five Nights at Freddy''s 2', 'One year since the supernatural nightmare at Freddy Fazbear''s Pizza, the stories about what transpired there have been twisted into a campy local legend, inspiring the town''s first ever Fazfest. With the truth kept from her, Abby sneaks out to reconnect with Freddy, Bonnie, Chica, and Foxy, setting into motion a terrifying series of events that will reveal dark secrets about the real origin of Freddy''s, and unleash a decades-hidden horror.', 'Emma Tammi', 104, '2025-12-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/udAxQEORq2I5wxI97N2TEqdhzBE.jpg', 'https://www.youtube.com/watch?v=NQypHE9_Fm4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (446, 'Hi :)', 'Two individuals initially exchange a simple "Hi," but through a series of chance encounters, shared experiences, and deep conversations, they gradually develop a strong connection and eventually fall in love.', 'Vishnu Edavan', 143, '2026-08-28', 'P', 'ta', 'https://image.tmdb.org/t/p/w500/9Vgmpa0tcCzkbXf9AY0zXrai1oi.jpg', 'https://www.youtube.com/watch?v=LVmH0rgWZb8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (447, 'Another Simple Favor', 'Stephanie and Emily reunite on the beautiful island of Capri, Italy for Emily''s extravagant wedding to a rich Italian businessman. Along with the glamorous guests, expect murder and betrayal to RSVP for a wedding with more twists and turns than the road from the Marina Grande to the Capri town square.', 'Paul Feig', 123, '2025-03-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zboCGZ4aIqPMd7VFI4HWnmc7KYJ.jpg', 'https://www.youtube.com/watch?v=QWajCwdC_TM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (448, 'The Mortuary Assistant', 'Rebecca Owens, a recent mortuary science graduate takes a night shift job at River Fields Mortuary. Initially, the job seems straightforward — embalming bodies, completing paperwork, and keeping things tidy. But once Rebecca starts working the night shift, things take a dark turn.', 'Jeremiah Kipp', 91, '2026-02-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/72AoFPC5TY4DfJwXXS9rPwPeReD.jpg', 'https://www.youtube.com/watch?v=YtY6JoPX5MU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (449, 'Ralph Breaks the Internet', 'Video game bad guy Ralph and fellow misfit Vanellope von Schweetz must risk it all by traveling to the World Wide Web in search of a replacement part to save Vanellope''s video game, Sugar Rush. In way over their heads, Ralph and Vanellope rely on the citizens of the internet — the netizens — to help navigate their way, including an entrepreneur named Yesss, who is the head algorithm and the heart and soul of trend-making site BuzzzTube.', 'Phil Johnston, Rich Moore', 112, '2018-11-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/iVCrhBcpDaHGvv7CLYbK6PuXZo1.jpg', 'https://www.youtube.com/watch?v=DIBw9dSVKdU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (450, 'Wonder Woman 1984', 'A botched store robbery places Wonder Woman in a global battle against a powerful and mysterious ancient force that puts her powers in jeopardy.', 'Patty Jenkins', 151, '2020-12-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8UlWHLMpgZm9bx6QYh0NFoq67TZ.jpg', 'https://www.youtube.com/watch?v=EMgbWouN4wE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (451, 'Raya and the Last Dragon', 'Long ago, in the fantasy world of Kumandra, humans and dragons lived together in harmony. But when an evil force threatened the land, the dragons sacrificed themselves to save humanity. Now, 500 years later, that same evil has returned and it’s up to a lone warrior, Raya, to track down the legendary last dragon to restore the fractured land and its divided people.', 'Carlos López Estrada, Don Hall', 107, '2021-03-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/5nVhgCzxKbK47OLIKxCR1syulOn.jpg', 'https://www.youtube.com/watch?v=1VIZ89FEjYI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (452, 'Baywatch', 'Devoted lifeguard Mitch Buchannon butts heads with a brash new recruit. Together, they uncover a local criminal plot that threatens the future of the Bay.', 'Seth Gordon', 116, '2017-05-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6HE4xd8zloDqmjMZuhUCCw2UcY1.jpg', 'https://www.youtube.com/watch?v=eyKOgnaf0BU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (453, 'Gran Turismo', 'The ultimate wish-fulfillment tale of a teenage Gran Turismo player whose gaming skills won him a series of Nissan competitions to become an actual professional racecar driver.', 'Neill Blomkamp', 135, '2023-08-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/51tqzRtKMMZEYUpSYkrUE7v9ehm.jpg', 'https://www.youtube.com/watch?v=GVPzGBvPrzw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (454, 'Annihilation', 'A biologist signs up for a dangerous, secret expedition into a mysterious zone where the laws of nature don''t apply.', 'Alex Garland', 115, '2018-02-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4YRplSk6BhH6PRuE9gfyw9byUJ6.jpg', 'https://www.youtube.com/watch?v=89OP78l9oF0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (455, 'The Black Phone', 'Finney Blake, a shy but clever 13-year-old boy, is abducted by a sadistic killer and trapped in a soundproof basement where screaming is of little use. When a disconnected phone on the wall begins to ring, Finney discovers that he can hear the voices of the killer’s previous victims. And they are dead set on making sure that what happened to them doesn’t happen to Finney.', 'Scott Derrickson', 103, '2022-06-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p9ZUzCyy9wRTDuuQexkQ78R2BgF.jpg', 'https://www.youtube.com/watch?v=3eGP6im8AZA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (456, 'Wonder', 'The story of August Pullman – a boy with facial differences – who enters fifth grade, attending a mainstream elementary school for the first time.', 'Stephen Chbosky', 113, '2017-11-13', 'K', 'en', 'https://image.tmdb.org/t/p/w500/sONh3LYGFcVDTy8pm1tbSOB13Li.jpg', 'https://www.youtube.com/watch?v=ASAGdtAJPnU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (457, 'Operation Fortune: Ruse de Guerre', 'Special agent Orson Fortune and his team of operatives recruit one of Hollywood''s biggest movie stars to help them on an undercover mission when the sale of a deadly new weapons technology threatens to disrupt the world order.', 'Guy Ritchie', 114, '2023-01-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uo7vWfQUlVwueYTDRicXOJa8Oow.jpg', 'https://www.youtube.com/watch?v=W8Sqk1GcqxY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (458, 'Roofman', 'A former Army Ranger and struggling father turns to robbing McDonald’s restaurants by cutting holes in their roofs, earning him the nickname "Roofman." After escaping prison, he secretly lives inside a Toys “R” Us for six months, surviving undetected while planning his next move. But when he falls for a divorced mom drawn to his undeniable charm, his double life begins to unravel, setting off a compelling and suspenseful game of cat and mouse as his past closes in.', 'Derek Cianfrance', 126, '2025-10-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wXDFtcnYtevleGzCmAD2ReQnJ4l.jpg', 'https://www.youtube.com/watch?v=GXecSGmQDEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (459, 'Ghost in the Shell', 'In the near future, Major is the first of her kind: a human saved from a terrible crash, then cyber-enhanced to be a perfect soldier devoted to stopping the world''s most dangerous criminals.', 'Rupert Sanders', 107, '2017-03-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zCtL3UBgCoZzd7XTVGhvl6XY75E.jpg', 'https://www.youtube.com/watch?v=5XnptKCeaJE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (460, 'Wind River', 'An FBI agent teams with the town''s veteran game tracker to investigate a murder that occurred on a Native American reservation.', 'Taylor Sheridan', 107, '2017-08-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pySivdR845Hom4u4T2WNkJxe6Ad.jpg', 'https://www.youtube.com/watch?v=E0qRHABxvfc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (461, 'A Man Called Otto', 'When a lively young family moves in next door, grumpy widower Otto Anderson meets his match in a quick-witted, pregnant woman named Marisol, leading to an unlikely friendship that turns his world upside down.', 'Marc Forster', 126, '2022-12-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/130H1gap9lFfiTF9iDrqNIkFvC9.jpg', 'https://www.youtube.com/watch?v=XvbGalkHKPY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (462, 'The Family Plan', 'Dan Morgan is many things: a devoted husband, a loving father, a celebrated car salesman. He''s also a former assassin. And when his past catches up to his present, he''s forced to take his unsuspecting family on a road trip unlike any other.', 'Simon Cellan Jones', 118, '2023-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jLLtx3nTRSLGPAKl4RoIv1FbEBr.jpg', 'https://www.youtube.com/watch?v=ns8weNznn1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (463, 'Black Box', 'A routine domestic flight turns into the flight from hell through a series of inexplicable phenomena and raw terror. Surreal encounters blur the boundaries between reality and nightmare. Passengers fight against all the odds in an attempt to survive while combating bizarre technological malfunctions, accelerating supernatural events and alien influences.', 'Steven Quale', 85, '2026-06-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/x6dsUKxz8O5rD3lzayJgvFpW58s.jpg', 'https://www.youtube.com/watch?v=y-nf8hUFd98', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (464, 'Scream', 'Twenty-five years after a streak of brutal murders shocked the quiet town of Woodsboro, a new killer has donned the Ghostface mask and begins targeting a group of teenagers to resurrect secrets from the town’s deadly past.', 'Matt Bettinelli-Olpin, Tyler Gillett', 114, '2022-01-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nD4M4Bx457ryLuKYpxFwQ2IBJ5w.jpg', 'https://www.youtube.com/watch?v=beToTslH17s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (465, 'The Bluff', 'When her tranquil life on a remote island is shattered by the return of her vengeful former captain, a skilled ex-pirate must confront her bloody past and unleash her deadly talents to save her family from a ruthless siege.', 'Frank E. Flowers', 103, '2026-02-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dl1cA7wdwePc9QU2Rc24EPqlcyJ.jpg', 'https://www.youtube.com/watch?v=uUYMqRjNxhM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (466, 'The Tomorrow War', 'The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.', 'Chris McKay', 138, '2021-09-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', 'https://www.youtube.com/watch?v=QPistcpGB8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (467, 'Warcraft', 'The peaceful realm of Azeroth stands on the brink of war as its civilization faces a fearsome race of invaders: orc warriors fleeing their dying home to colonize another. As a portal opens to connect the two worlds, one army faces destruction and the other faces extinction. From opposing sides, two heroes are set on a collision course that will decide the fate of their family, their people, and their home.', 'Duncan Jones', 123, '2016-05-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eGi5aoxaZveqNLtE7BZJCuWwR3G.jpg', 'https://www.youtube.com/watch?v=2Rxoz13Bthc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (468, 'Flow', 'A solitary cat, displaced by a great flood, finds refuge on a boat with various species and must navigate the challenges of adapting to a transformed world together.', 'Gints Zilbalodis', 85, '2024-08-29', 'T13', 'lv', 'https://image.tmdb.org/t/p/w500/z2sG41PxfL1hnL1mHbxzSREUtOf.jpg', 'https://www.youtube.com/watch?v=82WW9dVbglI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (469, 'Greenland', 'John Garrity, his estranged wife and their young son embark on a perilous journey to find sanctuary as a planet-killing comet hurtles toward Earth. Amid terrifying accounts of cities getting levelled, the Garritys experience the best and worst in humanity. As the countdown to the global apocalypse approaches zero, their incredible trek culminates in a desperate and last-minute flight to a possible safe haven.', 'Ric Roman Waugh', 120, '2020-07-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bNo2mcvSwIvnx8K6y1euAc1TLVq.jpg', 'https://www.youtube.com/watch?v=d4s9XNChIRk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (470, 'I Know What You Did Last Summer', 'When five friends inadvertently cause a deadly car accident, they cover up their involvement and make a pact to keep it a secret rather than face the consequences. A year later, their past comes back to haunt them and they''re forced to confront a horrifying truth: someone knows what they did last summer…and is hell-bent on revenge.', 'Jennifer Kaytin Robinson', 111, '2025-07-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8FP2ObEGIiQYQCf83gL4ZVzwZF8.jpg', 'https://www.youtube.com/watch?v=9QABNfDhSxs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (471, 'The Menu', 'A young couple travels to a remote island to eat at an exclusive restaurant where the chef has prepared a lavish menu, with some shocking surprises.', 'Mark Mylod', 107, '2022-11-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/fPtUgMcLIboqlTlPrq0bQpKK8eq.jpg', 'https://www.youtube.com/watch?v=CAWZMssP3gM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (472, 'Gandhari', 'When a mother loses her eyesight and her daughter in a kidnapping, she takes matters into her own hands to hunt down those responsible.', 'Devashish Makhija', 117, '2026-09-03', 'T18', 'hi', 'https://image.tmdb.org/t/p/w500/hCHei97aPYCCsh4vicz9X0wmdFV.jpg', 'https://www.youtube.com/watch?v=TRyBiPD1bUc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (473, 'Alice Through the Looking Glass', 'Alice Kingsleigh returns to Underland and faces a new adventure in saving the Mad Hatter.', 'James Bobin', 113, '2016-05-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kbGamUkYfgKIYIrU8kW5oc0NatZ.jpg', 'https://www.youtube.com/watch?v=QtrOm-DBhIM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (474, 'Hamnet', 'The powerful story of love and loss that inspired the creation of Shakespeare''s timeless masterpiece, Hamlet.', 'Chloé Zhao', 125, '2025-11-26', 'K', 'en', 'https://image.tmdb.org/t/p/w500/vbeyOZm2bvBXcbgPD3v6o94epPX.jpg', 'https://www.youtube.com/watch?v=E2xtmPkuksA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (475, 'A Complete Unknown', 'New York, early 1960s. Against the backdrop of a vibrant music scene and tumultuous cultural upheaval, an enigmatic 19-year-old from Minnesota arrives in the West Village with his guitar and revolutionary talent, destined to change the course of American music.', 'James Mangold', 141, '2024-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/llWl3GtNoXosbvYboelmoT459NM.jpg', 'https://www.youtube.com/watch?v=FdV-Cs5o8mc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (476, 'Split', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.', 'M. Night Shyamalan', 117, '2017-01-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ow2BSQGKJtZpH2zZY1rmX8eXKAi.jpg', 'https://www.youtube.com/watch?v=6bfooooTKyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (477, 'How to Train Your Dragon: The Hidden World', 'As Hiccup fulfills his dream of creating a peaceful dragon utopia, Toothless’ discovery of an untamed, elusive mate draws the Night Fury away. When danger mounts at home and Hiccup’s reign as village chief is tested, both dragon and rider must make impossible decisions to save their kind.', 'Dean DeBlois', 104, '2019-01-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xvx4Yhf0DVH8G4LzNISpMfFBDy2.jpg', 'https://www.youtube.com/watch?v=5DEdq57E5ls', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (478, 'Wonka', 'Willy Wonka – chock-full of ideas and determined to change the world one delectable bite at a time – is proof that the best things in life begin with a dream, and if you’re lucky enough to meet Willy Wonka, anything is possible.', 'Paul King', 117, '2023-12-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qhb1qOilapbapxWQn9jtRCMwXJF.jpg', 'https://www.youtube.com/watch?v=otNh9bTjXWg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (479, '13 Hours: The Secret Soldiers of Benghazi', 'An American Ambassador is killed during an attack at a U.S. compound in Libya as a security team struggles to make sense out of the chaos.', 'Michael Bay', 144, '2016-01-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fZlAxZMo6BId1SiqyjLmkd7oUB7.jpg', 'https://www.youtube.com/watch?v=4CJBuUwd0Os', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (480, 'Miraculous: Ladybug & Cat Noir, The Movie', 'After a guardian of magical jewels turns an awkward girl and a popular boy into superheroes, they can never reveal their identities — even to each other.', 'Jeremy Zag', 105, '2023-07-05', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/dQNJ8SdCMn3zWwHzzQD2xrphR1X.jpg', 'https://www.youtube.com/watch?v=3fzFvZToh8o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (481, 'War Dogs', 'Based on the true story of two young men, David Packouz and Efraim Diveroli, who won a $300 million contract from the Pentagon to arm America''s allies in Afghanistan.', 'Todd Phillips', 114, '2016-08-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mDcPRjZC1bb6LavFU3gwsWdVfCM.jpg', 'https://www.youtube.com/watch?v=KWs5qnZnhfo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (482, 'The Boy and the Heron', 'While the Second World War rages, the teenage Mahito, haunted by his mother''s tragic death, is relocated from Tokyo to the serene rural home of his new stepmother Natsuko, a woman who bears a striking resemblance to the boy''s mother. As he tries to adjust, this strange new world grows even stranger following the appearance of a persistent gray heron, who perplexes and bedevils Mahito, dubbing him the "long-awaited one."', 'Hayao Miyazaki', 124, '2023-07-14', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/f4oZTcfGrVTXKTWg157AwikXqmP.jpg', 'https://www.youtube.com/watch?v=A002-b7IH2M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (483, 'Ocean''s Eight', 'Debbie Ocean, a criminal mastermind, gathers a crew of female thieves to pull off the heist of the century at New York''s annual Met Gala.', 'Gary Ross', 111, '2018-06-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/MvYpKlpFukTivnlBhizGbkAe3v.jpg', 'https://www.youtube.com/watch?v=MFWF9dU5Zc0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (484, 'The Lord of the Rings: The War of the Rohirrim', 'A sudden attack by Wulf, a clever and traitorous lord of Rohan seeking vengeance for the death of his father, forces Helm Hammerhand, the King of Rohan, and his people to make a daring last stand in the ancient stronghold of the Hornburg.', 'Kenji Kamiyama', 134, '2024-12-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/23WCoDo6wzBfzbX7BGTNwVUqZfi.jpg', 'https://www.youtube.com/watch?v=gCUg6Td5fgQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (485, 'Conclave', 'After the unexpected death of the Pope, Cardinal Lawrence is tasked with managing the covert and ancient ritual of electing a new one. Sequestered in the Vatican with the Catholic Church’s most powerful leaders until the process is complete, Lawrence finds himself at the center of a conspiracy that could lead to its downfall.', 'Edward Berger', 120, '2024-10-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/m5x8D0bZ3eKqIVWZ5y7TnZ2oTVg.jpg', 'https://www.youtube.com/watch?v=JX9jasdi3ic', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (486, 'Tomb Raider', 'Lara Croft, the fiercely independent daughter of a missing adventurer, must push herself beyond her limits when she finds herself on the island where her father disappeared.', 'Roar Uthaug', 118, '2018-03-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/s4Qn5LF6OwK4rIifmthIDtbqDSs.jpg', 'https://www.youtube.com/watch?v=3KkhD0MnaJU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (487, 'I Swear', 'Diagnosed with Tourette Syndrome at 15, John Davidson navigates his way against the odds through troubled teenage years and into adulthood, finding inspiration in the kindness of others to discover his true purpose in life.', 'Kirk Jones', 121, '2025-09-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vUwyhNWBKkSwK8ELvEeBRwV724h.jpg', 'https://www.youtube.com/watch?v=10ynpduiRpM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (488, 'American Made', 'The true story of pilot Barry Seal, who transported contraband for the CIA and the Medellin cartel in the 1980s.', 'Doug Liman', 115, '2017-08-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/23ILgoPSO5ShKcTZOuiTVfqFAUB.jpg', 'https://www.youtube.com/watch?v=AEBIJRAkujM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (489, 'Jason Bourne', 'The most dangerous former operative of the CIA is drawn out of hiding to uncover hidden truths about his past.', 'Paul Greengrass', 123, '2016-07-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xA7N41glw17MBQtcWSm2eBlBRuG.jpg', 'https://www.youtube.com/watch?v=F4gJsKZvqE4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (490, 'Rampage', 'Primatologist Davis Okoye shares an unshakable bond with George, the extraordinarily intelligent, silverback gorilla who has been in his care since birth. But a rogue genetic experiment gone awry mutates this gentle ape into a raging creature of enormous size. To make matters worse, it’s soon discovered there are other similarly altered animals. As these newly created alpha predators tear across North America, destroying everything in their path, Okoye teams with a discredited genetic engineer to secure an antidote, fighting his way through an ever-changing battlefield, not only to halt a global catastrophe but to save the fearsome creature that was once his friend.', 'Brad Peyton', 107, '2018-04-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/MGADip4thVSErP34FAAfzFBTZ5.jpg', 'https://www.youtube.com/watch?v=-43MBOJnVks', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (491, 'Jumanji: Welcome to the Jungle', 'Four teenagers in detention discover an old video game console with a game they’ve never heard of. When they decide to play, they are immediately sucked into the jungle world of Jumanji in the bodies of their avatars. They’ll have to complete the adventure of their lives filled with fun, thrills and danger or be stuck in the game forever!', 'Jake Kasdan', 119, '2017-12-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', 'https://www.youtube.com/watch?v=10VphsyJhbU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (492, 'Remarkably Bright Creatures', 'Through unlikely bonds formed during night shifts at a local aquarium, Tova, an elderly widow, learns of a life-changing discovery that may bring her joy and wonder once again.', 'Olivia Newman', 114, '2026-05-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9HcEqn3D4J6b2Z0jK54id9nA0fr.jpg', 'https://www.youtube.com/watch?v=b14IFe4an5k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (493, 'Scary Stories to Tell in the Dark', 'Mill Valley, Pennsylvania, Halloween night, 1968. After playing a joke on a school bully, Stella and her friends decide to sneak into a supposedly haunted house that once belonged to the powerful Bellows family, unleashing dark forces that they will be unable to control.', 'André Øvredal', 108, '2019-08-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uy0dNFbhRhHBLwpOGpcTw9UEwdX.jpg', 'https://www.youtube.com/watch?v=7IQjZWz2JF0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (494, 'Blink Twice', 'When tech billionaire Slater King meets cocktail waitress Frida at his fundraising gala, he invites her to join him and his friends on a dream vacation on his private island. But despite the epic setting, beautiful people, ever-flowing champagne, and late-night dance parties, Frida can sense that there’s something sinister hiding beneath the island’s lush façade.', 'Zoë Kravitz', 103, '2024-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lZGOK0I2DJSRlEPNOAFTSNxSjDD.jpg', 'https://www.youtube.com/watch?v=aMcmfonGWY4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (495, 'Shazam!', 'A boy is given the ability to become an adult superhero in times of need with a single magic word.', 'David F. Sandberg', 132, '2019-03-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xnopI5Xtky18MPhK40cZAGAOVeV.jpg', 'https://www.youtube.com/watch?v=go6GEIrcvFY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (496, 'The Secret Woman', 'After discovering she has a family and a shipping empire, a woman with amnesia returns to a wealthy and seemingly perfect past to uncover why she left.', 'Barbara Topsøe-Rothenborg', 119, '2026-08-28', 'T18', 'da', 'https://image.tmdb.org/t/p/w500/5FC5vUHFz0fbJOd0bhyzJpCSLrc.jpg', 'https://www.youtube.com/watch?v=FldeGkt4e4k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (497, 'Black Clover: Sword of the Wizard King', 'As a lionhearted boy who can''t wield magic strives for the title of Wizard King, four banished Wizard Kings of yore return to crush the Clover Kingdom.', 'Ayataka Tanemura', 113, '2023-06-16', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/9YEGawvjaRgnyW6QVcUhFJPFDco.jpg', 'https://www.youtube.com/watch?v=M-JD8QqStBg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (498, 'Girl in the Basement', 'Sara is a teen girl who is looking forward to her 18th birthday to move away from her controlling father Don. But before she could even blow out the candles, Don imprisons her in the basement of their home.', 'Elisabeth Röhm', 88, '2021-02-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tPP9n6r5QrIKPnshnJqE7klptj2.jpg', 'https://www.youtube.com/watch?v=a7VGn_0Vsx8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (499, 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 'Tanjiro Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar''s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyojuro Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!', 'Haruo Sotozaki', 117, '2020-10-16', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg', 'https://www.youtube.com/watch?v=23riEOmDOgM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (500, 'Hanuman Ansh', 'A grieving boy seeks God to meet his departed mother, and in finding the divine, learns to serve humanity with miracles of love, food and silent blessings, becoming Hanuman Ansh, Neem Karoli Baba.', 'Vishal Chaturvedi', 150, '2026-08-07', 'K', 'hi', 'https://image.tmdb.org/t/p/w500/as2Y3zGUa2IUS3uAx2sh6Ano3es.jpg', 'https://www.youtube.com/watch?v=YpGhCA2X3gU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
