  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (501, 'The Lost City', 'Reclusive author Loretta Sage writes about exotic places in her popular adventure novels that feature a handsome cover model named Alan. While on tour promoting her new book with Alan, Loretta gets kidnapped by an eccentric billionaire who hopes she can lead him to the ancient city''s lost treasure that featured in her latest story. Alan, determined to prove he can be a hero in real life and not just on the pages of her books, sets off to rescue her.', 'Aaron Nee, Adam Nee', 112, '2022-03-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rnheO8cFvCYcmZsDrBoabJbKLFE.jpg', 'https://www.youtube.com/watch?v=5f9VcZqxFO4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (502, 'Enola Holmes 3', 'Adventure follows detective Enola Holmes to Malta, where her plans to tie the knot unravel when Sherlock''s disappearance plunges her into a perilous case.', 'Philip Barantini', 109, '2026-06-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7kRYHH9H9PjBFwz1FprbHB2AAjI.jpg', 'https://www.youtube.com/watch?v=n_pEJjq-9xQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (503, 'The Debt Collector', 'Tormented by past mistakes and a terminal diagnosis, an ex-debt collector returns to the underworld to protect the victims of a violent organization.', 'Surapong Ploensang', 134, '2026-07-20', 'T16', 'th', 'https://image.tmdb.org/t/p/w500/qADBUb5ybrkRVGZEFF8Z4RuOwys.jpg', 'https://www.youtube.com/watch?v=U9vJ2Z4SFQI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (504, 'Transformers: The Last Knight', 'Humans and Transformers are at war. Optimus Prime is gone. The key to saving our future lies buried in the secrets of the past, in the hidden history of Transformers on Earth. Saving our world falls upon the shoulders of an unlikely alliance: Cade Yeager; Bumblebee; an English Lord; and an Oxford Professor.', 'Michael Bay', 154, '2017-06-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/s5HQf2Gb3lIO2cRcFwNL9sn1o1o.jpg', 'https://www.youtube.com/watch?v=6Vtf0MszgP8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (505, 'Finding Dory', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?', 'Andrew Stanton', 97, '2016-06-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg', 'https://www.youtube.com/watch?v=JhvrQeY3doI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (506, 'Thrash', 'When a catastrophic hurricane slams a coastal town, stranded residents must survive rapidly rising waters swarming with ravenous sharks.', 'Tommy Wirkola', 84, '2026-04-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/adk8weka3O5648g3de4z3y4aE7G.jpg', 'https://www.youtube.com/watch?v=hzyOsNyDkbM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (507, 'The Angry Birds Movie', 'An island populated entirely by happy, flightless birds or almost entirely. In this paradise, Red, a bird with a temper problem, speedy Chuck, and the volatile Bomb have always been outsiders. But when the island is visited by mysterious green piggies, it’s up to these unlikely outcasts to figure out what the pigs are up to.', 'Clay Kaytis, Fergal Reilly', 97, '2016-05-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iOH0fEFtV9z9rZp9zmBFGGeWicv.jpg', 'https://www.youtube.com/watch?v=0qJzWrq7les', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (508, 'Luck', 'Suddenly finding herself in the never-before-seen Land of Luck, the unluckiest person in the world must unite with the magical creatures there to turn her luck around.', 'Peggy Holmes', 105, '2022-08-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1HOYvwGFioUFL58UVvDRG6beEDm.jpg', 'https://www.youtube.com/watch?v=xSG5UX0EQVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (509, 'Hotel Transylvania 3: Summer Vacation', 'Dracula, Mavis, Johnny and the rest of the Drac Pack take a vacation on a luxury Monster Cruise Ship, where Dracula falls in love with the ship’s captain, Ericka, who’s secretly a descendant of Abraham Van Helsing, the notorious monster slayer.', 'Genndy Tartakovsky', 97, '2018-06-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lzE5BwGQea1nek7TPXUuC5AZ6rq.jpg', 'https://www.youtube.com/watch?v=Ku52zNnft8k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (510, 'The Iron Claw', 'The true story of the inseparable Von Erich brothers, who made history in the intensely competitive world of professional wrestling in the early 1980s. Through tragedy and triumph, under the shadow of their domineering father and coach, the brothers seek larger-than-life immortality on the biggest stage in sports.', 'Sean Durkin', 133, '2023-12-21', 'K', 'en', 'https://image.tmdb.org/t/p/w500/s2VLjcykJfwplJNGT5iEeCA0mRx.jpg', 'https://www.youtube.com/watch?v=8KVsaoveTbw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (511, 'The Legend of Tarzan', 'Tarzan, having acclimated to life in London, is called back to his former home in the jungle to investigate the activities at a mining encampment.', 'David Yates', 109, '2016-06-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eJrfz178xBGlxjDGxnBXTzWWa4w.jpg', 'https://www.youtube.com/watch?v=Aj7ty6sViiU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (512, 'Jojo Rabbit', 'Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.', 'Taika Waititi', 108, '2019-10-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg', 'https://www.youtube.com/watch?v=tL4McUzXfFI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (513, 'Fountain of Youth', 'A treasure-hunting mastermind assembles a team for a life-changing adventure. But to outwit and outrun threats at every turn, he''ll need someone even smarter than he is: his estranged sister.', 'Guy Ritchie', 126, '2025-05-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4iWjGghUj2uyHo2Hyw8NFBvsNGm.jpg', 'https://www.youtube.com/watch?v=-7S28bH8iDs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (514, 'Babygirl', 'A high-powered CEO puts her career and family on the line when she begins a torrid affair with her much younger intern.', 'Halina Reijn', 115, '2024-12-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ilwO6elz3mLV9CToT7C8pjVeKX0.jpg', 'https://www.youtube.com/watch?v=-8Sx6U6Ou0Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (515, 'Mortal Kombat', 'Washed-up MMA fighter Cole Young, unaware of his heritage, and hunted by Emperor Shang Tsung''s best warrior, Sub-Zero, seeks out and trains with Earth''s greatest champions as he prepares to stand against the enemies of Outworld in a high stakes battle for the universe.', 'Simon McQuoid', 110, '2021-04-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nkayOAUBUu4mMvyNf9iHSUiPjF1.jpg', 'https://www.youtube.com/watch?v=jBa_aHwCbC4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (516, 'Hunting Season', 'When a reclusive survivalist and his daughter rescue a mysterious, wounded woman from a river, they become entangled in a deadly web of violence and revenge, forcing them to confront a brutal criminal to survive.', 'Raja Collins', 100, '2025-12-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cbryTyaWdqrKpQCw6K7zm2jrB5v.jpg', 'https://www.youtube.com/watch?v=O7vKuVadFmo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (517, 'Primate', 'College student Lucy and her friends spend their vacation at her family''s home in Hawaii, which includes her pet chimpanzee, Ben. However, when Ben contracts rabies after being bitten by a rabid animal, the group must fight for their lives in order to avoid the now-violent chimp.', 'Johannes Roberts', 89, '2026-01-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rKleYiEj4pFqxedTRWfujLooi84.jpg', 'https://www.youtube.com/watch?v=wo87F-va410', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (518, 'The Electric State', 'An orphaned teen hits the road with a mysterious robot to find her long-lost brother, teaming up with a smuggler and his wisecracking sidekick.', 'Anthony Russo, Joe Russo', 125, '2025-02-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/sI2NiMU8o65hmIMY0JI9CjJ0p7f.jpg', 'https://www.youtube.com/watch?v=KpN98z8Kf5E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (519, 'undertone', 'The host of a popular paranormal podcast becomes haunted by terrifying recordings mysteriously sent her way.', 'Ian Tuason', 94, '2026-03-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2PFgFMnrdCPXWiZl1PUvky7Mo9D.jpg', 'https://www.youtube.com/watch?v=1_TRSEcMvR0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (520, 'Portrait of a Lady on Fire', 'On an isolated island in Brittany at the end of the eighteenth century, a female painter is obliged to paint a wedding portrait of a young woman.', 'Céline Sciamma', 121, '2019-09-06', 'T13', 'fr', 'https://image.tmdb.org/t/p/w500/2LquGwEhbg3soxSCs9VNyh5VJd9.jpg', 'https://www.youtube.com/watch?v=Bn_-YoG69Sw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (521, 'A Silent Voice: The Movie', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', 'Naoko Yamada', 129, '2016-09-17', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg', 'https://www.youtube.com/watch?v=E7utbHbxDAM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (522, 'Solo Leveling -ReAwakening-', 'Over a decade after ''gates'' connecting worlds appeared, awakening ''hunters'' with superpowers, weakest hunter Sung Jinwoo encounters a double dungeon and accepts a mysterious quest, becoming the only one able to level up, changing his fate. A catch-up recap of the first season coupled with an exclusive sneak peek of the first two episodes of the highly anticipated second season in one momentous theatrical fan experience.', 'Shunsuke Nakashige', 116, '2024-11-26', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/uzHMp5heVLR68kbbUEXFPsmxYsM.jpg', 'https://www.youtube.com/watch?v=EC_mmRxh2SU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (523, 'Tell Me What You Want', 'After his father''s death, Eric Zimmerman travels to Spain to oversee his company''s branches. In Madrid, he falls for Judith and engage in an intense, erotic relationship full of exploration. However, Eric fears his secret may end their affair.', 'Lucía Alemany', 114, '2024-11-29', 'P', 'es', 'https://image.tmdb.org/t/p/w500/yZXYCiZQPB7Ui6D5206W1zDKv8P.jpg', 'https://www.youtube.com/watch?v=MzNbhA4WFqg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (524, 'The Next 365 Days', 'Laura and Massimo''s relationship hangs in the balance as they try to overcome trust issues while a tenacious Nacho works to push them apart.', 'Barbara Białowąs, Tomasz Mandes', 112, '2022-08-18', 'T13', 'pl', 'https://image.tmdb.org/t/p/w500/8AWm7iMcsCI3DdGz4YEJtiMDp8Z.jpg', 'https://www.youtube.com/watch?v=iXdw5wYI4cY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (525, 'The Old Guard 2', 'Andy and her team of immortal warriors fight with renewed purpose as they face a powerful new foe threatening their mission to protect humanity.', 'Victoria Mahoney', 107, '2025-07-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wqfu3bPLJaEWJVk3QOm0rKhxf1A.jpg', 'https://www.youtube.com/watch?v=lyivgZ074PY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (526, 'Bridget Jones: Mad About the Boy', 'Bridget Jones navigates life as a widow and single mum with the help of her family, friends, and former lover, Daniel. Back to work and on the apps, she''s pursued by a younger man and maybe – just maybe – her son''s science teacher.', 'Michael Morris', 124, '2025-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/e5VR3nhLYG60znxaqU84wv4VSCb.jpg', 'https://www.youtube.com/watch?v=7sSNobjiep4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (527, 'Luca', 'Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.', 'Enrico Casarosa', 95, '2021-06-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg', 'https://www.youtube.com/watch?v=YdAIBlPVe9s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (528, 'Until Dawn', 'One year after her sister Melanie mysteriously disappeared, Clover and her friends head into the remote valley where she vanished in search of answers. Exploring an abandoned visitor center, they find themselves stalked by a masked killer and horrifically murdered one by one...only to wake up and find themselves back at the beginning of the same evening.', 'David F. Sandberg', 103, '2025-04-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bLY5yN4MKVynZ2HMZWElTOGBgBe.jpg', 'https://www.youtube.com/watch?v=2b3vBaINZ7w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (529, 'Nope', 'Residents in a lonely gulch of inland California bear witness to an uncanny, chilling discovery.', 'Jordan Peele', 130, '2022-07-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/AcKVlWaNVVVFQwro3nLXqPljcYA.jpg', 'https://www.youtube.com/watch?v=HUgmq_8PlRY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (530, 'The Matrix Resurrections', 'Plagued by strange memories, Neo''s life takes an unexpected turn when he finds himself back inside the Matrix.', 'Lana Wachowski', 148, '2021-12-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', 'https://www.youtube.com/watch?v=9ix7TUGVYIo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (531, 'Resident Evil: Vendetta', 'When a fearless enemy out for revenge unleashes a brutal and deadly new virus, BSAA captain Chris Redfield enlists the help of Agent Leon S. Kennedy and Professor Rebecca Chambers to bring down the death merchant and save New York City.', 'Takanori Tsujimoto', 97, '2017-05-27', 'T18', 'ja', 'https://image.tmdb.org/t/p/w500/kdiMtgjWXEH9QZ85hgmWaSwshjf.jpg', 'https://www.youtube.com/watch?v=B1PJGWC5ThY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (532, 'Whistle', 'When a misfit group of unwitting high school students stumbles upon a cursed Aztec Death Whistle, they discover that blowing it unleashes a terrifying sound that summons their future deaths to hunt them down.', 'Corin Hardy', 100, '2026-01-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vgonf5kGsiijUBjzxKTvechhT28.jpg', 'https://www.youtube.com/watch?v=-O5DgGQJeks', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (533, 'Maze Runner: The Death Cure', 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.', 'Wes Ball', 143, '2018-01-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/s8K0US4tUEoOrQ1LDh0eppuwGDx.jpg', 'https://www.youtube.com/watch?v=4-BTxXm8KSg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (534, 'The SpongeBob Movie: Search for SquarePants', 'Desperate to be a big guy, SpongeBob sets out to prove his bravery to Mr. Krabs by following The Flying Dutchman – a mysterious swashbuckling ghost pirate – on a seafaring adventure that takes him to the deepest depths of the deep sea, where no Sponge has gone before.', 'Derek Drymon', 88, '2025-12-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xJnOMMsFASxNiFnG7v3TNIQ3ife.jpg', 'https://www.youtube.com/watch?v=XdPt8QWTypI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (535, 'Pacific Rim: Uprising', 'It has been ten years since The Battle of the Breach and the oceans are still, but restless. Vindicated by the victory at the Breach, the Jaeger program has evolved into the most powerful global defense force in human history. The PPDC now calls upon the best and brightest to rise up and become the next generation of heroes when the Kaiju threat returns.', 'Steven S. DeKnight', 111, '2018-03-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/nFWhttU8PM50t25NPdy7PE7rv3G.jpg', 'https://www.youtube.com/watch?v=8BAhwgjMvnM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (536, 'The Phoenician Scheme', 'Wealthy businessman Zsa-zsa Korda appoints his only daughter, a nun, as sole heir to his estate. As Korda embarks on a new enterprise, they soon become the target of scheming tycoons, foreign terrorists, and determined assassins.', 'Wes Anderson', 102, '2025-05-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/iXxIUVqpQAlyy98UjUlzjkMYuj6.jpg', 'https://www.youtube.com/watch?v=GEuMnPl2WI4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (537, 'Mean Girls', 'New student Cady Heron is welcomed into the top of the social food chain by the elite group of popular girls called ‘The Plastics,’ ruled by the conniving queen bee Regina George and her minions Gretchen and Karen. However, when Cady makes the major misstep of falling for Regina’s ex-boyfriend Aaron Samuels, she finds herself prey in Regina’s crosshairs. As Cady sets to take down the group’s apex predator with the help of her outcast friends Janis and Damian, she must learn how to stay true to herself while navigating the most cutthroat jungle of all: high school.', 'Arturo Perez Jr., Samantha Jayne', 113, '2024-01-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fbbj3viSUDEGT1fFFMNpHP1iUjw.jpg', 'https://www.youtube.com/watch?v=9xgPEplWACQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (538, 'Resident Evil: Death Island', 'In San Francisco, Jill Valentine is dealing with a zombie outbreak and a new T-Virus, Leon Kennedy is on the trail of a kidnapped DARPA scientist, and Claire Redfield is investigating a monstrous fish that is killing whales in the bay. Joined by Chris Redfield and Rebecca Chambers, they discover the trail of clues from their separate cases all converge on the same location, Alcatraz Island, where a new evil has taken residence and awaits their arrival.', 'Eiichiro Hasumi', 91, '2023-06-22', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/qayga07ICNDswm0cMJ8P3VwklFZ.jpg', 'https://www.youtube.com/watch?v=L-vkuA8oqMY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (539, 'Ambulance', 'Decorated veteran Will Sharp, desperate for money to cover his wife''s medical bills, asks for help from his adoptive brother Danny. A charismatic career criminal, Danny instead offers him a score: the biggest bank heist in Los Angeles history: $32 million.', 'Michael Bay', 136, '2022-03-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hUbgg3mMSbY9PlpTxBo4IFUVSd6.jpg', 'https://www.youtube.com/watch?v=7NU-STboFeI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (540, 'Gods of Egypt', 'A common thief joins a mythical god on a quest through Egypt.', 'Alex Proyas', 127, '2016-02-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hzH7fwaTyQNITLo40Hu3R7cVMqv.jpg', 'https://www.youtube.com/watch?v=cMVxECWC-vk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (541, 'Back in Action', 'Fifteen years after vanishing from the CIA to start a family, elite spies Matt and Emily jump back into the world of espionage when their cover is blown.', 'Seth Gordon', 114, '2025-01-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3L3l6LsiLGHkTG4RFB2aBA6BttB.jpg', 'https://www.youtube.com/watch?v=MV2nYw6gL_w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (542, 'The Lego Batman Movie', 'A cooler-than-ever Batman must face the usual villains as the Joker plots a takeover of Gotham City. But when Bruce Wayne accidentally adopts a teenage orphan who wishes to become his sidekick, he’s forced to give up his lone-vigilante ways and learn to work with others.', 'Chris McKay', 104, '2017-02-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e1TliRWOdXQ73pRunbpFiGst6Kd.jpg', 'https://www.youtube.com/watch?v=LHgQSwgKygk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (543, 'Hotel Transylvania: Transformania', 'When Van Helsing''s mysterious invention, the "Monsterfication Ray," goes haywire, Drac and his monster pals are all transformed into humans, and Johnny becomes a monster. In their new mismatched bodies, Drac and Johnny must team up and race across the globe to find a cure before it''s too late, and before they drive each other crazy.', 'Derek Drymon, Jennifer Kluska', 92, '2022-01-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/teCy1egGQa0y8ULJvlrDHQKnxBL.jpg', 'https://www.youtube.com/watch?v=6suJohjIvfo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (544, 'Star Trek Beyond', 'The USS Enterprise crew explores the furthest reaches of uncharted space, where they encounter a mysterious new enemy who puts them and everything the Federation stands for to the test.', 'Justin Lin', 122, '2016-07-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wI5VghYNYLktDRPUa5rrVcVA1h7.jpg', 'https://www.youtube.com/watch?v=3MBXBMkcUNo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (545, 'Cold Storage', 'When a mutating, highly contagious fungus escapes a sealed facility, two employees – joined by a grizzled bioterror operative – must survive the wildest night shift ever to save humanity from extinction.', 'Jonny Campbell', 99, '2026-01-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3HA2iiq982e01EKXJvPFyfMADVM.jpg', 'https://www.youtube.com/watch?v=cSeXZTKeHOI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (546, 'Death of a Unicorn', 'A father and daughter accidentally hit and kill a unicorn while en route to a weekend retreat, where his billionaire boss seeks to exploit the creature’s miraculous curative properties.', 'Alex Scharfman', 107, '2025-03-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/xWlF2i51zUq7BUq4iJte1g9NyIM.jpg', 'https://www.youtube.com/watch?v=9cMIarrxLGs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (547, 'Abigail', 'A group of criminals kidnap a teenage ballet dancer, the daughter of a notorious gang leader, in order to obtain a ransom of $50 million, but over time, they discover that she is not just an ordinary girl. After the kidnappers begin to diminish, one by one, they discover, to their increasing horror, that they are locked inside with no normal little girl.', 'Matt Bettinelli-Olpin, Tyler Gillett', 109, '2024-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5gKKSoD3iezjoL7YqZONjmyAiRA.jpg', 'https://www.youtube.com/watch?v=3PsP8MFH8p0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (548, 'Fuze', 'An unexploded WWII bomb is discovered on a busy construction site in the centre of London. Chaos ensues as the military and police begin a mass evacuation against a ticking clock.', 'David Mackenzie', 96, '2026-03-23', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oMFdQE5hMJ9JjhNORegwTo0GKmh.jpg', 'https://www.youtube.com/watch?v=1aNywiElPSY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (549, 'Sisu: Road to Revenge', 'Returning to the house where his family was brutally murdered during the war, "the man who refuses to die" dismantles it, loads it on a truck, and is determined to rebuild it somewhere safe in their honor. When the commander who killed his family comes back hellbent on finishing the job, a relentless, eye-popping cross-country chase ensues.', 'Jalmari Helander', 89, '2025-10-21', 'T16', 'fi', 'https://image.tmdb.org/t/p/w500/roCMOuMQ55Z2TxVx1vZZTevlo0n.jpg', 'https://www.youtube.com/watch?v=VmStqCXIgio', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (550, 'Damsel', 'A young woman''s marriage to a charming prince turns into a fierce fight for survival when she''s offered up as a sacrifice to a fire-breathing dragon.', 'Juan Carlos Fresnadillo', 107, '2024-03-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/AgHbB9DCE9aE57zkHjSmseszh6e.jpg', 'https://www.youtube.com/watch?v=iM150ZWovZM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (551, 'Solo: A Star Wars Story', 'Through a series of daring escapades deep within a dark and dangerous criminal underworld, Han Solo meets his mighty future copilot Chewbacca and encounters the notorious gambler Lando Calrissian.', 'Ron Howard', 135, '2018-05-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4oD6VEccFkorEBTEDXtpLAaz0Rl.jpg', 'https://www.youtube.com/watch?v=jPEYpryMp2s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (552, 'Blue Beetle', 'Recent college grad Jaime Reyes returns home full of aspirations for his future, only to find that home is not quite as he left it. As he searches to find his purpose in the world, fate intervenes when Jaime unexpectedly finds himself in possession of an ancient relic of alien biotechnology: the Scarab.', 'Ángel Manuel Soto', 128, '2023-08-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mXLOHHc1Zeuwsl4xYKjKh2280oL.jpg', 'https://www.youtube.com/watch?v=4wxyy8Rcz4k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (553, 'Trolls', 'After the monstrous Bergens invade Troll Village, Princess Poppy, the happiest Troll ever born, and overly-cautious, curmudgeonly outcast Branch set off on a journey to rescue her friends. Their mission is full of adventure and mishaps, as this mismatched duo try to tolerate each other long enough to get the job done.', 'Mike Mitchell', 92, '2016-10-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/9VlK2j0THZWzhQPq0W3Oc0IIdBB.jpg', 'https://www.youtube.com/watch?v=xyjm5VQ11TQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (554, 'Cold Pursuit', 'The quiet family life of Nels Coxman, a snowplow driver, is upended after his son''s murder. Nels begins a vengeful hunt for Viking, the drug lord he holds responsible for the killing, eliminating Viking''s associates one by one. As Nels draws closer to Viking, his actions bring even more unexpected and violent consequences, as he proves that revenge is all in the execution.', 'Hans Petter Moland', 119, '2019-02-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5RILVnOchQyL1LbcVzmabipdJfc.jpg', 'https://www.youtube.com/watch?v=0phuNQQ_gHI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (555, 'The Holdovers', 'A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', 'Alexander Payne', 133, '2023-10-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', 'https://www.youtube.com/watch?v=AhKLpJmHhIg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (556, 'Only the Brave', 'Members of the Granite Mountain Hotshots battle deadly wildfires to save an Arizona town.', 'Joseph Kosinski', 133, '2017-09-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/db5IkOJu9UHktrKroNktw1Z8ARY.jpg', 'https://www.youtube.com/watch?v=DSHk_BHQxp0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (557, 'Master of the Universe', 'A young man must use his untapped powers to fight back against an evil alien and their army, who will stop at nothing to take over Earth and then the universe.', 'Marcel Walz', 81, '2026-05-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/a77OcLmarwiBJakOPPC36m58t4L.jpg', 'https://www.youtube.com/watch?v=CmuEqjuzxWc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (558, 'The Great Wall', 'European mercenaries searching for black powder become embroiled in the defense of the Great Wall of China against a horde of monstrous creatures.', 'Zhang Yimou', 103, '2016-12-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p70dq1YxabemdZDm5K6Q8G10wSn.jpg', 'https://www.youtube.com/watch?v=6SKI9rgqFck', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (559, 'Dear You', 'Xiaowei travels to Thailand to find his "billionaire grandfather" who is out of contact due to debt problems, but unexpectedly find the one who has been corresponding with his grandmother for years is not her husband.', 'Lan Hongchun', 118, '2026-04-30', 'P', 'zh', 'https://image.tmdb.org/t/p/w500/rjmhzdVS3Ia535pFawju857e2Na.jpg', 'https://www.youtube.com/watch?v=abeSQSbNXSk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (560, 'M3GAN 2.0', 'After the underlying tech for M3GAN is stolen and misused by a powerful defense contractor to create a military-grade weapon known as Amelia, M3GAN''s creator Gemma realizes that the only option is to resurrect M3GAN and give her a few upgrades, making her faster, stronger, and more lethal.', 'Gerard Johnstone', 120, '2025-06-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oekamLQrwlJjRNmfaBE4llIvkir.jpg', 'https://www.youtube.com/watch?v=1FeiTZMtwLA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (561, 'The Adam Project', 'After accidentally crash-landing in 2022, time-traveling fighter pilot Adam Reed teams up with his 12-year-old self on a mission to save the future.', 'Shawn Levy', 106, '2022-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/wFjboE0aFZNbVOF05fzrka9Fqyx.jpg', 'https://www.youtube.com/watch?v=IE8HIsIrq4o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (562, 'Maleficent: Mistress of Evil', 'Maleficent and her goddaughter Aurora begin to question the complex family ties that bind them as they are pulled in different directions by impending nuptials, unexpected allies, and dark new forces at play.', 'Joachim Rønning', 119, '2019-10-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vloNTScJ3w7jwNwtNGoG8DbTThv.jpg', 'https://www.youtube.com/watch?v=1qIziwbp_7A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (563, 'Tom & Jerry', 'Tom the cat and Jerry the mouse get kicked out of their home and relocate to a fancy New York hotel, where a scrappy employee named Kayla will lose her job if she can’t evict Jerry before a high-class wedding at the hotel. Her solution? Hiring Tom to get rid of the pesky mouse.', 'Tim Story', 101, '2021-02-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8XZI9QZ7Pm3fVkigWJPbrXCMzjq.jpg', 'https://www.youtube.com/watch?v=kP9TfCWaQT4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (564, 'Terrifier 2', 'A year after the Miles County massacre, Art the Clown is resurrected by a sinister entity. Art returns home, where he must hunt down and destroy teenage Sienna and her younger brother Jonathan on Halloween. As the body count rises, the siblings fight to stay alive while uncovering the true nature of Art''s evil intent.', 'Damien Leone', 138, '2022-10-06', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/qEAlwXbYk6IHA4ztoS2XFFaa7Xo.jpg', 'https://www.youtube.com/watch?v=6KkONLf_ZKU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (565, 'Moonlight', 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.', 'Barry Jenkins', 112, '2016-10-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', 'https://www.youtube.com/watch?v=9NJj12tJzqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (566, 'Ruby Gillman, Teenage Kraken', 'Ruby Gillman, a sweet and awkward high school student, discovers she''s a direct descendant of the warrior kraken queens. The kraken are sworn to protect the oceans of the world against the vain, power-hungry mermaids. Destined to inherit the throne from her commanding grandmother, Ruby must use her newfound powers to protect those she loves most.', 'Kirk DeMicco', 92, '2023-06-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8ChIb3WzYAcza1vrXR56v510MWk.jpg', 'https://www.youtube.com/watch?v=iAMKwDsfUeU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (567, 'Gemini Man', 'Henry Brogan is an elite 51-year-old assassin who''s ready to call it quits after completing his 72nd job. His plans get turned upside down when he becomes the target of a mysterious operative who can seemingly predict his every move. To his horror, Brogan soon learns that the man who''s trying to kill him is a younger, faster, cloned version of himself.', 'Ang Lee', 117, '2019-10-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uTALxjQU8e1lhmNjP9nnJ3t2pRU.jpg', 'https://www.youtube.com/watch?v=6orc_lHvJKY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (568, 'The Killer', 'After a fateful miss, an assassin battles his employers, and himself, on an international manhunt he insists isn''t personal.', 'David Fincher', 118, '2023-10-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ipkcgvN7h3yZnbYowthloHLKsf4.jpg', 'https://www.youtube.com/watch?v=5S7FR_HCg9g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (569, 'A House of Dynamite', 'When a single, unattributed missile is launched at the United States, a race begins to determine who is responsible and how to respond.', 'Kathryn Bigelow', 112, '2025-10-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/eB3Tl6xo9VNiN6YIi9XV44v6dab.jpg', 'https://www.youtube.com/watch?v=_wpw2QHJNco', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (570, 'Young Hearts', '14-year-old Elias increasingly feels like an outsider in his village. When he meets his new neighbour of the same age, Alexander, Elias is confronted with his burgeoning sexuality.', 'Anthony Schatteman', 99, '2024-10-26', 'K', 'nl', 'https://image.tmdb.org/t/p/w500/iGCtYxfuvXfy0BD5m6p7vKuPOxS.jpg', 'https://www.youtube.com/watch?v=1aCTG9HplF8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (571, 'Manchester by the Sea', 'After his older brother passes away, Lee Chandler is forced to return home to care for his 16-year-old nephew. There he is compelled to deal with a tragic past that separated him from his family and the community where he was born and raised.', 'Kenneth Lonergan', 138, '2016-11-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/o9VXYOuaJxCEKOxbA86xqtwmqYn.jpg', 'https://www.youtube.com/watch?v=NxQmuJnrjxg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (572, 'The Lost Bus', 'A determined father risks everything to rescue a dedicated teacher and her students from a raging wildfire.', 'Paul Greengrass', 130, '2025-09-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4IPxzGlE17fJAwUTMul4opMeutA.jpg', 'https://www.youtube.com/watch?v=XSDHjkuwaic', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (573, 'Jungle Cruise', 'Dr. Lily Houghton enlists the aid of wisecracking skipper Frank Wolff to take her down the Amazon in his dilapidated boat. Together, they search for an ancient tree that holds the power to heal – a discovery that will change the future of medicine.', 'Jaume Collet-Serra', 127, '2021-07-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yKy9ELL8CON5sqDg4yIvBb5LTZL.jpg', 'https://www.youtube.com/watch?v=f_HvoipFcA8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (574, 'Spies in Disguise', 'Super spy Lance Sterling and scientist Walter Beckett are almost exact opposites. Lance is smooth, suave and debonair. Walter is… not. But what Walter lacks in social skills he makes up for in smarts and invention, creating the awesome gadgets Lance uses on his epic missions. But when events take an unexpected turn, Walter and Lance suddenly have to rely on each other in a whole new way.', 'Nick Bruno, Troy Quane', 102, '2019-12-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/z52xI0MnoX1rqySFJYnmBqHbXRn.jpg', 'https://www.youtube.com/watch?v=6FK19sxxnBU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (575, 'Reminders of Him', 'When Diem''s custodial grandparents adamantly refuse Kenna''s attempts to see her daughter, Kenna discovers unexpected compassion, and then something truer and deeper, with former NFL player and local bar owner Ledger. As their secret romance develops, so do the dangers for both of them, leading Kenna toward heartbreak and, ultimately, the hope for a second chance.', 'Vanessa Caswill', 114, '2026-03-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7L6rceYgzQ0NeHD7PRDNrRoQ291.jpg', 'https://www.youtube.com/watch?v=i36Zw32GfRQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (576, 'The Founder', 'The true story of how Ray Kroc, a salesman from Illinois, met Mac and Dick McDonald, who were running a burger operation in 1950s Southern California. Kroc was impressed by the brothers’ speedy system of making the food and saw franchise potential. He maneuvered himself into a position to be able to pull the company from the brothers and create a billion-dollar empire.', 'John Lee Hancock', 115, '2016-11-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8gLIksu5ggdfBL1UbeTeonHquxl.jpg', 'https://www.youtube.com/watch?v=oprJX5BomEc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (577, 'Hunter Killer', 'Untested American submarine commander, Capt. Joe Glass of the USS Arkansas, is on the hunt for a U.S. sub in distress in the Arctic Ocean. He soon learns a secret Russian coup is in the offing, a conspiracy that threatens to dismantle the world order. With crew and country on the line, Glass must coordinate with an elite group of Navy SEALs to sneak through enemy waters, rescue the kidnapped Russian president, and hopefully prevent World War III.', 'Donovan Marsh', 121, '2018-10-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/a0j18XNVhP4RcW3wXwsqT0kVoQm.jpg', 'https://www.youtube.com/watch?v=mnP_z3qXDCQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (578, 'Kissing Is the Easy Part', 'Sean''s gunning for MIT. Flora''s ditching the SAT. A secret deal with her tenured parents sparks a romance that challenges everything they believe in.', 'Fawzia Mirza', 101, '2026-02-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gPxlb7LLqbsKgjltgVrgYdhfxCZ.jpg', 'https://www.youtube.com/watch?v=T65yqsFnuSQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (579, 'A Haunting in Venice', 'Celebrated sleuth Hercule Poirot, now retired and living in self-imposed exile in Venice, reluctantly attends a Halloween séance at a decaying, haunted palazzo. When one of the guests is murdered, the detective is thrust into a sinister world of shadows and secrets.', 'Kenneth Branagh', 104, '2023-09-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/l6iwxT0NbVw6QiF08YTIuTnXS82.jpg', 'https://www.youtube.com/watch?v=oRCKIP5paEU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (580, 'Anna', 'Beneath Anna Poliatova''s striking beauty lies a secret that will unleash her indelible strength and skill to become one of the world''s most feared government assassins.', 'Luc Besson', 119, '2019-06-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2U0oAVAE0lDRhNmJPPYhDW9kQ8t.jpg', 'https://www.youtube.com/watch?v=oZSMV-NDH4w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (581, 'The Fate of the Furious', 'When a mysterious woman seduces Dom into the world of crime and a betrayal of those closest to him, the crew face trials that will test them as never before.', 'F. Gary Gray', 136, '2017-04-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dImWM7GJqryWJO9LHa3XQ8DD5NH.jpg', 'https://www.youtube.com/watch?v=-9FU7Ia-BKg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (582, 'The SpongeBob Movie: Sponge on the Run', 'When his best friend Gary is suddenly snatched away, SpongeBob takes Patrick on a madcap mission far beyond Bikini Bottom to save their pink-shelled pal.', 'Tim Hill', 95, '2020-08-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jlJ8nDhMhCYJuzOw3f52CP1W8MW.jpg', 'https://www.youtube.com/watch?v=HfiH_526qhY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (583, 'The Addams Family', 'The Addams family''s lives begin to unravel when they face-off against a treacherous, greedy crafty reality-TV host while also preparing for their extended family to arrive for a major celebration.', 'Conrad Vernon, Greg Tiernan', 87, '2019-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/q1epO0eO8DWu8Vo8tPfvVlzW48T.jpg', 'https://www.youtube.com/watch?v=xFCrR3Uw6Mk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (584, 'Don''t Breathe', 'A group of teens break into a blind man''s home thinking they''ll get away with the perfect crime. They''re wrong.', 'Fede Álvarez', 89, '2016-06-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dSxHyPZ2nipSfvdft4IhQKjk5eZ.jpg', 'https://www.youtube.com/watch?v=76yBTNDB6vU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (585, 'Teenage Mutant Ninja Turtles: Out of the Shadows', 'After supervillain Shredder escapes custody, he joins forces with mad scientist Baxter Stockman and two dimwitted henchmen, Bebop and Rocksteady, to unleash a diabolical plan to take over the world. As the Turtles prepare to take on Shredder and his new crew, they find themselves facing an even greater evil with similar intentions: the notorious Krang.', 'Dave Green', 112, '2016-05-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/euVaCiCWz3AALcQXHT6aUqdGUo6.jpg', 'https://www.youtube.com/watch?v=HeaugHGd1Kw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (586, 'CODA', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family''s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.', 'Sian Heder', 112, '2021-08-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', 'https://www.youtube.com/watch?v=0pmfrE1YL4I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (587, 'No Other Choice', 'After being laid off and humiliated by a ruthless job market, a veteran paper mill manager descends into violence in a desperate bid to reclaim his dignity.', 'Park Chan-wook', 139, '2025-09-24', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/vc2S0dvgpsM0XfSiXZDMVkRCSSU.jpg', 'https://www.youtube.com/watch?v=SK_DEabMNVg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (588, 'The Threesome', 'Connor has a threesome with his long-time crush Olivia and an alluring stranger named Jenny. It surprisingly serves as the spark to a full blown relationship with Olivia, until both women end up pregnant and all three are thrust into a difficult journey toward new realities that none of them could have expected.', 'Chad Hartigan', 112, '2025-09-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7vQUAw3CX60dhzgzC7BQZFN7Y31.jpg', 'https://www.youtube.com/watch?v=0ClkglwGNg4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (589, 'Highest 2 Lowest', 'When a titan music mogul, widely known as having the "best ears in the business", is targeted with a ransom plot, he is jammed up in a life-or-death moral dilemma.', 'Spike Lee', 133, '2025-08-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/RFQtinuiHhOnbmJaCn3uzegCYF.jpg', 'https://www.youtube.com/watch?v=Sh8yqcozfn8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (590, 'How to Be Single', 'New York City is full of lonely hearts seeking the right match, and what Alice, Robin, Lucy, Meg, Tom and David all have in common is the need to learn how to be single in a world filled with ever-evolving definitions of love.', 'Christian Ditter', 110, '2016-02-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/a4Ce3qHqIyHM3QfGsiVTAu3YADJ.jpg', 'https://www.youtube.com/watch?v=akwGjUeU6YA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (591, 'Dolittle', 'After losing his wife seven years earlier, the eccentric Dr. John Dolittle, famed doctor and veterinarian of Queen Victoria’s England, hermits himself away behind the high walls of Dolittle Manor with only his menagerie of exotic animals for company. But when the young queen falls gravely ill, a reluctant Dolittle is forced to set sail on an epic adventure to a mythical island in search of a cure, regaining his wit and courage as he crosses old adversaries and discovers wondrous creatures.', 'Stephen Gaghan', 101, '2020-01-02', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3Nt3v1uzUgfSuVARD1AnI9g9Zl9.jpg', 'https://www.youtube.com/watch?v=FEf412bSPLs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (592, 'Argylle', 'When the plots of reclusive author Elly Conway''s fictional espionage novels begin to mirror the covert actions of a real-life spy organization, quiet evenings at home become a thing of the past. Accompanied by her cat Alfie and Aidan, a cat-allergic spy, Elly races across the world to stay one step ahead of the killers as the line between Conway''s fictional world and her real one begins to blur.', 'Matthew Vaughn', 139, '2024-01-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/siduVKgOnABO4WH4lOwPQwaGwJp.jpg', 'https://www.youtube.com/watch?v=Sy6eNs3EW3E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (593, 'The Hunt', 'Twelve strangers wake up in a clearing. They don''t know where they are—or how they got there. In the shadow of a dark internet conspiracy theory, ruthless elitists gather at a remote location to hunt humans for sport. But their master plan is about to be derailed when one of the hunted turns the tables on her pursuers.', 'Craig Zobel', 90, '2020-03-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wxPhn4ef1EAo5njxwBkAEVrlJJG.jpg', 'https://www.youtube.com/watch?v=sowGYbxTPgU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (594, 'The Pickup', 'A routine cash pickup takes a wild turn when mismatched armored truck drivers Russell and Travis are ambushed by ruthless criminals led by savvy mastermind Zoe.', 'Tim Story', 94, '2025-07-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vFWvWhfAvij8UIngg2Vf6JV95Cr.jpg', 'https://www.youtube.com/watch?v=YIcga73lPFE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (595, 'Mother Mary', 'Long-buried wounds rise to the surface when iconic pop star Mother Mary reunites with her estranged best friend and former costume designer Sam Anselm on the eve of her comeback performance.', 'David Lowery', 112, '2026-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uVcsN3yoHh7ZcJ6ecj1FJfv7dLa.jpg', 'https://www.youtube.com/watch?v=6VLbjGVXMYI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (596, 'Just Play Dead', 'A criminal mastermind plans to fake his death for insurance money while framing his wife''s lover. His wife plots to kill him for real and take it all. Both race to outmanoeuvre each other in a deadly battle of wits.', 'Martin Campbell', 97, '2026-08-28', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/e0WaDBrrBAMcq2stAXCR7rXEsiw.jpg', 'https://www.youtube.com/watch?v=LfpPh2pW0Oo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (597, 'The Lego Ninjago Movie', 'Six young ninjas are tasked with defending their island home of Ninjago. By night, they’re gifted warriors using their skill and awesome fleet of vehicles to fight villains and monsters. By day, they’re ordinary teens struggling against their greatest enemy....high school.', 'Bob Logan, Charlie Bean, Paul Fisher', 101, '2017-09-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vUo0pNXGhp2ffTJxiStWt6fHL7F.jpg', 'https://www.youtube.com/watch?v=N0csmPZzYH0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (598, 'Creed III', 'After dominating the boxing world, Adonis Creed has thrived in his career and family life. When a childhood friend and former boxing prodigy, Damian Anderson, resurfaces after serving a long sentence in prison, he is eager to prove that he deserves his shot in the ring. The face-off between former friends is more than just a fight. To settle the score, Adonis must put his future on the line to battle Damian — a fighter with nothing to lose.', 'Michael B. Jordan', 116, '2023-03-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/cvsXj3I9Q2iyyIo95AecSd1tad7.jpg', 'https://www.youtube.com/watch?v=AHmCH7iB_IM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (599, 'Cocaine Bear', 'Inspired by a true story, an oddball group of cops, criminals, tourists and teens converge in a Georgia forest where a 500-pound black bear goes on a murderous rampage after unintentionally ingesting cocaine.', 'Elizabeth Banks', 95, '2023-02-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gOnmaxHo0412UVr1QM5Nekv1xPi.jpg', 'https://www.youtube.com/watch?v=DuWEEKeJLMI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (600, 'The Ugly Stepsister', 'In a fairy-tale kingdom where beauty is a brutal business, Elvira battles to compete with her incredibly beautiful stepsister, Agnes, and she will go to any length to catch the Prince’s eye.', 'Emilie Blichfeldt', 109, '2025-03-07', 'T18', 'no', 'https://image.tmdb.org/t/p/w500/rayAREIKtSinuov10GvrZHyXfXH.jpg', 'https://www.youtube.com/watch?v=5vZ1_Yxjwzs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
