  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (601, 'Expend4bles', 'Armed with every weapon they can get their hands on and the skills to use them, The Expendables are the world’s last line of defense and the team that gets called when all other options are off the table. But new team members with new styles and tactics are going to give “new blood” a whole new meaning.', 'Scott Waugh', 103, '2023-09-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iwsMu0ehRPbtaSxqiaUDQB9qMWT.jpg', 'https://www.youtube.com/watch?v=Cm3Z1jEjHHc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (602, 'The Magnificent Seven', 'Looking to mine for gold, greedy industrialist Bartholomew Bogue seizes control of the Old West town of Rose Creek. With their lives in jeopardy, Emma Cullen and other desperate residents turn to bounty hunter Sam Chisolm for help. Chisolm recruits an eclectic group of gunslingers to take on Bogue and his ruthless henchmen. With a deadly showdown on the horizon, the seven mercenaries soon find themselves fighting for more than just money once the bullets start to fly.', 'Antoine Fuqua', 132, '2016-09-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ezcS78TIjgr85pVdaPDd2rSPVNs.jpg', 'https://www.youtube.com/watch?v=q-RBA0xoaWU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (603, 'The Count of Monte Cristo', 'Edmond Dantès becomes the target of a sinister plot and is arrested on his wedding day for a crime he did not commit. After 14 years in the island prison of Château d’If, he manages a daring escape. Now rich beyond his dreams, he assumes the identity of the Count of Monte-Cristo and exacts his revenge on the three men who betrayed him.', 'Alexandre de La Patellière, Matthieu Delaporte', 178, '2024-06-28', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/sAT1P3FGhtJ68anUyJScnMu8t1l.jpg', 'https://www.youtube.com/watch?v=8Q6y1waxlTY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (604, 'Uncut Gems', 'A charismatic New York City jeweler always on the lookout for the next big score makes a series of high-stakes bets that could lead to the windfall of a lifetime. Howard must perform a precarious high-wire act, balancing business, family, and encroaching adversaries on all sides in his relentless pursuit of the ultimate win.', 'Benny Safdie, Josh Safdie', 136, '2019-12-13', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/6XN1vxHc7kUSqNWtaQKN45J5x2v.jpg', 'https://www.youtube.com/watch?v=akKdBkmugEI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (605, 'Modha Rathri', 'Two strangers are brought together at an unusual wedding where, in one night, too many surprises unfold and several lies are told, spiraling into chaos that changes everything.', 'Raja Karuppasamy', 141, '2026-08-21', 'P', 'ta', 'https://image.tmdb.org/t/p/w500/3VuNFeniljhEe9MDW12MnDbETgH.jpg', 'https://www.youtube.com/watch?v=UrWrvwIRnqk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (606, 'After', 'Tessa Young is a dedicated student, dutiful daughter and loyal girlfriend to her high school sweetheart. Entering her first semester of college, Tessa''s guarded world opens up when she meets Hardin Scott, a mysterious and brooding rebel who makes her question all she thought she knew about herself -- and what she wants out of life.', 'Jenny Gage', 106, '2019-04-11', 'K', 'en', 'https://image.tmdb.org/t/p/w500/u3B2YKUjWABcxXZ6Nm9h10hLUbh.jpg', 'https://www.youtube.com/watch?v=2ZAdcWHuCmY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (607, 'Kill Code', 'North America has been divided into four main quadrants. A power-hungry corporation has taken over the conventional prison system and made criminals the new law enforcers. The owner of that corporation, nanoscientist Eion Prescott, created a nano-virus called Onyx. Which is distributed through deadly watches to criminals. First, infecting them. Then, forcing them into eliminating each other for freedom. Who can topple the corporation''s entire system from within?', 'Justin Price', 87, '2026-04-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bXvSKLCillha6wxY0yxoRCM2WQl.jpg', 'https://www.youtube.com/watch?v=HlIKFktkF_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (608, 'Onward', 'In a suburban fantasy world, two teenage elf brothers embark on an extraordinary quest to discover if there is still a little magic left out there.', 'Dan Scanlon', 102, '2020-02-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/f4aul3FyD3jv3v4bul1IrkWZvzq.jpg', 'https://www.youtube.com/watch?v=A5Z7QsRGxGo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (609, 'Madame Web', 'Forced to confront revelations about her past, paramedic Cassandra Webb forges a relationship with three young women destined for powerful futures...if they can all survive a deadly present.', 'SJ Clarkson', 117, '2024-02-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rULWuutDcN5NvtiZi4FRPzRYWSh.jpg', 'https://www.youtube.com/watch?v=s_76M4c4LTo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (610, 'The Lego Movie 2: The Second Part', 'It''s been five years since everything was awesome and the citizens are facing a huge new threat: LEGO DUPLO® invaders from outer space, wrecking everything faster than they can rebuild.', 'Mike Mitchell', 107, '2019-02-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/QTESAsBVZwjtGJNDP7utiGV37z.jpg', 'https://www.youtube.com/watch?v=XvHSlHhh1gk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (611, 'Dumb Money', 'Vlogger Keith Gill sinks his life savings into GameStop stock and posts about it. When social media starts blowing up, so do his life and the lives of everyone following him. As a stock tip becomes a movement, everyone gets rich—until the billionaires fight back, and both sides find their worlds turned upside down.', 'Craig Gillespie', 105, '2023-09-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/e9u7luSxFKOZgPTB9XHFnPArGdP.jpg', 'https://www.youtube.com/watch?v=_VxRoOZNaR8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (612, 'Red Sparrow', 'Prima ballerina Dominika Egorova faces a bleak and uncertain future after she suffers an injury that ends her career. She soon turns to Sparrow School, a secret intelligence service that trains exceptional young people to use their minds and bodies as weapons. Dominika emerges as the most dangerous Sparrow after completing the sadistic training process. As she comes to terms with her new abilities, she meets a CIA agent who tries to convince her that he is the only person she can trust.', 'Francis Lawrence', 140, '2018-02-28', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cdefNr6aS00IwVbSlxdFJnfmzKh.jpg', 'https://www.youtube.com/watch?v=PmUL6wMpMWw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (613, 'Logan Lucky', 'Trying to reverse a family curse, brothers Jimmy and Clyde Logan set out to execute an elaborate robbery during the legendary Coca-Cola 600 race at the Charlotte Motor Speedway.', 'Steven Soderbergh', 119, '2017-08-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mQrhrBaaHvRfBQq0Px3HtVbH9iE.jpg', 'https://www.youtube.com/watch?v=aPzvKH8AVf0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (614, 'Miss Peregrine''s Home for Peculiar Children', 'A teenager finds himself transported to an island where he must help protect a group of orphans with special powers from creatures intent on destroying them.', 'Tim Burton', 127, '2016-09-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/CIlbMFOfYDj0MP23hsIYhFGrL6.jpg', 'https://www.youtube.com/watch?v=DN1uhnnKscY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (615, 'The 5th Wave', '16-year-old Cassie Sullivan tries to survive in a world devastated by the waves of an alien invasion that has already decimated the population and knocked mankind back to the Stone Age.', 'J Blakeson', 112, '2016-01-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4Dd79cz5qxKNoKWg1xsfrpOchEr.jpg', 'https://www.youtube.com/watch?v=JDJj9X0ZAsM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (616, 'The Lighthouse', 'Two lighthouse keepers try to maintain their sanity while living on a remote and mysterious New England island in the 1890s.', 'Robert Eggers', 109, '2019-10-18', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/yAKNmpcUweGH6WMCEWenwU9PsbE.jpg', 'https://www.youtube.com/watch?v=42_UHhpq530', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (617, 'Good Boys', 'A group of young boys on the cusp of becoming teenagers embark on an epic quest to fix their broken drone before their parents get home.', 'Gene Stupnitsky', 90, '2019-08-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tximyCXMEnWIIyOy9STkOduUprG.jpg', 'https://www.youtube.com/watch?v=rF1F9dIbNqM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (618, 'The Invisible Man', 'When Cecilia''s abusive ex takes his own life and leaves her his fortune, she suspects his death was a hoax. As a series of coincidences turn lethal, Cecilia works to prove that she is being hunted by someone nobody can see.', 'Leigh Whannell', 124, '2020-02-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5EufsDwXdY2CVttYOk2WtYhgKpa.jpg', 'https://www.youtube.com/watch?v=WO_FJdiY9dA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (619, 'Den of Thieves', 'A gritty crime saga which follows the lives of an elite unit of the LA County Sheriff''s Dept. and the state''s most successful bank robbery crew as the outlaws plan a seemingly impossible heist on the Federal Reserve Bank.', 'Christian Gudegast', 140, '2018-01-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dAP5NpkrMMczir5dUPjRR6ywqgz.jpg', 'https://www.youtube.com/watch?v=CZkUlNwiEBY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (620, 'The Boss Baby: Family Business', 'The Templeton brothers — Tim and his Boss Baby little bro Ted — have become adults and drifted away from each other. But a new boss baby with a cutting-edge approach and a can-do attitude is about to bring them together again … and inspire a new family business.', 'Tom McGrath', 107, '2021-07-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aQ7huOn3F0iJCJrFezS8p9WEsri.jpg', 'https://www.youtube.com/watch?v=-rF2j6K5FoM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (621, 'The Roses', 'Life seems easy for picture-perfect couple Ivy and Theo: successful careers, a loving marriage, great kids. But beneath the façade of their supposed ideal life, a storm is brewing – as Theo''s career nosedives while Ivy''s own ambitions take off, a tinderbox of fierce competition and hidden resentment ignites.', 'Jay Roach', 105, '2025-08-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/99O8HLHklXGzvF2TqiRqr7WddzT.jpg', 'https://www.youtube.com/watch?v=XkgMaS5gbaA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (622, 'Rogue One: A Star Wars Story', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.', 'Gareth Edwards', 133, '2016-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', 'https://www.youtube.com/watch?v=Wji-BZ0oCwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (623, 'Land of Bad', 'When a Delta Force special ops mission goes terribly wrong, Air Force drone pilot Reaper has 48 hours to remedy what has devolved into a wild rescue operation. With no weapons and no communication other than the drone above, the ground mission suddenly becomes a full-scale battle when the team is discovered by the enemy.', 'William Eubank', 113, '2024-02-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/h3jYanWMEJq6JJsCopy1h7cT2Hs.jpg', 'https://www.youtube.com/watch?v=dKcHOR-V1G4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (624, 'Love Me Love Me', 'After her brother''s death, June moves to Milan for a fresh start, finding comfort in Will, the perfect honor student at her new international school. But when his troubled best friend James—hiding a dangerous life in clandestine MMA fights—sparks a rivalry that quickly turns into irresistible attraction, June must choose between safety and a love that upends everything she thought she wanted.', 'Roger Kumble', 99, '2026-02-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jfwHKRHRE2X4NTexdzblaioHH51.jpg', 'https://www.youtube.com/watch?v=B7prWpweShU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (625, 'Deepwater Horizon', 'A story set on the offshore drilling rig Deepwater Horizon, which exploded during April 2010 and created the worst oil spill in U.S. history.', 'Peter Berg', 107, '2016-09-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jgBIYCZACe3iaS9TL2XzVGkO5p5.jpg', 'https://www.youtube.com/watch?v=8yASbM8M2vg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (626, 'Rebel Moon - Part One: A Child of Fire', 'When the ruthless forces of the Motherworld threaten a quiet farming village on a distant moon, a mysterious outsider becomes its best hope for survival.', 'Zack Snyder', 134, '2023-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ui4DrH1cKk2vkHshcUcGt2lKxCm.jpg', 'https://www.youtube.com/watch?v=_rHLOXbFZtI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (627, 'Beast', 'MMA legend Patton James, now a commercial fisherman, is pulled back into the cage when his brother is in danger. Reuniting with his old coach Sammy, he commits to one final fight in one championship against the brutal champion Xavier Grau.', 'Tyler Atkins', 115, '2026-04-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7NrvUI3vnW8H3rD7ExKcTL7KRcQ.jpg', 'https://www.youtube.com/watch?v=yJN2mJ4uOas', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (628, 'David', 'From the songs of his mother’s heart to the whispers of a faithful God, David’s story begins in quiet devotion. When the giant Goliath rises to terrorize a nation, a young shepherd armed with only a sling, a few stones, and unshakable faith steps forward. Pursued by power and driven by purpose, his journey tests the limits of loyalty, love, and courage—culminating in a battle not just for a crown, but for the soul of a kingdom.', 'Brent Dawes, Phil Cunningham', 109, '2025-12-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/bESlrLOrsQ9gKzaGQGHXKOyIUtX.jpg', 'https://www.youtube.com/watch?v=gWgyI6_lR0A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (629, 'Red Notice', 'An Interpol-issued Red Notice is a global alert to hunt and capture the world''s most wanted. But when a daring heist brings together the FBI''s top profiler and two rival criminals, there''s no telling what will happen.', 'Rawson Marshall Thurber', 118, '2021-11-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lAXONuqg41NwUMuzMiFvicDET9Y.jpg', 'https://www.youtube.com/watch?v=Pj0wz7zu3Ms', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (630, 'Hungry', 'A group of holidaymakers must fight for their lives against a rampaging hippo on the loose after becoming lost in the Louisiana swamplands.', 'James Nunn', 93, '2026-06-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4uNhvGxBDiO0mU5UhxuXBsJwKF3.jpg', 'https://www.youtube.com/watch?v=QX85JymdGnQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (631, 'Cosmic Princess Kaguya!', 'Iroha''s life gets knocked off its orbit when Kaguya, a carefree runaway from the Moon, moves in and convinces her to perform in a virtual world together.', 'Shingo Yamashita', 141, '2026-01-22', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/9I9cM38gecZcwJ0C6r0cwfvtPJP.jpg', 'https://www.youtube.com/watch?v=5I8vubBZOb4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (632, 'Ron''s Gone Wrong', 'In a world where walking, talking, digitally connected bots have become children''s best friends, an 11-year-old finds that his robot buddy doesn''t quite work the same as the others do.', 'Jean-Philippe Vine, Sarah Smith', 107, '2021-10-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/plzgQAXIEHm4Y92ktxU6fedUc0x.jpg', 'https://www.youtube.com/watch?v=8I8nMtzN05s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (633, 'Ghostbusters: Frozen Empire', 'The Spengler family returns to where it all started - the iconic New York City firehouse - to team up with the original Ghostbusters, who''ve developed a top-secret research lab to take busting ghosts to the next level. But when the discovery of an ancient artifact unleashes an evil force, Ghostbusters new and old must join forces to protect their home and save the world from a second Ice Age.', 'Gil Kenan', 115, '2024-03-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/e1J2oNzSBdou01sUvriVuoYp0pJ.jpg', 'https://www.youtube.com/watch?v=6VKmGxhF-GY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (634, 'Napoleon', 'An epic that details the checkered rise and fall of French Emperor Napoleon Bonaparte and his relentless journey to power through the prism of his addictive, volatile relationship with his wife, Josephine.', 'Ridley Scott', 158, '2023-11-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ytFOXyghxLzAM4KZyazDdEkM66q.jpg', 'https://www.youtube.com/watch?v=1DJYiG6wh0w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (635, 'The BFG', 'An orphan little girl befriends a benevolent giant who takes her to Giant Country, where they attempt to stop the man-eating giants that are invading the human world.', 'Steven Spielberg', 117, '2016-06-01', 'P', 'en', 'https://image.tmdb.org/t/p/w500/w17Mc2x2olB5CtewznUFxgpvne0.jpg', 'https://www.youtube.com/watch?v=Y6ZbRD1T7uI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (636, 'Three Billboards Outside Ebbing, Missouri', 'After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', 'Martin McDonagh', 115, '2017-12-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bRYLt8fV82tdVoDppSFTZIcJiLN.jpg', 'https://www.youtube.com/watch?v=Jit3YhGx5pU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (637, 'The Gray Man', 'When a shadowy CIA agent uncovers damning agency secrets, he''s hunted across the globe by a sociopathic rogue operative who''s put a bounty on his head.', 'Anthony Russo, Joe Russo', 128, '2022-07-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8cXbitsS6dWQ5gfMTZdorpAAzEH.jpg', 'https://www.youtube.com/watch?v=BmllggGO4pM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (638, 'Geostorm', 'After an unprecedented series of natural disasters threatened the planet, the world''s leaders came together to create an intricate network of satellites to control the global climate and keep everyone safe. But now, something has gone wrong: the system built to protect Earth is attacking it, and it becomes a race against the clock to uncover the real threat before a worldwide geostorm wipes out everything and everyone along with it.', 'Dean Devlin', 109, '2017-10-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nrsx0jEaBgXq4PWo7SooSnYJTv.jpg', 'https://www.youtube.com/watch?v=EuOlYPSEzSc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (639, 'Murder on the Orient Express', 'Genius Belgian detective Hercule Poirot investigates the murder of an American tycoon aboard the Orient Express train.', 'Kenneth Branagh', 114, '2017-11-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7GtdJU6iAg6fjQu3E3zta3bIAQh.jpg', 'https://www.youtube.com/watch?v=Mq4m3yAoW8E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (640, 'Nuremberg', 'In postwar Germany, an American psychiatrist must determine whether Nazi prisoners are fit to go on trial for war crimes, and finds himself in a complex battle of intellect and ethics with Hermann Göring, Hitler''s right-hand man.', 'James Vanderbilt', 149, '2025-11-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xthXNYltOOm80vW5Kxjzxx5gvQ6.jpg', 'https://www.youtube.com/watch?v=WvAy9C-bipY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (641, 'The First Omen', 'When a young American woman is sent to Rome to begin a life of service to the church, she encounters a darkness that causes her to question her own faith and uncovers a terrifying conspiracy that hopes to bring about the birth of evil incarnate.', 'Arkasha Stevenson', 119, '2024-04-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tnsDyNNkOxYUyjD8CNJoAla6YvY.jpg', 'https://www.youtube.com/watch?v=6GMiIRitv5s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (642, 'Last Night in Soho', 'A young girl, passionate about fashion design, is mysteriously able to enter the 1960s where she encounters her idol, a dazzling wannabe singer. But 1960s London is not what it seems, and time seems to be falling apart with shady consequences.', 'Edgar Wright', 117, '2021-10-09', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/n1ZRmjlk1BJTY7aASqACfPAaLn2.jpg', 'https://www.youtube.com/watch?v=AcVnFrxjPjI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (643, 'Teenage Mutant Ninja Turtles: Mutant Mayhem', 'After years of being sheltered from the human world, the Turtle brothers set out to win the hearts of New Yorkers and be accepted as normal teenagers through heroic acts. Their new friend April O''Neil helps them take on a mysterious crime syndicate, but they soon get in over their heads when an army of mutants is unleashed upon them.', 'Jeff Rowe', 100, '2023-07-31', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gyh0eECE2IqrW8GWl3KoHBfc45j.jpg', 'https://www.youtube.com/watch?v=E4Kz4tZ6RcA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (644, 'Elvis', 'The life story of Elvis Presley as seen through the complicated relationship with his enigmatic manager, Colonel Tom Parker.', 'Baz Luhrmann', 159, '2022-06-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qBOKWqAFbveZ4ryjJJwbie6tXkQ.jpg', 'https://www.youtube.com/watch?v=Gp2BNHwbwvI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (645, 'Pokémon Detective Pikachu', 'In a world where people collect pocket-size monsters (Pokémon) to do battle, a boy comes across an intelligent monster who seeks to be a detective.', 'Rob Letterman', 105, '2019-05-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uhWvnFgg3BNlcUz0Re1HfQqIcCD.jpg', 'https://www.youtube.com/watch?v=1roy4o4tqQM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (646, 'The Foreigner', 'Quan is a humble London businessman whose long-buried past erupts in a revenge-fueled vendetta when the only person left for him to love – his teenage daughter – dies in an Irish Republican Army car bombing. His relentless search to find the terrorists leads to a cat-and-mouse conflict with a British government official whose own past may hold the clues to the identities of the elusive killers.', 'Martin Campbell', 114, '2017-09-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rwM4hzrmc5HiWfQD9ls9DL4QgGl.jpg', 'https://www.youtube.com/watch?v=r_rSAbYyIq0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (647, 'PAW Patrol: The Movie', 'Ryder and the pups are called to Adventure City to stop Mayor Humdinger from turning the bustling metropolis into a state of chaos.', 'Cal Brunker', 86, '2021-08-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jXavWyam2VPR6bOhLwwuP3K2Hw4.jpg', 'https://www.youtube.com/watch?v=LRMTr2VZcr8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (648, 'Annabelle: Creation', 'Several years after the tragic death of their little girl, a doll maker and his wife welcome a nun and several girls from a shuttered orphanage into their home, soon becoming the target of the doll maker''s possessed creation—Annabelle.', 'David F. Sandberg', 110, '2017-08-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/tb86j8jVCVsdZnzf8I6cIi65IeM.jpg', 'https://www.youtube.com/watch?v=EjZkJa6Z-SY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (649, 'Her Private Hell', 'When a mysterious mist engulfs a futuristic metropolis, unleashing a deadly and elusive entity, a troubled young woman searches for her father. Her quest collides with an American GI on a harrowing odyssey to rescue his daughter from Hell.', 'Nicolas Winding Refn', 110, '2026-07-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pyIDpB5iZMRB5PdV9an146QEXAl.jpg', 'https://www.youtube.com/watch?v=C7E-0t1TfzM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (650, 'Sicario: Day of the Soldado', 'Agent Matt Graver teams up with operative Alejandro Gillick to prevent Mexican drug cartels from smuggling terrorists across the United States border.', 'Stefano Sollima', 122, '2018-06-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qcLYofEhNh51Sk1jUWjmKHLzkqw.jpg', 'https://www.youtube.com/watch?v=Pymm6cmE9uQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
