INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (651, 'A Quiet Place: Day One', 'As New York City is invaded by alien creatures who hunt by sound, a woman named Sam fights to survive with her cat.', 'Michael Sarnoski', 100, '2024-06-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/hU42CRk14JuPEdqZG3AWmagiPAP.jpg', 'https://www.youtube.com/watch?v=E-WIb4ATfT8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (652, 'I Saw the TV Glow', 'In late-90s suburbia, a lonely teenager meets a girl at school who introduces him to a mysterious late-night T.V. show — a vision of a supernatural world pulsing beneath their own. As time goes on, however, questions begin to arise about why the show sometimes seems more real than their own lives. In the pale glow of the television, their view of reality begins to crack.', 'Jane Schoenbrun', 100, '2024-05-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hS4GYkYpN1rfl4GIxyc02sCyfAj.jpg', 'https://www.youtube.com/watch?v=kymDzCgPwj0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (653, 'The Legend of Hei 2', 'When an attack shatters the fragile peace between the spirit world and humanity, Hei teams up with Luye, the last disciple of his Shifu Wuxian, to expose a conspiracy that threatens both realms - and the bond they''ve sworn to protect.', 'Gu Jie, MTJJ', 119, '2025-07-18', 'T13', 'zh', 'https://image.tmdb.org/t/p/w500/dRCUBiTKtsmju3fmSS4MK0ywcqR.jpg', 'https://www.youtube.com/watch?v=6t-uv2Vv_vA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (654, 'Lady Bird', 'Lady Bird McPherson, a strong willed, deeply opinionated, artistic 17 year old comes of age in Sacramento. Her relationship with her mother and her upbringing are questioned and tested as she plans to head off to college.', 'Greta Gerwig', 94, '2017-09-01', 'K', 'en', 'https://image.tmdb.org/t/p/w500/gl66K7zRdtNYGrxyS2YDUP5ASZd.jpg', 'https://www.youtube.com/watch?v=cNi_HC839Wo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (655, 'Dark Waters', 'A tenacious attorney uncovers a dark secret that connects a growing number of unexplained deaths to one of the world''s largest corporations. In the process, he risks everything — his future, his family, and his own life — to expose the truth.', 'Todd Haynes', 127, '2019-11-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bzvzaHqKBSuGIIWhinTQPHvT0zf.jpg', 'https://www.youtube.com/watch?v=RvAOuhyunhY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (656, 'Young Washington', 'Before he led a nation, George Washington was a young soldier thrown into a global conflict. With alliances crumbling and war closing in, he must choose who to trust and confront the leader he''s becoming.', 'Jon Erwin', 121, '2026-07-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/6CdoTKnRQHJkjRGxTefFGkPQplB.jpg', 'https://www.youtube.com/watch?v=LJek-kc384w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (657, 'Spiral: From the Book of Saw', 'Working in the shadow of an esteemed police veteran, brash Detective Ezekiel “Zeke” Banks and his rookie partner take charge of a grisly investigation into murders that are eerily reminiscent of the city’s gruesome past. Unwittingly entrapped in a deepening mystery, Zeke finds himself at the center of the killer’s morbid game.', 'Darren Lynn Bousman', 93, '2021-05-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/cTvSDfBuXTZTdRCNduGMANd7VEP.jpg', 'https://www.youtube.com/watch?v=7dgjBjEpMsM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (658, 'Beast Race', 'In future Rio de Janeiro, a young leader of the resistance must enter a deadly parkour-inspired competition in order to save his sister''s life.', 'Ernesto Solis, Fernando Meirelles, Rodrigo Pesavento', 124, '2026-03-17', 'T16', 'pt', 'https://image.tmdb.org/t/p/w500/mwmfEqWXZG6HmAUuN5SjO8s7UNV.jpg', 'https://www.youtube.com/watch?v=JVVqUrIp05U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (659, 'Dora and the Lost City of Gold', 'Dora, a girl who has spent most of her life exploring the jungle with her parents, now must navigate her most dangerous adventure yet: high school. Always the explorer, Dora quickly finds herself leading Boots (her best friend, a monkey), Diego, and a rag tag group of teens on an adventure to save her parents and solve the impossible mystery behind a lost Inca civilization.', 'James Bobin', 102, '2019-08-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xvYCZ740XvngXK0FNeSNVTJJJ5v.jpg', 'https://www.youtube.com/watch?v=gUTtJjV852c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (660, 'Pet Sematary', 'Dr. Louis Creed and his wife, Rachel, move from Boston to Ludlow, in rural Maine, with their two young children. Hidden in the woods near the new family home, Ellie, their eldest daughter, discovers a mysterious cemetery where the pets of community members are buried.', 'Dennis Widmyer, Kevin Kölsch', 101, '2019-04-04', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/7SPhr7Qj39vbnfF9O2qHRYaKHAL.jpg', 'https://www.youtube.com/watch?v=VllcgXSIJkE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (661, 'Fifty Shades Darker', 'When a wounded Christian Grey tries to entice a cautious Ana Steele back into his life, she demands a new arrangement before she will give him another chance. As the two begin to build trust and find stability, shadowy figures from Christian’s past start to circle the couple, determined to destroy their hopes for a future together.', 'James Foley', 118, '2017-02-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/w3qa274gvca9t8pkUoG8nfQgTU3.jpg', 'https://www.youtube.com/watch?v=TUnylyz5mqQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (662, 'The Favourite', 'England, early 18th century. The close relationship between Queen Anne and Sarah Churchill is threatened by the arrival of Sarah''s cousin, Abigail Hill, resulting in a bitter rivalry between the two cousins to be the Queen''s favourite.', 'Yorgos Lanthimos', 120, '2018-11-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/cwBq0onfmeilU5xgqNNjJAMPfpw.jpg', 'https://www.youtube.com/watch?v=SYb-wkehT1g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (663, 'Pete''s Dragon', 'For years, old wood carver Mr. Meacham has delighted local children with his tales of the fierce dragon that resides deep in the woods of the Pacific Northwest. To his daughter, Grace, who works as a forest ranger, these stories are little more than tall tales... until she meets Pete, a mysterious 10-year-old with no family and no home who claims to live in the woods with a giant, green dragon named Elliott. And from Pete''s descriptions, Elliott seems remarkably similar to the dragon from Mr. Meacham''s stories. With the help of Natalie, an 11-year-old girl whose father Jack owns the local lumber mill, Grace sets out to determine where Pete came from, where he belongs, and the truth about this dragon.', 'David Lowery', 103, '2016-08-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/A9x4Ogk8KUXTfU649NS6lS9TCmu.jpg', 'https://www.youtube.com/watch?v=Xhv5Kc8dmv8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (664, 'JUJUTSU KAISEN: Execution', 'A veil abruptly descends over the busy Shibuya area amid the bustling Halloween crowds, trapping countless civilians inside. Satoru Gojo, the strongest jujutsu sorcerer, steps into the chaos. But lying in wait are curse users and spirits scheming to seal him away. Yuji Itadori, accompanied by his classmates and other top-tier jujutsu sorcerers, enters the fray in an unprecedented clash of curses — the Shibuya Incident. In the aftermath, ten colonies across Japan are transformed into dens of curses in a plan orchestrated by Noritoshi Kamo. As the deadly Culling Game starts, Special Grade sorcerer Yuta Okkotsu is assigned to carry out Yuji''s execution for his perceived crimes. A compilation movie of Shibuya Incident including the first two episodes of the Culling Games arc.', 'Shota Goshozono', 88, '2025-11-07', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/v0s3dx6am0RzfsuK3KdEy8ZoCDs.jpg', 'https://www.youtube.com/watch?v=Vo7G5Y212Gg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (665, 'Allegiant', 'Beatrice Prior and Tobias Eaton venture into the world outside of the fence and are taken into protective custody by a mysterious agency known as the Bureau of Genetic Welfare.', 'Robert Schwentke', 120, '2016-03-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/faq9JlF8znUGQ5p3En1W61Fi5p0.jpg', 'https://www.youtube.com/watch?v=ESJBomF-9Y8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (666, 'IF', 'After discovering she can see everyone''s imaginary friends, a girl embarks on a magical adventure to reconnect forgotten imaginary friends with their kids.', 'John Krasinski', 104, '2024-05-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xbKFv4KF3sVYuWKllLlwWDmuZP7.jpg', 'https://www.youtube.com/watch?v=TP47e3-nmw8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (667, 'The Green Knight', 'An epic fantasy adventure based on the timeless Arthurian legend, The Green Knight tells the story of Sir Gawain, King Arthur''s reckless and headstrong nephew, who embarks on a daring quest to confront the eponymous Green Knight, a gigantic emerald-skinned stranger and tester of men.', 'David Lowery', 130, '2021-07-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/if4hw3Ou5Sav9Em7WWHj66mnywp.jpg', 'https://www.youtube.com/watch?v=sS6ksY8xWCY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (668, 'Saccharine', 'After succumbing to an obscure weight-loss craze involving the eating of human ashes, lovelorn medical student Hana finds herself haunted by the ghost of the person she''s eating.', 'Natalie Erika James', 113, '2026-05-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bCHPB5WZy4T0Rerh1GTuQLzU0rF.jpg', 'https://www.youtube.com/watch?v=uIY13LD3RUY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (669, 'Instant Family', 'When Pete and Ellie decide to start a family, they stumble into the world of foster care adoption. They hope to take in one small child but when they meet three siblings, including a rebellious 15 year old girl, they find themselves speeding from zero to three kids overnight.', 'Sean Anders', 118, '2018-11-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xYV1mODz99w7AjKDSQ7h2mzZhVe.jpg', 'https://www.youtube.com/watch?v=IUfZq3DUd3Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (670, 'Infinite', 'Evan McCauley has skills he never learned and memories of places he has never visited. Self-medicated and on the brink of a mental breakdown, a secret group that call themselves “Infinites” come to his rescue, revealing that his memories are real.', 'Antoine Fuqua', 106, '2021-09-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/niw2AKHz6XmwiRMLWaoyAOAti0G.jpg', 'https://www.youtube.com/watch?v=a3RDnD9YVxA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (671, 'Train Dreams', 'A logger leads a life of quiet grace as he experiences love and loss during an era of monumental change in early 20th-century America.', 'Clint Bentley', 102, '2025-11-05', 'P', 'en', 'https://image.tmdb.org/t/p/w500/jnaOmD9PmAkNjgVtCn17o7clOYe.jpg', 'https://www.youtube.com/watch?v=6voWeM-xQ4Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (672, 'Emilia Pérez', 'Rita, an underrated lawyer working for a large law firm more interested in getting criminals out of jail than bringing them to justice, is hired by the leader of a criminal organization.', 'Jacques Audiard', 132, '2024-08-21', 'T18', 'fr', 'https://image.tmdb.org/t/p/w500/7seqaCaaXDNUHOx4DqwpoOH8pPa.jpg', 'https://www.youtube.com/watch?v=4h7j_EcZ5fU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (673, 'Doctor Sleep', 'Still scarred by the trauma he endured as a child at the Overlook Hotel, Dan Torrance faces the ghosts of the past when he meets Abra, a courageous teen who desperately needs his help -- and who possesses a powerful extrasensory ability called the "shine".', 'Mike Flanagan', 152, '2019-10-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p69QzIBbN06aTYqRRiCOY1emNBh.jpg', 'https://www.youtube.com/watch?v=2msJTFvhkU4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (674, 'Game Night', 'Max and Annie''s weekly game night gets kicked up a notch when Max''s brother Brooks arranges a murder mystery party -- complete with fake thugs and federal agents. So when Brooks gets kidnapped, it''s all supposed to be part of the game. As the competitors set out to solve the case, they start to learn that neither the game nor Brooks are what they seem to be. The friends soon find themselves in over their heads as each twist leads to another unexpected turn over the course of one chaotic night.', 'John Francis Daley, Jonathan Goldstein', 100, '2018-02-15', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/85R8LMyn9f2Lev2YPBF8Nughrkv.jpg', 'https://www.youtube.com/watch?v=qmxMAdV6s4U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (675, 'Ghostbusters', 'Following a ghost invasion of Manhattan, paranormal enthusiasts Erin Gilbert and Abby Yates, nuclear engineer Jillian Holtzmann, and subway worker Patty Tolan band together to stop the otherworldly threat.', 'Paul Feig', 117, '2016-07-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wJmWliwXIgZOCCVOcGRBhce7xPS.jpg', 'https://www.youtube.com/watch?v=D3i2CqernTE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (676, 'The Invisible Guest', 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.', 'Oriol Paulo', 107, '2017-01-06', 'T18', 'es', 'https://image.tmdb.org/t/p/w500/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg', 'https://www.youtube.com/watch?v=epCg2RbyF80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (677, 'Shazam! Fury of the Gods', 'Billy Batson and his foster siblings, who transform into superheroes by saying "Shazam!", are forced to get back into action and fight the Daughters of Atlas, who they must stop from using a weapon that could destroy the world.', 'David F. Sandberg', 130, '2023-03-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3GrRgt6CiLIUXUtoktcv1g2iwT5.jpg', 'https://www.youtube.com/watch?v=AIc671o9yCI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (678, 'Rambo: Last Blood', 'After fighting his demons for decades, John Rambo now lives in peace on his family ranch in Arizona, but his rest is interrupted when Gabriela, the granddaughter of his housekeeper María, disappears after crossing the border into Mexico to meet her biological father. Rambo, who has become a true father figure for Gabriela over the years, undertakes a desperate and dangerous journey to find her.', 'Adrian Grünberg', 89, '2019-09-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', 'https://www.youtube.com/watch?v=4vWg5yJuWfs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (679, 'The Father', 'A man refuses all assistance from his daughter as he ages and, as he tries to make sense of his changing circumstances, he begins to doubt his loved ones, his own mind and even the fabric of his reality.', 'Florian Zeller', 97, '2020-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pr3bEQ517uMb5loLvjFQi8uLAsp.jpg', 'https://www.youtube.com/watch?v=4TZb7YfK-JI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (680, 'Normal', 'An unassuming substitute sheriff with a troubled past responds to a bank robbery in a small, sleepy town and unknowingly uncovers something far more explosive.', 'Ben Wheatley', 91, '2026-04-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/t13MdGCKRZvkmrFW2A7Vih3QjwD.jpg', 'https://www.youtube.com/watch?v=5OndK0w1lYY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (681, '6 Underground', 'After faking his death, a tech billionaire recruits a team of international operatives for a bold and bloody mission to take down a brutal dictator.', 'Michael Bay', 128, '2019-12-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lnWkyG3LLgbbrIEeyl5mK5VRFe4.jpg', 'https://www.youtube.com/watch?v=2elnByQVXbg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (682, 'Protector', 'Nikki''s life is shattered when her daughter is kidnapped. Thrust into the criminal underworld while hunted by cops and military, she must fight to rescue her child.', 'Adrian Grünberg', 90, '2026-02-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/icOZpnGuH9YrEaW3wrw5GJaXGih.jpg', 'https://www.youtube.com/watch?v=IRKGIuL3728', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (683, 'Violent Night', 'When a team of mercenaries breaks into a wealthy family compound on Christmas Eve, taking everyone inside hostage, the team isn’t prepared for a surprise combatant: Santa Claus is on the grounds, and he’s about to show why this Nick is no saint.', 'Tommy Wirkola', 112, '2022-11-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/e8CpMgdyihz9Td7amQDqubPuzfN.jpg', 'https://www.youtube.com/watch?v=a53e4HHnx_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (684, 'Midway', 'The story of the Battle of Midway, and the leaders and soldiers who used their instincts, fortitude and bravery to overcome massive odds.', 'Roland Emmerich', 138, '2019-11-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/hj8pyoNnynGeJTAbl7jcLZO8Uhx.jpg', 'https://www.youtube.com/watch?v=Z_7eN5iloyk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (685, 'Suzume', 'Suzume, 17, lost her mother as a little girl. On her way to school, she meets a mysterious young man. But her curiosity unleashes a calamity that endangers the entire population of Japan, and so Suzume embarks on a journey to set things right.', 'Makoto Shinkai', 122, '2022-11-11', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/yStW1TXF5s7Tbtu9KjIZEaWl6HL.jpg', 'https://www.youtube.com/watch?v=9UuwS0mTBNM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (686, 'The Purge: Election Year', 'Two years after choosing not to kill the man who killed his son, former police sergeant Leo Barnes has become head of security for Senator Charlene Roan, the front runner in the next Presidential election due to her vow to eliminate the Purge. On the night of what should be the final Purge, a betrayal from within the government forces Barnes and Roan out onto the street where they must fight to survive the night.', 'James DeMonaco', 109, '2016-06-29', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gg7tlp45xqGWMra0sqQVPvybje2.jpg', 'https://www.youtube.com/watch?v=9rqIJcY9hMc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (687, 'Eternity', 'In an afterlife where souls have one week to decide where to spend eternity, Joan is faced with the impossible choice between the man she spent her life with and her first love, who died young and has waited decades for her to arrive.', 'David Freyne', 114, '2025-11-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/yiwGcjfDKXD5PqQnyKUU9kspWQQ.jpg', 'https://www.youtube.com/watch?v=GzkoY6hUvQQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (688, 'Kinds of Kindness', 'A triptych fable following a man without choice who tries to take control of his own life; a policeman who is alarmed that his wife who was missing-at-sea has returned and seems a different person; and a woman determined to find a specific someone with a special ability, who is destined to become a prodigious spiritual leader.', 'Yorgos Lanthimos', 164, '2024-05-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/50lPmjIpDs8gKfgK7fPIeKzpllh.jpg', 'https://www.youtube.com/watch?v=Kk6c7MNmTwI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (689, 'The Last Duel', 'King Charles VI declares that Knight Jean de Carrouges settle his dispute with his squire, Jacques Le Gris, by challenging him to a duel.', 'Ridley Scott', 153, '2021-10-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zjrJE0fpzPvX8saJXj8VNfcjBoU.jpg', 'https://www.youtube.com/watch?v=mgygUwPJvYk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (690, 'Passengers', 'A spacecraft traveling to a distant colony planet and transporting thousands of people has a malfunction in its sleep chambers. As a result, two passengers are awakened 90 years early.', 'Morten Tyldum', 116, '2016-12-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/jK9S6HANSf2no64v1x1HxfcpmcA.jpg', 'https://www.youtube.com/watch?v=7BWWWQzTpNU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (691, 'Eden', 'A group of disillusioned outsiders abandon modern society in search of a new beginning. Settling on a remote, uninhabited island, their utopian dream quickly unravels as they discover that the greatest threat isn’t the brutal climate or deadly wildlife, but each other.', 'Ron Howard', 129, '2025-04-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jbFEESMVbpJU8IjZBjiWGJdEsxR.jpg', 'https://www.youtube.com/watch?v=2HRB36E5N6g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (692, 'Brightburn', 'What if a child from another world crash-landed on Earth, but instead of becoming a hero to mankind, he proved to be something far more sinister?', 'David Yarovesky', 91, '2019-05-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sJWwkYc9ajwnPRSkqj8Aue5JbKz.jpg', 'https://www.youtube.com/watch?v=Z0391pRUFIY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (693, 'Borderlands', 'Returning to her home planet, an infamous bounty hunter forms an unexpected alliance with a team of unlikely heroes. Together, they battle monsters and dangerous bandits to protect a young girl who holds the key to unimaginable power.', 'Eli Roth', 101, '2024-08-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4JGoZu1ZKFpMJTWAP35PCfkMgu8.jpg', 'https://www.youtube.com/watch?v=Icnysn53neU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (694, 'The New Mutants', 'Five young mutants, just discovering their abilities while held in a secret facility against their will, fight to escape their past sins and save themselves.', 'Josh Boone', 94, '2020-08-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xiDGcXJTvu1lazFRYip6g1eLt9c.jpg', 'https://www.youtube.com/watch?v=W_vJhUAOFpI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (695, 'Enola Holmes', 'While searching for her missing mother, intrepid teen Enola Holmes uses her sleuthing skills to outsmart big brother Sherlock and help a runaway lord.', 'Harry Bradbeer', 124, '2020-09-22', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/riYInlsq2kf1AWoGm80JQW5dLKp.jpg', 'https://www.youtube.com/watch?v=1d0Zf9sXlHk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (696, 'Flight Risk', 'A pilot transports a U.S. Marshal accompanying a government witness to a trial in New York. As they cross the Alaskan wilderness, tensions soar and trust is tested, as not everyone on board is who they seem.', 'Mel Gibson', 91, '2025-01-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/q0bCG4NX32iIEsRFZqRtuvzNCyZ.jpg', 'https://www.youtube.com/watch?v=Cml3CFDBj2s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (697, 'Bird Box', 'Five years after an ominous unseen presence drives most of society to suicide, a survivor and her two children make a desperate bid to reach safety.', 'Susanne Bier', 124, '2018-12-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rGfGfgL2pEPCfhIvqHXieXFn7gp.jpg', 'https://www.youtube.com/watch?v=INJ2bPFy108', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (698, 'Hitman''s Wife''s Bodyguard', 'The world’s most lethal odd couple – bodyguard Michael Bryce and hitman Darius Kincaid – are back on another life-threatening mission. Still unlicensed and under scrutiny, Bryce is forced into action by Darius''s even more volatile wife, the infamous international con artist Sonia Kincaid. As Bryce is driven over the edge by his two most dangerous protectees, the trio get in over their heads in a global plot and soon find that they are all that stand between Europe and a vengeful and powerful madman.', 'Patrick Hughes', 117, '2021-06-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6zwGWDpY8Zu0L6W4SYWERBR8Msw.jpg', 'https://www.youtube.com/watch?v=9C0l31YcahQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (699, 'Do Not Enter', 'A group of young explorers investigates an old abandoned hotel, only to encounter a strange supernatural being and a competing group looking for a legendary hidden treasure.', 'Marc Klasfeld', 91, '2026-03-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/stM9N7eJmHKLmFR59JG4tLdN7Wk.jpg', 'https://www.youtube.com/watch?v=jbbaNL6rfEc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (700, 'Twisters', 'As storm season intensifies, the paths of former storm chaser Kate Carter and reckless social-media superstar Tyler Owens collide when terrifying phenomena never seen before are unleashed. The pair and their competing teams find themselves squarely in the paths of multiple storm systems converging over central Oklahoma in the fight of their lives.', 'Lee Isaac Chung', 123, '2024-07-10', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pjnD08FlMAIXsfOLKQbvmO0f0MD.jpg', 'https://www.youtube.com/watch?v=AZbEi95SuMg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
