  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (701, 'Warfare', 'A platoon of Navy SEALs embarks on a dangerous mission in Ramadi, Iraq, with the chaos and brotherhood of war retold through their memories of the event.', 'Alex Garland, Ray Mendoza', 95, '2025-04-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/l39TlELomwysfsr37vrvCV6rmaQ.jpg', 'https://www.youtube.com/watch?v=JER0Fkyy3tw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (702, 'Us', 'Husband and wife Gabe and Adelaide Wilson take their kids to their beach house expecting to unplug and unwind with friends. But as night descends, their serenity turns to tension and chaos when some shocking visitors arrive uninvited.', 'Jordan Peele', 116, '2019-03-14', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ux2dU1jQ2ACIMShzB3yP93Udpzc.jpg', 'https://www.youtube.com/watch?v=hNCmb-4oXJA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (703, 'Creed II', 'Between personal obligations and training for his next big fight against an opponent with ties to his family''s past, Adonis Creed is up against the challenge of his life.', 'Steven Caple Jr.', 130, '2018-11-21', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/v3QyboWRoA4O9RbcsqH8tJMe8EB.jpg', 'https://www.youtube.com/watch?v=cPNVNqn4T9I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (704, 'Men in Black: International', 'The Men in Black have always protected the Earth from the scum of the universe. In this new adventure, they tackle their biggest, most global threat to date: a mole in the Men in Black organization.', 'F. Gary Gray', 115, '2019-06-12', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/dPrUPFcgLfNbmDL8V69vcrTyEfb.jpg', 'https://www.youtube.com/watch?v=40ghX7dNuKI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (705, 'Trolls Band Together', 'When Branch''s brother, Floyd, is kidnapped for his musical talents by a pair of nefarious pop-star villains, Branch and Poppy embark on a harrowing and emotional journey to reunite the other brothers and rescue Floyd from a fate even worse than pop-culture obscurity.', 'Walt Dohrn', 91, '2023-10-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3ySgD2xwasTHOK6R9bNZiEwKgYo.jpg', 'https://www.youtube.com/watch?v=ftUpFjGKuY0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (706, 'Winnie-the-Pooh: Blood and Honey 2', 'Five months following the murders, Christopher Robin struggles to maintain a regular life while dealing with PTSD. However, deep within the 100-Acre-Wood, a destructive rage grows as Pooh, Piglet, Owl, and Tigger find their home and their lives endangered after their existence is revealed.', 'Rhys Frake-Waterfield', 93, '2024-03-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2sADrLwMQof6yYmrJRSa04tFZuS.jpg', 'https://www.youtube.com/watch?v=dgIlZOv4M-c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (707, 'Army of the Dead', 'Following a zombie outbreak in Las Vegas, a group of mercenaries take the ultimate gamble: venturing into the quarantine zone to pull off the greatest heist ever attempted.', 'Zack Snyder', 148, '2021-05-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gCIsRxzcxvmuLYeAvWgoOuSxszF.jpg', 'https://www.youtube.com/watch?v=tI1JGPhYBS8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (708, 'A Big Bold Beautiful Journey', 'Sarah and David are single strangers who meet at a mutual friend’s wedding and soon, through a surprising twist of fate, find themselves on a funny, fantastical, sweeping adventure together where they get to re-live important moments from their respective pasts, illuminating how they got to where they are in the present... and possibly getting a chance to alter their futures.', 'Kogonada', 109, '2025-09-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/uMAkmQlKthQpTMiyPAKOYK3JnMs.jpg', 'https://www.youtube.com/watch?v=7t9cPtA9St0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (709, 'Greyhound', 'A first-time captain leads a convoy of allied ships carrying thousands of soldiers across the treacherous waters of the "Black Pit" to the front lines of WWII. With no air cover protection for 5 days, the captain and his convoy must battle the surrounding enemy Nazi U-boats in order to give the allies a chance to win the war.', 'Aaron Schneider', 92, '2020-07-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/kjMbDciooTbJPofVXgAoFjfX8Of.jpg', 'https://www.youtube.com/watch?v=5Byeq_hyh2U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (710, 'Roma', 'In 1970s Mexico City, two domestic workers help a mother of four while her husband is away for an extended period of time.', 'Alfonso Cuarón', 135, '2018-11-21', 'P', 'es', 'https://image.tmdb.org/t/p/w500/dtIIyQyALk57ko5bjac7hi01YQ.jpg', 'https://www.youtube.com/watch?v=6BS27ngZtxg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (711, 'Life', 'The six-member crew of the International Space Station is tasked with studying a sample from Mars that may be the first proof of extra-terrestrial life, which proves more intelligent than ever expected.', 'Daniel Espinosa', 104, '2017-03-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/wztfli5NgYDgurVgShNflvnyA3Z.jpg', 'https://www.youtube.com/watch?v=6Eey3D-Lybk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (712, 'In the Lost Lands', 'A queen sends the powerful and feared sorceress Gray Alys to the ghostly wilderness of the Lost Lands in search of a magical power, where she and her guide, the drifter Boyce, must outwit and outfight both man and demon.', 'Paul W. S. Anderson', 101, '2025-02-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dDlfjR7gllmr8HTeN6rfrYhTdwX.jpg', 'https://www.youtube.com/watch?v=CMyrp5Vk3mU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (713, 'Peter Pan & Wendy', 'Wendy Darling, a young girl afraid to leave her childhood home behind, meets Peter Pan, a boy who refuses to grow up. Alongside her brothers and a tiny fairy, Tinker Bell, she travels with Peter to the magical world of Neverland. There, she encounters an evil pirate captain, Captain Hook, and embarks on a thrilling adventure that will change her life forever.', 'David Lowery', 106, '2023-04-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9NXAlFEE7WDssbXSMgdacsUD58Y.jpg', 'https://www.youtube.com/watch?v=9Ji5U2sTlLU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (714, 'The Three Musketeers: D''Artagnan', 'D''Artagnan, a spirited young Gascon, is left for dead after trying to save a noblewoman from being kidnapped. Once in Paris, he tries by all means to find his attackers, unaware that his quest will lead him to the very heart of a war where the future of France is at stake. Aided by King''s Musketeers Athos, Porthos and Aramis, he faces the machinations of villainous Cardinal Richelieu and Milady de Winter, while falling in love with Constance, the Queen''s confidante.', 'Martin Bourboulon', 121, '2023-04-05', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/hfExJPcbBtDeFDEb7I1By72Drlr.jpg', 'https://www.youtube.com/watch?v=IAizCzFkHI0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (715, 'Peter Rabbit', 'Peter Rabbit''s feud with Mr. McGregor escalates to greater heights than ever before as they rival for the affections of the warm-hearted animal lover who lives next door.', 'Will Gluck', 93, '2018-02-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lugOvdaNpbVGQK9TyMRDiUbLtY6.jpg', 'https://www.youtube.com/watch?v=32via095BPk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (716, 'Jujutsu Kaisen 0', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?', 'Sunghoo Park', 105, '2021-12-24', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/23oJaeBh0FDk2mQ2P240PU9Xxfh.jpg', 'https://www.youtube.com/watch?v=2docezZl574', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (717, 'The Angry Birds Movie 2', 'Red, Chuck, Bomb and the rest of their feathered friends are surprised when a green pig suggests that they put aside their differences and unite to fight a common threat. Aggressive birds from an island covered in ice are planning to use an elaborate weapon to destroy the fowl and swine.', 'Thurop Van Orman', 97, '2019-08-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ebe8hJRCwdflNQbUjRrfmqtUiNi.jpg', 'https://www.youtube.com/watch?v=RDj8Y2K0ODA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (718, 'Playdate', 'When out-of-work accountant Brian joins stay-at-home dad Jeff for a playdate with their sons, he expects a laid-back afternoon. Instead, they''re chased by mercenaries, and Brian—totally unprepared—must survive one absurd obstacle after another.', 'Luke Greenfield', 93, '2025-11-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fGodXWqJkkkbSebPIlxLSygV8GY.jpg', 'https://www.youtube.com/watch?v=xGTq0blCPVQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (719, 'The Little Things', 'Deputy Sheriff Joe "Deke" Deacon joins forces with Sgt. Jim Baxter to search for a serial killer who''s terrorizing Los Angeles. As they track the culprit, Baxter is unaware that the investigation is dredging up echoes of Deke''s past, uncovering disturbing secrets that could threaten more than his case.', 'John Lee Hancock', 128, '2021-01-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tLO1aD1ghdtVMT32z2sRmzgYKYd.jpg', 'https://www.youtube.com/watch?v=1HZAnkxdYuA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (720, 'Those Who Wish Me Dead', 'A young boy finds himself pursued by two assassins in the Montana wilderness, with a survival expert determined to protect him, and a forest fire threatening to consume them all.', 'Taylor Sheridan', 100, '2021-05-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/xCEg6KowNISWvMh8GvPSxtdf9TO.jpg', 'https://www.youtube.com/watch?v=sV6VNNjBkcE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (721, 'Halloween', 'Laurie Strode comes to her final confrontation with Michael Myers, the masked figure who has haunted her since she narrowly escaped his killing spree on Halloween night four decades ago.', 'David Gordon Green', 106, '2018-10-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/f7JAX5EGk4GgsEnus6OxyzwpFp7.jpg', 'https://www.youtube.com/watch?v=ek1ePFp-nBI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (722, 'Office Romance', 'Jackie, President and CEO of Air Cruz, runs a tight ship in her business, including a rigid anti-fraternization policy for all her employees. When a new sexy lawyer begins working for her, that policy becomes very tested.', 'Ol Parker', 115, '2026-06-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/1HRUTqEVDmJC4L6tp6zd85MI6uH.jpg', 'https://www.youtube.com/watch?v=11gcNa-TBRA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (723, 'Longlegs', 'FBI Agent Lee Harker is a gifted new recruit assigned to the unsolved case of an elusive serial killer. As the case takes complex turns, unearthing evidence of the occult, Harker discovers a personal connection to the merciless killer and must race against time to stop him before he claims the lives of another innocent family.', 'Osgood Perkins', 101, '2024-07-10', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/1EwNyiiNFd863H4e8nWEzutnZD7.jpg', 'https://www.youtube.com/watch?v=48wg-_VzD04', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (724, 'The Dark Tower', 'A boy haunted by visions of a parallel world aids its disillusioned guardian in preventing the destruction of the nexus of universes known as the Dark Tower.', 'Nikolaj Arcel', 95, '2017-08-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/i9GUSgddIqrroubiLsvvMRYyRy0.jpg', 'https://www.youtube.com/watch?v=GjwfqXTebIY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (725, 'After the Hunt', 'A college professor finds herself at a personal and professional crossroads when a star pupil levels an accusation against one of her colleagues, and a dark secret from her own past threatens to come to light.', 'Luca Guadagnino', 139, '2025-10-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ryF8QPGUGlo8gRB4OYKb4J0r3aJ.jpg', 'https://www.youtube.com/watch?v=A8R6DMlDtxk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (726, 'Saw X', 'Between the events of ''Saw'' and ''Saw II'', a sick and desperate John Kramer travels to Mexico for a risky and experimental medical procedure in hopes of a miracle cure for his cancer, only to discover the entire operation is a scam to defraud the most vulnerable. Armed with a newfound purpose, the infamous serial killer returns to his work, turning the tables on the con artists in his signature visceral way through devious, deranged, and ingenious traps.', 'Kevin Greutert', 118, '2023-09-27', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/u7Lp1Hi8aBS73jv4KRMIv5aK4ax.jpg', 'https://www.youtube.com/watch?v=t3PzUo4P21c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (727, 'Below Her Mouth', 'An unexpected affair quickly escalates into a heart-stopping reality for two women whose passionate connection changes their lives forever.', 'April Mullen', 91, '2017-02-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/tPhBftWySbanfEialbsUzOuccgN.jpg', 'https://www.youtube.com/watch?v=UlahbaaJqog', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (728, 'The Hitman''s Bodyguard', 'The world’s top bodyguard gets a new client, a hitman who must testify at the International Court of Justice. They must put their differences aside and work together to make it to the trial on time.', 'Patrick Hughes', 118, '2017-08-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/5CGjlz2vyBhW5xHW4eNOZIdgzYq.jpg', 'https://www.youtube.com/watch?v=IpKmt4MpctM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (729, 'DC League of Super-Pets', 'When Superman and the rest of the Justice League are kidnapped, Krypto the Super-Dog must convince a rag-tag shelter pack - Ace the hound, PB the potbellied pig, Merton the turtle and Chip the squirrel - to master their own newfound powers and help him rescue the superheroes.', 'Jared Stern', 105, '2022-07-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qpPMewlugFaejXjz4YNDnpTniFX.jpg', 'https://www.youtube.com/watch?v=1jkw2JPCl18', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (730, 'Central Intelligence', 'Calvin Joyner, a mild-mannered accountant whose high school glory days are long behind him, reconnects with an awkward pal from high school through Facebook. After meeting up, Calvin’s mundane life takes an unexpectedly thrilling turn when he''s thrust into the world of international espionage.', 'Rawson Marshall Thurber', 107, '2016-06-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hXQVMbRNpf7c93e8clMY4W5DRm6.jpg', 'https://www.youtube.com/watch?v=J_8OsnCTRx8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (731, 'The Woman King', 'The story of the Agojie, the all-female unit of warriors who protected the African Kingdom of Dahomey in the 1800s with skills and a fierceness unlike anything the world has ever seen, and General Nanisca as she trains the next generation of recruits and readies them for battle against an enemy determined to destroy their way of life.', 'Gina Prince-Bythewood', 135, '2022-09-16', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/438QXt1E3WJWb3PqNniK0tAE5c1.jpg', 'https://www.youtube.com/watch?v=3RDaPV_rJ1Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (732, 'Halloween Ends', 'Four years after the events of Halloween in 2018, Laurie has decided to liberate herself from fear and rage and embrace life. But when a young man is accused of killing a boy he was babysitting, it ignites a cascade of violence and terror that will force Laurie to finally confront the evil she can’t control, once and for all.', 'David Gordon Green', 111, '2022-10-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/q06saepaXeBdkMibuN4R2fXmgIw.jpg', 'https://www.youtube.com/watch?v=i_mAWKyfj6c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (733, 'Together', 'Years into their relationship, Tim and Millie find themselves at a crossroads as they move to the country, abandoning all that is familiar in their lives except each other. With tensions already flaring, a nightmarish encounter with a mysterious, unnatural force threatens to corrupt their lives, their love, and their flesh.', 'Michael Shanks', 102, '2025-07-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/80slKYVM5teFH3kz6ouWrZXveqj.jpg', 'https://www.youtube.com/watch?v=9bqIwMH3En8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (734, 'Charlie''s Angels', 'Elena Houghlin is a scientist, engineer and inventor of Calisto -- a sustainable energy source that will revolutionize the way people use power. It will be ready as soon as she works out the last issue, if not it could be turned into a dangerous weapon. But when the cutting edge technology is pushed to an investor before she can do that, Elena turns to the Townsend Agency for help. Now, it''s up to the Angels -- Jane, Sabina, and the newly recruited Elena -- to retrieve Calisto before it can be transformed into a weapon of mass destruction.', 'Elizabeth Banks', 118, '2019-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1DPUFG6QnGqzpvEaDEv7TaepycM.jpg', 'https://www.youtube.com/watch?v=RSUq4VfWfjE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (735, 'A Simple Favor', 'Stephanie, a dedicated mother and popular vlogger, befriends Emily, a mysterious upper-class woman whose son Nicky attends the same school as Miles, Stephanie''s son. When Emily asks her to pick Nicky up from school and then disappears, Stephanie undertakes an investigation that will dive deep into Emily''s cloudy past.', 'Paul Feig', 117, '2018-09-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aIYsjQM0piKc0ibPBCTWv3sqshj.jpg', 'https://www.youtube.com/watch?v=rAqMlh0b2HU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (736, 'The Pope''s Exorcist', 'Father Gabriele Amorth, Chief Exorcist of the Vatican, investigates a young boy''s terrifying possession and ends up uncovering a centuries-old conspiracy the Vatican has desperately tried to keep hidden.', 'Julius Avery', 103, '2023-04-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jFC4LS5qTAT3PinzdEzINfu1CV9.jpg', 'https://www.youtube.com/watch?v=YJXqvnT_rsk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (737, 'The Forever Purge', 'All the rules are broken as a sect of lawless marauders decides that the annual Purge does not stop at daybreak and instead should never end as they chase a group of immigrants who they want to punish because of their harsh historical past.', 'Everardo Gout', 103, '2021-06-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/lB068qa6bQ0QKYKyC2xnYGvYjl7.jpg', 'https://www.youtube.com/watch?v=xOrXpK-rUaI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (738, 'Your Fault: London', 'Nick and Noah are both embarking on life-changing adventures that are threatening to pull them apart—Nick in business with his father and Noah starting a fresh chapter at Oxford University. Now living separate lives, and meeting new people, they find themselves entangled in temptations, rivalries, and betrayals and their bond is tested like never before. As secrets unravel and temptation rises, they must fight to hold onto each other—or risk losing everything.', 'Charlotte Fassler, Dani Girdwood', 123, '2026-06-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/nLxu237EJAisFCYKK48hN9Plobx.jpg', 'https://www.youtube.com/watch?v=A3ZbjkDxYUs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (739, 'Valerian and the City of a Thousand Planets', 'In the 28th century, Valerian and Laureline are special operatives charged with keeping order throughout the human territories. On assignment from the Minister of Defense, the two undertake a mission to Alpha, an ever-expanding metropolis where species from across the universe have converged over centuries to share knowledge, intelligence, and cultures. At the center of Alpha is a mysterious dark force which threatens the peaceful existence of the City of a Thousand Planets, and Valerian and Laureline must race to identify the menace and safeguard not just Alpha, but the future of the universe.', 'Luc Besson', 137, '2017-07-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vlc95gl3PtrjxSEuM8RhTtSm2xU.jpg', 'https://www.youtube.com/watch?v=_shrCoqWh9k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (740, 'The Watchers', 'A young artist gets stranded in an extensive, immaculate forest in western Ireland, where, after finding shelter, she becomes trapped alongside three strangers, stalked by mysterious creatures each night.', 'Ishana Night Shyamalan', 102, '2024-06-06', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vZVEUPychdvZLrTNwWErr9xZFmu.jpg', 'https://www.youtube.com/watch?v=CrhrNS0JFyg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (741, 'Ferdinand', 'Ferdinand, a little bull, prefers sitting quietly under a cork tree just smelling the flowers versus jumping around, snorting, and butting heads with other bulls. As Ferdinand grows big and strong, his temperament remains mellow. But one day five men come to choose the "biggest, fastest, roughest bull" for the bullfights in Madrid— and Ferdinand is mistakenly chosen.', 'Carlos Saldanha', 108, '2017-12-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rMm94JsRfcOPiPVsTRcBiiVBOhz.jpg', 'https://www.youtube.com/watch?v=0Iiq-9fhwa0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (742, 'A Dog''s Purpose', 'A dog goes on quest to discover his purpose in life over the course of several lifetimes with multiple owners.', 'Lasse Hallström', 100, '2017-01-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/3jcNvhtVQe5Neoffdic39fRactM.jpg', 'https://www.youtube.com/watch?v=1jLOOCADTGs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (743, 'Gifted', 'Frank, a single man raising his child prodigy niece Mary, is drawn into a custody battle with his mother.', 'Marc Webb', 101, '2017-04-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7YB2YrMwIm1g8FyZtlvmVDfRnAT.jpg', 'https://www.youtube.com/watch?v=x7CAjpdRaXU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (744, 'Death Wish', 'A mild-mannered father is transformed into a killing machine after his family is torn apart by a violent act.', 'Eli Roth', 107, '2018-03-01', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/g0eEEZAqMf98ULQnoiORuazjOpn.jpg', 'https://www.youtube.com/watch?v=HzILu6yyA20', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (745, 'Home Sweet Home Alone', 'After being left at home by himself for the holidays, 10-year-old Max Mercer must work to defend his home from a married couple who tries to steal back a valuable heirloom.', 'Dan Mazer', 93, '2021-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/fP3VvqUjEBjawxZHL4sYCq2ZdJD.jpg', 'https://www.youtube.com/watch?v=2BkVf2voCr0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (746, 'The Ice Age Adventures of Buck Wild', 'The fearless one-eyed weasel Buck teams up with mischievous possum brothers Crash & Eddie as they head off on a new adventure into Buck''s home: The Dinosaur World.', 'John Donkin', 82, '2022-01-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9ginbMWmt9y7PIHW1c9hnbIVWPm.jpg', 'https://www.youtube.com/watch?v=DSbpMKROvnc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (747, 'The Money Maker', 'A Polish engineer relocates to France and becomes a legendary counterfeiter. Working solo, he crafts flawless fake francs worth millions over 14 years, earning the nickname "Cézanne of counterfeit money" for his artistic skill and output.', 'Jean-Paul Salomé', 128, '2026-01-12', 'T16', 'fr', 'https://image.tmdb.org/t/p/w500/9syq0YtiW9d9PpQ5fAgWBK6LAtb.jpg', 'https://www.youtube.com/watch?v=f_bbFLsJl9A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (748, 'Sully', 'On 15 January 2009, the world witnessed the ''Miracle on the Hudson'' when Captain ''Sully'' Sullenberger glided his disabled plane onto the Hudson River, saving the lives of all 155 souls aboard. However, even as Sully was being heralded by the public and the media for his unprecedented feat of aviation skill, an investigation was unfolding that threatened to destroy his reputation and career.', 'Clint Eastwood', 96, '2016-09-07', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/4vs83YcJ8TsabADDtaeCJ6ZTjYY.jpg', 'https://www.youtube.com/watch?v=6Tbkbx4Hz8Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (749, 'The Sea Beast', 'When a young girl stows away on the ship of a legendary sea monster hunter, they launch an epic journey into uncharted waters — and make history to boot.', 'Chris Williams', 115, '2022-06-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9Zfv4Ap1e8eKOYnZPtYaWhLkk0d.jpg', 'https://www.youtube.com/watch?v=P-E-IGQCsPo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (750, 'The Predator', 'When a young boy accidentally triggers the universe''s most lethal hunters'' return to Earth, only a ragtag crew of ex-soldiers and a disgruntled scientist can prevent the end of the human race.', 'Shane Black', 107, '2018-09-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/a3eWGF6YPF7No5Rbtjc8QpDvz7l.jpg', 'https://www.youtube.com/watch?v=50_Ala5BKBo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
