  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (751, 'Hell or High Water', 'A divorced dad and his ex-con brother resort to a desperate scheme in order to save their family''s farm in West Texas.', 'David Mackenzie', 102, '2016-08-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ljRRxqy2aXIkIBXLmOVifcOR021.jpg', 'https://www.youtube.com/watch?v=JQoqsKoJVDw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (752, 'Carry-On', 'An airport security officer races to outsmart a mysterious traveler forcing him to let a dangerous item slip onto a Christmas Eve flight.', 'Jaume Collet-Serra', 120, '2024-12-05', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/sjMN7DRi4sGiledsmllEw5HJjPy.jpg', 'https://www.youtube.com/watch?v=KS0XacjMmOc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (753, 'Mulan', 'When the Emperor of China issues a decree that one man per family must serve in the Imperial Chinese Army to defend the country from Huns, Hua Mulan, the eldest daughter of an honored warrior, steps in to take the place of her ailing father. She is spirited, determined and quick on her feet. Disguised as a man by the name of Hua Jun, she is tested every step of the way and must harness her innermost strength and embrace her true potential.', 'Niki Caro', 115, '2020-09-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/aKx1ARwG55zZ0GpRvU2WrGrCG9o.jpg', 'https://www.youtube.com/watch?v=KK8FHdFluOQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (754, 'Materialists', 'A young, ambitious New York City matchmaker finds herself torn between the perfect match and her imperfect ex.', 'Celine Song', 116, '2025-06-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eDo0pNruy0Qgj6BdTyHIR4cxHY8.jpg', 'https://www.youtube.com/watch?v=9gjeXsTsxqY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (755, 'Darkest Hour', 'In May 1940, the fate of World War II hangs on Winston Churchill, who must decide whether to negotiate with Adolf Hitler or fight on knowing that it could mean the end of the British Empire.', 'Joe Wright', 125, '2017-11-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/xa6G3aKlysQeVg9wOb0dRcIGlWu.jpg', 'https://www.youtube.com/watch?v=JQAYFbcgf60', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (756, 'Glass', 'In a series of escalating encounters, former security guard David Dunn uses his supernatural abilities to track Kevin Wendell Crumb, a disturbed man who has twenty-four personalities. Meanwhile, the shadowy presence of Elijah Price emerges as an orchestrator who holds secrets critical to both men.', 'M. Night Shyamalan', 129, '2019-01-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/svIDTNUoajS8dLEo7EosxvyAsgJ.jpg', 'https://www.youtube.com/watch?v=95ghQs5AmNk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (757, 'Society of the Snow', 'On October 13, 1972, Uruguayan Air Force Flight 571, chartered to take a rugby team to Chile, crashes into a glacier in the heart of the Andes.', 'J. A. Bayona', 143, '2023-12-15', 'P', 'es', 'https://image.tmdb.org/t/p/w500/2e853FDVSIso600RqAMunPxiZjq.jpg', 'https://www.youtube.com/watch?v=pDak4qLyF4Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (758, 'Happy Gilmore 2', 'Happy Gilmore isn''t done with golf — not by a long shot. Since his retirement after his first Tour Championship win, Gilmore returns to finance his daughter''s ballet classes.', 'Kyle Newacheck', 118, '2025-07-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/E3dPHPJigkXwuiE0n1vzz0se8a.jpg', 'https://www.youtube.com/watch?v=YKzRPFvky9Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (759, 'Asteroid City', 'In an American desert town circa 1955, the itinerary of a Junior Stargazer/Space Cadet convention is spectacularly disrupted by world-changing events.', 'Wes Anderson', 105, '2023-06-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hfo7pvL9Fys7rocfL4VOzw9qDEQ.jpg', 'https://www.youtube.com/watch?v=9FXCSXuGTF4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (760, '72 HOURS', 'To save his career, a 40-year-old ad exec joins a crew of twentysomethings for a wild Miami bachelor party after they mistakenly add him to a group chat.', 'Tim Story', 105, '2026-07-20', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/9Bu1PW2R1XayqRqnl0aDOgMcrdS.jpg', 'https://www.youtube.com/watch?v=N-J-HR3quc4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (761, 'Bumblebee', 'On the run in the year 1987, Bumblebee finds refuge in a junkyard in a small Californian beach town. Charlie, on the cusp of turning 18 and trying to find her place in the world, discovers Bumblebee, battle-scarred and broken. When Charlie revives him, she quickly learns this is no ordinary yellow VW bug.', 'Travis Knight', 114, '2018-11-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', 'https://www.youtube.com/watch?v=fAIX12F6958', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (762, 'Sausage Party', 'Hot dog Frank leads a group of supermarket products on a quest to discover the truth about their existence and what really happens when they''re chosen to leave the grocery store.', 'Conrad Vernon, Greg Tiernan', 89, '2016-07-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', 'https://www.youtube.com/watch?v=GAJrBPUVDJM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (763, 'Tell Me Softly', 'Kamila has everything under control: studies, social life, her image... Everything except the unexpected return of her neighbors, the Di Bianco brothers, after seven years of absence. Thiago stole her first kiss, and Taylor was her best friend, but now their return will turn Kami''s world upside down. Can the three overcome the past that binds them? Or will everything explode into pieces once again?', 'Denis Rovira van Boekholt', 119, '2025-12-11', 'P', 'es', 'https://image.tmdb.org/t/p/w500/6Z37lW0JfLdeFcgH9yaTyg6B9A6.jpg', 'https://www.youtube.com/watch?v=maaZ6St22b8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (764, 'Arthur the King', 'Over the course of ten days and 435 miles, an unbreakable bond is forged between pro adventure racer Michael Light and a scrappy street dog companion dubbed Arthur. As the team is pushed to their outer limits of endurance in the race, Arthur redefines what victory, loyalty and friendship truly mean.', 'Simon Cellan Jones', 107, '2024-02-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/zkKB3kOun5DKAkm61pHvLbrjxfa.jpg', 'https://www.youtube.com/watch?v=wjDJNEPghNY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (765, 'Wish', 'Asha, a sharp-witted idealist, makes a wish so powerful that it is answered by a cosmic force – a little ball of boundless energy called Star. Together, Asha and Star confront a most formidable foe - the ruler of Rosas, King Magnifico - to save her community and prove that when the will of one courageous human connects with the magic of the stars, wondrous things can happen.', 'Chris Buck, Fawn Veerasunthorn', 95, '2023-11-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/nesuSdJakNkf0zs7OfoasB6Clxf.jpg', 'https://www.youtube.com/watch?v=RUu1FjoV9Vs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (766, 'Day Shift', 'An LA vampire hunter has a week to come up with the cash to pay for his kid''s tuition and braces. Trying to make a living these days just might kill him.', 'J.J. Perry', 114, '2022-08-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tkl7n5r542S40hnYDI27lGNCACu.jpg', 'https://www.youtube.com/watch?v=GN_IwBptKi4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (767, 'We Live in Time', 'An up-and-coming chef and a recent divorcée find their lives forever changed when a chance encounter brings them together, in a decade-spanning, deeply moving romance.', 'John Crowley', 108, '2024-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oeDNBgnlGF6rnyX1P1K8Vl2f3lW.jpg', 'https://www.youtube.com/watch?v=MH02yagHaNw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (768, 'Power Rangers', 'Five ordinary teens must become something extraordinary when they learn that their small town of Angel Grove — and the world — is on the verge of being obliterated by an alien threat. Chosen by destiny, our heroes quickly discover they are the only ones who can save the planet. But to do so, they will have to overcome their real-life issues and before it’s too late, band together as the Power Rangers.', 'Dean Israelite', 124, '2017-03-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bKYKyyIv5YnisxjZtDreWtYA386.jpg', 'https://www.youtube.com/watch?v=5kIe6UZHSXw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (769, 'The Boogeyman', 'Still reeling from the tragic death of their mother, a teenage girl and her younger sister find themselves plagued by a sadistic presence in their house and struggle to get their grieving father to pay attention before it’s too late.', 'Rob Savage', 99, '2023-05-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/pYwZdnXVnVxAr7dx4MEK7tTK9gI.jpg', 'https://www.youtube.com/watch?v=DVUB1SeBXho', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (770, 'Fantasy Island', 'A group of contest winners arrive at an island hotel to live out their dreams, only to find themselves trapped in nightmare scenarios.', 'Jeff Wadlow', 109, '2020-02-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8ZMrZGGW65ePWIgRn1260nA1uUm.jpg', 'https://www.youtube.com/watch?v=9G3U5WzfN_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (771, 'The Emoji Movie', 'Gene, a multi-expressional emoji, sets out on a journey to become a normal emoji.', 'Tony Leondis', 86, '2017-07-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/60bTx5z9zL1AqCjZ0gmWoRMJ6Bb.jpg', 'https://www.youtube.com/watch?v=Rd85FEdJfTw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (772, 'Smurfs', 'When Papa Smurf is mysteriously taken by evil wizards, Razamel and Gargamel, Smurfette leads the Smurfs on a mission into the real world to save him. With the help of new friends, the Smurfs must discover what defines their destiny to save the universe.', 'Chris Miller', 89, '2025-06-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8o6lkhL32xQJeB52IIG1us5BVey.jpg', 'https://www.youtube.com/watch?v=108UjvIzE64', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (773, 'Captain Fantastic', 'Deep in the forests of the Pacific Northwest, a father devoted to raising his six kids with a rigorous physical and intellectual education is forced to leave his paradise and enter the world, beginning a journey that challenges his idea of what it means to be a parent.', 'Matt Ross', 119, '2016-07-08', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2sFME73GaD8UsUxPUKe60cPdLif.jpg', 'https://www.youtube.com/watch?v=w5jeBvjcJe4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (774, 'Fantastic Beasts: The Crimes of Grindelwald', 'Gellert Grindelwald has escaped imprisonment and has begun gathering followers to his cause—elevating wizards above all non-magical beings. The only one capable of putting a stop to him is the wizard he once called his closest friend, Albus Dumbledore. However, Dumbledore will need to seek help from the wizard who had thwarted Grindelwald once before, his former student Newt Scamander, who agrees to help, unaware of the dangers that lie ahead. Lines are drawn as love and loyalty are tested, even among the truest friends and family, in an increasingly divided wizarding world.', 'David Yates', 134, '2018-11-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fMMrl8fD9gRCFJvsx0SuFwkEOop.jpg', 'https://www.youtube.com/watch?v=5sEaYB4rLFQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (775, 'First Man', 'A look at the life of the astronaut, Neil Armstrong, and the legendary space mission that led him to become the first man to walk on the Moon on July 20, 1969.', 'Damien Chazelle', 141, '2018-10-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/i91mfvFcPPlaegcbOyjGgiWfZzh.jpg', 'https://www.youtube.com/watch?v=O9Y7DTCn7Cc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (776, 'Apocalypse Z: The Beginning of the End', 'When a kind of rabies that transforms people into aggressive creatures spreads across the planet, Manel isolates himself at home with his cat, relying on his wits to survive; but soon they must go out in search of food, by land and by sea, dodging many dangers.', 'Carles Torrens', 119, '2024-10-04', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/wIGJnIFQlESkC2rLpfA8EDHqk4g.jpg', 'https://www.youtube.com/watch?v=ZOSw6sx43fA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (777, 'The Fabelmans', 'Growing up in post-World War II era Arizona, young Sammy Fabelman aspires to become a filmmaker as he reaches adolescence, but soon discovers a shattering family secret and explores how the power of films can help him see the truth.', 'Steven Spielberg', 151, '2022-11-11', 'P', 'en', 'https://image.tmdb.org/t/p/w500/h7llKkqkkJtJrTOaDLuVeUYDQ7I.jpg', 'https://www.youtube.com/watch?v=9wAKUa487aw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (778, 'Last Breath', 'Seasoned deep-sea divers battle the raging elements to rescue their crewmate trapped hundreds of feet below the ocean''s surface.', 'Alex Parkinson', 93, '2025-02-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uB8yTnF6YLIIVKuRJAK8LNk8C6w.jpg', 'https://www.youtube.com/watch?v=sNMyooXZZTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (779, 'Dangerous Animals', 'A savvy and free-spirited surfer is abducted by a shark-obsessed serial killer. Held captive on his boat, she must figure out how to escape before he carries out a ritualistic feeding to the sharks below.', 'Sean Byrne', 98, '2025-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/9tk3Si960hg4E49eMt81dS7Qe9Z.jpg', 'https://www.youtube.com/watch?v=WR2btzjmmuc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (780, 'On Body and Soul', 'Two introverted people find out by pure chance that they share the same dream every night. They are puzzled, incredulous, a bit frightened. As they hesitantly accept this strange coincidence, they try to recreate in broad daylight what happens in their dream.', 'Ildikó Enyedi', 116, '2017-03-02', 'T13', 'hu', 'https://image.tmdb.org/t/p/w500/uguWEoZelSSckxgiQctlkZ6gpfU.jpg', 'https://www.youtube.com/watch?v=jK5tIkuTKbA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (781, 'Killer Heat', 'An expat PI is hired to investigate a suspicious death in Crete, Greece, where jealousies run deep amongst the victim''s powerful family.', 'Philippe Lacôte', 97, '2024-09-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/WiAEiqelck0NGWplhL5JQR12eg.jpg', 'https://www.youtube.com/watch?v=ADGSIaE6nzE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (782, 'The Commuter', 'A businessman, on his daily commute home, gets unwittingly caught up in a criminal conspiracy that threatens not only his life but the lives of those around him.', 'Jaume Collet-Serra', 104, '2018-01-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rDeGK6FIUfVcXmuBdEORPAGPMNg.jpg', 'https://www.youtube.com/watch?v=BN4p7XhR16A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (783, '10 Cloverfield Lane', 'After a catastrophic car crash, a young woman wakes up in a survivalist''s underground bunker, where he claims to have saved her from an apocalyptic attack that has left the outside world uninhabitable.', 'Dan Trachtenberg', 104, '2016-03-10', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg', 'https://www.youtube.com/watch?v=yQy-ANhnUpE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (784, 'The Huntsman: Winter''s War', 'As two evil sisters prepare to conquer the land, two renegades—Eric the Huntsman, who aided Snow White in defeating Ravenna in Snowwhite and the Huntsman, and his forbidden lover, Sara—set out to stop them.', 'Cedric Nicolas-Troyan', 114, '2016-04-06', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/ekHPrneEoa1EoDclWdillOKznqM.jpg', 'https://www.youtube.com/watch?v=F2-_OQL9fBk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (785, 'The Lost City of Z', 'A true-life drama in the 1920s, centering on British explorer Col. Percy Fawcett, who discovered evidence of a previously unknown, advanced civilization in the Amazon and disappeared whilst searching for it.', 'James Gray', 141, '2017-03-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8SxHVNk6tqXYwygmDzz1YuJEm2J.jpg', 'https://www.youtube.com/watch?v=AiM3cX3kSeM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (786, 'Roald Dahl''s The Witches', 'In late 1967, a young orphaned boy goes to live with his loving grandma in the rural Alabama town of Demopolis. As the boy and his grandmother encounter some deceptively glamorous but thoroughly diabolical witches, she wisely whisks him away to a seaside resort. Regrettably, they arrive at precisely the same time that the world''s Grand High Witch has gathered.', 'Robert Zemeckis', 104, '2020-10-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/betExZlgK0l7CZ9CsCBVcwO1OjL.jpg', 'https://www.youtube.com/watch?v=9nlhmJF5FNI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (787, 'Fall for Me', 'Lilli is suspicious of her sister''s new fiance, but when an attractive stranger enters her life, she''s suddenly distracted by the thralls of desire.', 'Sherry Hormann', 103, '2025-08-20', 'T16', 'de', 'https://image.tmdb.org/t/p/w500/mduZ3YRKele4rHhrse7b7B3d44b.jpg', 'https://www.youtube.com/watch?v=pgu-BsBV-2I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (788, 'The Killer''s Game', 'When top hitman Joe Flood is diagnosed with a terminal illness, he decides to take matters into his own hands – by taking a hit out on himself. But when the very hitmen he hired also target his ex-girlfriend, he must fend off an army of assassin colleagues and win back the love of his life before it''s too late.', 'J.J. Perry', 106, '2024-09-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4bKlTeOUr5AKrLky8mwWvlQqyVd.jpg', 'https://www.youtube.com/watch?v=ZHK6WghyWGY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (789, 'Orphan: First Kill', 'After escaping from an Estonian psychiatric facility, Leena Klammer travels to America by impersonating Esther, the missing daughter of a wealthy family. But when her mask starts to slip, she is put against a mother who will protect her family from the murderous “child” at any cost.', 'William Brent Bell', 99, '2022-07-27', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pHkKbIRoCe7zIFvqan9LFSaQAde.jpg', 'https://www.youtube.com/watch?v=_uX6of3vBu0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (790, 'Predator: Killer of Killers', 'While three of the fiercest warriors in human history—a Viking raider, a ninja in feudal Japan, and a WWII pilot—are killers in their own right, they are merely prey for their new opponent: the ultimate killer of killers.', 'Dan Trachtenberg', 85, '2025-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2XDQa6EmFHSA37j1t0w88vpWqj9.jpg', 'https://www.youtube.com/watch?v=eWzPKrNoSyM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (791, 'Morbius', 'Dangerously ill with a rare blood disorder, and determined to save others suffering his same fate, Dr. Michael Morbius attempts a desperate gamble. What at first appears to be a radical success soon reveals itself to be a remedy potentially worse than the disease.', 'Daniel Espinosa', 105, '2022-03-30', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/Av8Z2jZhEm1FLkFzMThzz9hndJF.jpg', 'https://www.youtube.com/watch?v=SQK-QxxtE8Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (792, 'Dirty Grandpa', 'Jason Kelly is one week away from marrying his boss''s uber-controlling daughter, putting him on the fast track for a partnership at the law firm. However, when the straight-laced Jason is tricked into driving his foul-mouthed grandfather, Dick, to Daytona for spring break, his pending nuptials are suddenly in jeopardy. Between riotous frat parties, bar fights, and an epic night of karaoke, Dick is on a quest to live his life to the fullest and bring Jason along for the ride.', 'Dan Mazer', 102, '2016-01-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/k0Lz1TfSlbcQthQKYGwE7blDfwN.jpg', 'https://www.youtube.com/watch?v=q1zlkaPpMsA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (793, 'The Banshees of Inisherin', 'Two lifelong friends find themselves at an impasse when one abruptly ends their relationship, with alarming consequences for both of them.', 'Martin McDonagh', 114, '2022-10-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4yFG6cSPaCaPhyJ1vtGOtMD1lgh.jpg', 'https://www.youtube.com/watch?v=9-R9u2UD3FU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (794, 'Robin Hood', 'A war-hardened Crusader and his Moorish commander mount an audacious revolt against the corrupt English crown.', 'Otto Bathurst', 116, '2018-11-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg', 'https://www.youtube.com/watch?v=ne7eStct3Fc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (795, 'Wish Dragon', 'Determined teen Din is longing to reconnect with his childhood best friend when he meets a wish-granting dragon who shows him the magic of possibilities.', 'Chris Appelhans', 99, '2021-01-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/lnPf6hzANL6pVQTxUlsNYSuhT5l.jpg', 'https://www.youtube.com/watch?v=uWIRyU5fuzU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (796, 'Haunted Mansion', 'A woman and her son enlist a motley crew of so-called spiritual experts to help rid their home of supernatural squatters.', 'Justin Simien', 123, '2023-07-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8Im6DknDVxRiGXc5t8rVOJyzuNx.jpg', 'https://www.youtube.com/watch?v=AjLKTz81bj8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (797, 'The Banker', 'In the 1960s, two entrepreneurs hatch an ingenious business plan to fight for housing integration—and equal access to the American Dream.', 'George Nolfi', 120, '2020-03-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/biXzsw22U6vSd0XktmZwAOc4uik.jpg', 'https://www.youtube.com/watch?v=J_-nk9-sMus', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (798, 'RRR', 'A fictional history of two legendary revolutionaries'' journey away from home before they began fighting for their country in the 1920s.', 'S. S. Rajamouli', 187, '2022-03-24', 'T16', 'te', 'https://image.tmdb.org/t/p/w500/u0XUBNQWlOvrh0Gd97ARGpIkL0.jpg', 'https://www.youtube.com/watch?v=AVVO3Yat_Bw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (799, 'The Tank', 'A German Tiger tank crew is sent on a dangerous mission to rescue the missing officer Paul von Hardenburg from a top-secret bunker behind enemy lines. As they make their way through the lethal no-man''s land, they must confront not only the enemy, but also their own fears and inner demons. Fueled by the Wehrmacht''s methamphetamine, their mission increasingly becomes a journey into the heart of darkness.', 'Dennis Gansel', 117, '2025-09-18', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/65Jr1JAgWlu9em8zHhAfrNJJQBt.jpg', 'https://www.youtube.com/watch?v=4uZWlKGRZis', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (800, 'The Zone of Interest', 'The commandant of Auschwitz, Rudolf Höss, and his wife Hedwig, strive to build a dream life for their family in a house and garden next to the camp.', 'Jonathan Glazer', 105, '2023-12-15', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hUu9zyZmDd8VZegKi1iK1Vk0RYS.jpg', 'https://www.youtube.com/watch?v=GFNtVaAuVYY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (801, 'Where the Crawdads Sing', 'Abandoned by her family, Kya raises herself all alone in the marshes outside of her small town. When her former boyfriend is found dead, Kya is instantly branded by the local townspeople and law enforcement as the prime suspect for his murder.', 'Olivia Newman', 126, '2022-07-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/n1el846gLDXfhOvrRCsyvaAOQWv.jpg', 'https://www.youtube.com/watch?v=PY3808Iq0Tg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (802, 'Nocturnal Animals', 'Susan Morrow receives a book manuscript from her ex-husband – a man she left 20 years earlier – asking for her opinion of his writing. As she reads, she is drawn into the fictional life of Tony Hastings, a mathematics professor whose family vacation turns violent.', 'Tom Ford', 116, '2016-11-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/mdLDgQBD0va09npSQX5Zgo2evXM.jpg', 'https://www.youtube.com/watch?v=JOsEU5oYpTA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (803, 'Deep Water', 'A well-to-do husband who allows his wife to have affairs in order to avoid a divorce becomes a prime suspect in the disappearance of her lovers.', 'Adrian Lyne', 116, '2022-03-17', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6yRMyWwjuhKg6IU66uiZIGhaSc8.jpg', 'https://www.youtube.com/watch?v=90JsrQwE5CA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (804, 'Smurfs: The Lost Village', 'In this fully animated, all-new take on the Smurfs, a mysterious map sets Smurfette and her friends Brainy, Clumsy and Hefty on an exciting race through the Forbidden Forest leading to the discovery of the biggest secret in Smurf history.', 'Kelly Asbury', 89, '2017-03-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/swt9crREg1UcKgg3wGWfoFNlXOz.jpg', 'https://www.youtube.com/watch?v=8LdpyRBE0aA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (805, 'Ghosted', 'Salt-of-the-earth Cole falls head over heels for enigmatic Sadie—but then makes the shocking discovery that she''s a secret agent. Before they can decide on a second date, Cole and Sadie are swept away on an international adventure to save the world.', 'Dexter Fletcher', 117, '2023-04-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/liLN69YgoovHVgmlHJ876PKi5Yi.jpg', 'https://www.youtube.com/watch?v=IAdCsNtEuBU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (806, 'Paddington 2', 'Paddington, now happily settled with the Browns, picks up a series of odd jobs to buy the perfect present for his Aunt Lucy, but it is stolen.', 'Paul King', 104, '2017-11-05', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1OJ9vkD5xPt3skC6KguyXAgagRZ.jpg', 'https://www.youtube.com/watch?v=07Um1PY_P4o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (807, 'Mike & Nick & Nick & Alice', 'Two gangsters and the woman they love try to survive the most dangerous night of their lives. As if that wasn’t enough, there’s one wild ingredient added to the mix: a time machine.', 'BenDavid Grabinski', 107, '2026-03-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7F0jc75HrSkLVcvOXR2FXAIwuEv.jpg', 'https://www.youtube.com/watch?v=pI-2t18TXqs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (808, 'Pearl', 'Trapped on her family’s isolated farm, Pearl must tend to her ailing father under the bitter and overbearing watch of her devout mother. Lusting for a glamorous life like she’s seen in the movies, Pearl’s ambitions, temptations, and repressions collide.', 'Ti West', 102, '2022-09-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ulBLIBqvdnf4H6JBt0OpMCU1ECn.jpg', 'https://www.youtube.com/watch?v=L5PW5r3pEOg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (809, 'Lightyear', 'Legendary Space Ranger Buzz Lightyear embarks on an intergalactic adventure alongside a group of ambitious recruits and his robot companion Sox.', 'Angus MacLane', 105, '2022-06-15', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ox4goZd956BxqJH6iLwhWPL9ct4.jpg', 'https://www.youtube.com/watch?v=0ir3Z8hLeHc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (810, 'Eddington', 'In May of 2020, a standoff between a small-town sheriff and mayor sparks a powder keg as neighbor is pitted against neighbor in Eddington, New Mexico.', 'Ari Aster', 148, '2025-07-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4GIqZUgPZ146BhibsPHMHef2nXX.jpg', 'https://www.youtube.com/watch?v=X0ydvsZaZb0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (811, 'Sound of Freedom', 'The story of Tim Ballard, a former US government agent, who quits his job in order to devote his life to rescuing children from global sex traffickers.', 'Alejandro Monteverde', 131, '2023-07-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/qA5kPYZA7FkVvqcEfJRoOy4kpHg.jpg', 'https://www.youtube.com/watch?v=UwSBQWI-bek', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (812, 'Paddington in Peru', 'Paddington travels to Peru to visit his beloved Aunt Lucy, who now resides at the Home for Retired Bears. With the Brown Family in tow, a thrilling adventure ensues when a mystery plunges them into an unexpected journey through the Amazon rainforest and up to the mountain peaks of Peru.', 'Dougal Wilson', 106, '2024-11-08', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1ffZAucqfvQu36x1C49XfOdjuOG.jpg', 'https://www.youtube.com/watch?v=NTvudSGfHRI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (813, 'The Old Guard', 'Four undying warriors who''ve secretly protected humanity for centuries become targeted for their mysterious powers just as they discover a new immortal.', 'Gina Prince-Bythewood', 125, '2020-07-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cjr4NWURcVN3gW5FlHeabgBHLrY.jpg', 'https://www.youtube.com/watch?v=aK-X2d0lJ_s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (814, 'The Life of Chuck', 'In this extraordinary story of an ordinary man, Charles ''Chuck'' Krantz experiences the wonder of love, the heartbreak of loss, and the multitudes contained in all of us.', 'Mike Flanagan', 111, '2025-06-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/oumprkO9bThExP8NwxBIBnvBu2v.jpg', 'https://www.youtube.com/watch?v=dOyXdwXt8d4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (815, 'Primitive War', 'During the Vietnam War, a recon unit ventures to an isolated jungle valley to uncover the fate of a missing platoon. They soon find themselves in a fight for their lives against an unexpected enemy — prehistoric dinosaurs.', 'Luke Sparke', 135, '2025-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/noujgznyJIaurEinZhcSVzTmkLo.jpg', 'https://www.youtube.com/watch?v=NfMKBKKzIXM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (816, 'The Curse of La Llorona', 'In 1970s Los Angeles, the legendary ghost La Llorona is stalking the night -- and the children. Ignoring the eerie warning of a troubled mother, a social worker and her own kids are drawn into a frightening supernatural realm. Their only hope of surviving La Llorona''s deadly wrath is a disillusioned priest who practices mysticism to keep evil at bay.', 'Michael Chaves', 93, '2019-04-17', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/hETrPpoKs6BwoilK64YJ7Z5GcRT.jpg', 'https://www.youtube.com/watch?v=ALhy6XTpMlk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (817, 'Weathering with You', 'The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.', 'Makoto Shinkai', 112, '2019-07-19', 'P', 'ja', 'https://image.tmdb.org/t/p/w500/qgrk7r1fV4IjuoeiGS5HOhXNdLJ.jpg', 'https://www.youtube.com/watch?v=Q6iK6DjV_iE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (818, 'Die My Love', 'After inheriting a remote Montana house, Jackson moves there from New York with his partner Grace, and the couple soon welcome a child. As Jackson becomes increasingly absent and rural isolation sets in, Grace struggles with loneliness, creative frustration, and unresolved emotional wounds. What begins as an attempt at renewal gradually turns into an intense psychological descent, placing strain on their relationship and exposing the fragile balance between love, identity, and motherhood.', 'Lynne Ramsay', 119, '2025-10-06', 'P', 'en', 'https://image.tmdb.org/t/p/w500/kajpShbFhOdpl6yCrLezMrr9tB4.jpg', 'https://www.youtube.com/watch?v=2jzXHW6Qe70', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (819, 'The Harder They Fall', 'Gunning for revenge, outlaw Nat Love saddles up with his gang to take down enemy Rufus Buck, a ruthless crime boss who just got sprung from prison.', 'Jeymes Samuel', 137, '2021-10-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/su9WzL7lwUZPhjH6eZByAYFx2US.jpg', 'https://www.youtube.com/watch?v=Poc55U2RPMw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (820, 'Molly''s Game', 'Molly Bloom, a young skier and former Olympic hopeful becomes a successful entrepreneur (and a target of an FBI investigation) when she establishes a high-stakes, international poker game.', 'Aaron Sorkin', 141, '2017-12-07', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zrGQwKNmAz5awZI2V1k5M4eTTTN.jpg', 'https://www.youtube.com/watch?v=9v-pw0ZQRLY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (821, 'Monster Hunter', 'A portal transports Cpt. Artemis and an elite unit of soldiers to a strange world where powerful monsters rule with deadly ferocity. Faced with relentless danger, the team encounters a mysterious hunter who may be their only hope to find a way home.', 'Paul W. S. Anderson', 103, '2020-12-03', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/1UCOF11QCw8kcqvce8LKOO6pimh.jpg', 'https://www.youtube.com/watch?v=3od-kQMTZ9M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (822, 'Megalopolis', 'In a futuristic New York known as New Rome, visionary architect Cesar Catilina dreams of building "Megalopolis," a utopian city that redefines society’s limits. Opposing him is the corrupt Mayor Franklyn Cicero, who clings to power and profit. Between them stands Julia, the mayor’s daughter, whose love for Cesar forces her to choose between loyalty, ambition, and the fate of humanity.', 'Francis Ford Coppola', 138, '2024-09-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/doVWgLdNyK36nEyyZgVsEWFCO1e.jpg', 'https://www.youtube.com/watch?v=FHYlEOK0uOE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (823, 'Love, Simon', 'Everyone deserves a great love story, but for 17-year-old Simon Spier, it''s a little more complicated. He hasn''t told his family or friends that he''s gay, and he doesn''t know the identity of the anonymous classmate that he''s fallen for online.', 'Greg Berlanti', 110, '2018-02-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/snIsqVPmlu4LPjvToHpDotxa7Eh.jpg', 'https://www.youtube.com/watch?v=E0cbWdlQg_8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (824, 'A Real Pain', 'Mismatched cousins David and Benji reunite for a tour through Poland to honor their beloved grandmother. The adventure takes a turn when the pair''s old tensions resurface against the backdrop of their family history.', 'Jesse Eisenberg', 90, '2024-11-01', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/yaTFjMNh8D78dDHrglivOTv5YOx.jpg', 'https://www.youtube.com/watch?v=E_sjoa8aHpc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (825, 'London Has Fallen', 'In London for the Prime Minister''s funeral, Mike Banning discovers a plot to assassinate all the attending world leaders.', 'Babak Najafi', 99, '2016-03-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iEbLkYzyiUdOKNK4WNBFyGH7r2Y.jpg', 'https://www.youtube.com/watch?v=oQhX4JxGHtw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (826, 'Chip ''n Dale: Rescue Rangers', 'Decades since their successful television series was canceled, Chip has succumbed to a life of suburban domesticity as an insurance salesman. Dale, meanwhile, has had CGI surgery and works the nostalgia convention circuit, desperate to relive his glory days. When a former cast mate mysteriously disappears, Chip and Dale must repair their broken friendship and take on their Rescue Rangers detective personas once again to save their friend’s life.', 'Akiva Schaffer', 99, '2022-05-20', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/7UGmn8TyWPPzkjhLUW58cOUHjPS.jpg', 'https://www.youtube.com/watch?v=RW0xBFB-QLw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (827, 'The Strangers: Chapter 3', 'Tethered by a frightening conclusion, Maya and the Strangers are locked on an unavoidable, unforgiving collision course — a showdown that proves they’re far from strangers now.', 'Renny Harlin', 92, '2026-02-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dWi4D1rUX1Pg4MaafpwwssqJ9lv.jpg', 'https://www.youtube.com/watch?v=B2fZEIHamVs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (828, 'Brothers Under Fire', 'Captain Jordan Wright''s squadron on leave for a wedding in Mexico encounters a murderous cartel. As Jordan tries to lead survivors to safety, war erupts between his squad and the cartel, forcing him into a battle to save his men.', 'Justin Chadwick', 99, '2026-04-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/e5EKqk9V7N3w0WvYFhl6wSVrMp0.jpg', 'https://www.youtube.com/watch?v=4R6mxR53m10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (829, 'Peninsula', 'A soldier and his team battle hordes of post-apocalyptic zombies in the wastelands of the Korean Peninsula.', 'Yeon Sang-ho', 116, '2020-07-15', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/eeqvAzCccAZOhU3RfbvHB3s44S6.jpg', 'https://www.youtube.com/watch?v=cRvHl1dThlg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (830, 'The Wailing', 'A stranger arrives in a little village and soon after a mysterious sickness starts spreading. A policeman is drawn into the incident and is forced to solve the mystery in order to save his daughter.', 'Na Hong-jin', 156, '2016-05-12', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/lWE9ih9qgjx8HatYboP7fG0nri.jpg', 'https://www.youtube.com/watch?v=43uAputjI4k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (831, 'Sniper: No Nation', 'Brandon Beckett and Agent Zero lead a rescue mission in Costa Verde when their friends are taken hostage.', 'Trevor Calverley', 96, '2026-03-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tUmARo0TZEK1EaSuS6dU35FhDyU.jpg', 'https://www.youtube.com/watch?v=-smVu1cxPm8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (832, 'Guillermo del Toro''s Pinocchio', 'During the rise of fascism in Mussolini''s Italy, a wooden boy brought magically to life struggles to live up to his father''s expectations.', 'Guillermo del Toro, Mark Gustafson', 117, '2022-11-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vx1u0uwxdlhV2MUzj4VlcMB0N6m.jpg', 'https://www.youtube.com/watch?v=Od2NW1sfRdA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (833, 'Nightmare Alley', 'An ambitious carnival man with a talent for manipulating people with a few well-chosen words hooks up with a female psychologist who is even more dangerous than he is.', 'Guillermo del Toro', 151, '2021-12-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vfn1feL0V9HNSXuLLpaxAW8O6LO.jpg', 'https://www.youtube.com/watch?v=Q81Yf46Oj3s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (834, 'To All the Boys I''ve Loved Before', 'Lara Jean''s love life goes from imaginary to out of control when her secret letters to every boy she''s ever fallen for are mysteriously mailed out.', 'Susan Johnson', 100, '2018-08-17', 'K', 'en', 'https://image.tmdb.org/t/p/w500/hKHZhUbIyUAjcSrqJThFGYIR6kI.jpg', 'https://www.youtube.com/watch?v=555oiY9RWM4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (835, 'Don''t Worry Darling', 'Alice and Jack are lucky to be living in the idealized community of Victory, the experimental company town housing the men who work for the top-secret Victory Project and their families. But when cracks in their idyllic life begin to appear, exposing flashes of something much more sinister lurking beneath the attractive façade, Alice can’t help questioning exactly what they’re doing in Victory, and why.', 'Olivia Wilde', 123, '2022-09-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wjAJWfuE5OQm5zerlOAbTxdHFMV.jpg', 'https://www.youtube.com/watch?v=FgmnKsED-jU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (836, 'M3GAN', 'A brilliant toy company roboticist uses artificial intelligence to develop M3GAN, a life-like doll programmed to emotionally bond with her newly orphaned niece. But when the doll''s programming works too well, she becomes overprotective of her new friend with terrifying results.', 'Gerard Johnstone', 102, '2022-12-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/d9nBoowhjiiYc4FBNtQkPY7c11H.jpg', 'https://www.youtube.com/watch?v=BRb4U99OU80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (837, 'Flora and Son', 'Single mom Flora is at a loss about what to do with her rebellious teenage son, Max. Her efforts to keep him out of trouble lead to a beat-up acoustic guitar, a washed-up LA musician, and harmony for this frayed Dublin family.', 'John Carney', 97, '2023-09-21', 'P', 'en', 'https://image.tmdb.org/t/p/w500/pq2p8ovf8PZps2HafvJaLrZK8gS.jpg', 'https://www.youtube.com/watch?v=beNTTHnMIy8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (838, 'The Grudge', 'After a young mother murders her family in her own house, a detective attempts to investigate the mysterious case, only to discover that the house is cursed by a vengeful ghost. Now targeted by the demonic spirits, the detective must do anything to protect herself and her family from harm.', 'Nicolas Pesce', 94, '2019-12-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vN7JHlHOT9rHNDU27tfYqhABBj5.jpg', 'https://www.youtube.com/watch?v=O2NKzO-fxwQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (839, 'After Everything', 'Besieged by writer’s block and the crushing breakup with Tessa, Hardin travels to Portugal in search of a woman he wronged in the past – and to find himself. Hoping to win back Tessa, he realizes he needs to change his ways before he can make the ultimate commitment.', 'Castille Landon', 93, '2023-09-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/uQxjZGU6rxSPSMeAJPJQlmfV3ys.jpg', 'https://www.youtube.com/watch?v=NsmopvKNSE4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (840, 'Ballerina', 'In 1879 Paris, a young orphan dreams of becoming a ballerina and flees her rural Brittany for Paris, where she passes for someone else and accedes to the position of pupil at the Grand Opera house.', 'Eric Summer, Éric Warin', 89, '2016-12-14', 'K', 'en', 'https://image.tmdb.org/t/p/w500/qBxMhcmNnFniuDAZTKEHcSgKtsn.jpg', 'https://www.youtube.com/watch?v=FsNJBRDbZBE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (841, 'The Platform', 'A slab of food descends down a vertical facility. The residents above eat heartily, leaving those below starving and desperate. A rebellion is imminent.', 'Galder Gaztelu-Urrutia', 95, '2019-11-08', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/iXvQnzy6JCAx1PiQEKXuTY04ZHl.jpg', 'https://www.youtube.com/watch?v=RlfooqeZcdY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (842, 'Annabelle Comes Home', 'Determined to keep Annabelle from wreaking more havoc, demonologists Ed and Lorraine Warren bring the possessed doll to the locked artifacts room in their home, placing her “safely” behind sacred glass and enlisting a priest’s holy blessing. But an unholy night of horror awaits as Annabelle awakens the evil spirits in the room, who all set their sights on a new target—the Warrens'' ten-year-old daughter, Judy, and her friends.', 'Gary Dauberman', 106, '2019-06-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qWsHMrbg9DsBY3bCMk9jyYCRVRs.jpg', 'https://www.youtube.com/watch?v=bCxm7cTpBAs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (843, 'Once Upon a Time in the Middle East', 'Seeking a fresh start, chef Xu Fu travels to the Middle East to support his family and repay his debts. Alongside restaurant manager Ma Junsheng, he transforms the struggling Dragon Restaurant into a thriving business. But when war engulfs the city, their hard-won success is shattered and the restaurant becomes a refuge for those caught in the conflict. As danger closes in, Xu Fu must risk everything to protect his newfound community and preserve a small beacon of hope amid the devastation.', 'Wen Muye', 141, '2026-08-08', 'T16', 'zh', 'https://image.tmdb.org/t/p/w500/wAuGgXjA7GV8NrKfmUKl2AP8vqG.jpg', 'https://www.youtube.com/watch?v=IEgL2ycJcao', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (844, 'After Ever Happy', 'As a shocking truth about a couple''s families emerges, the two lovers discover they are not so different from each other. Tessa is no longer the sweet, simple, good girl she was when she met Hardin — any more than he is the cruel, moody boy she fell so hard for.', 'Castille Landon', 95, '2022-08-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/moogpu8rNkEjTgFyLXwhPghft5w.jpg', 'https://www.youtube.com/watch?v=K7AL2OARpTo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (845, 'Immaculate', 'An American nun embarks on a new journey when she joins a remote convent in the Italian countryside. However, her warm welcome quickly turns into a living nightmare when she discovers her new home harbours a sinister secret and unspeakable horrors.', 'Michael Mohan', 89, '2024-03-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zyopv7D5j7cfswG0NYiA14qAdPC.jpg', 'https://www.youtube.com/watch?v=11gb7q1tosI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (846, 'Beau Is Afraid', 'Following the sudden death of his mother, a mild-mannered but anxiety-ridden man confronts his darkest fears as he embarks on an epic odyssey back home.', 'Ari Aster', 179, '2023-04-14', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/wgVkkjigF31r1nZV80uV0xNIoun.jpg', 'https://www.youtube.com/watch?v=PuiWDn976Ek', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (847, 'Love Lies Bleeding', 'Reclusive gym manager Lou falls hard for Jackie, an ambitious bodybuilder headed through town to Las Vegas in pursuit of her dream. But their love ignites violence, pulling them deep into the web of Lou’s criminal family.', 'Rose Glass', 104, '2024-03-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xImj8RLe39YK0lyVu9kXv7ApN8p.jpg', 'https://www.youtube.com/watch?v=AULR_GPteNQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (848, 'Never Let Go', 'As an evil takes over the world beyond their front doorstep, the only protection for a mother and her twin sons is their house and their family’s protective bond.', 'Alexandre Aja', 101, '2024-09-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3EpZ2ksjijmdr8BhISP03PYzNFW.jpg', 'https://www.youtube.com/watch?v=-H3yhfkJBnQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (849, 'Kubo and the Two Strings', 'Kubo mesmerizes the people in his village with his magical gift for spinning wild tales with origami. When he accidentally summons an evil spirit seeking vengeance, Kubo is forced to go on a quest to solve the mystery of his fallen samurai father and his mystical weaponry, as well as discover his own magical powers.', 'Travis Knight', 102, '2016-08-18', 'P', 'en', 'https://image.tmdb.org/t/p/w500/la6QA9tk4Foq8OBH2Dyh5dTcw6H.jpg', 'https://www.youtube.com/watch?v=Pz49Ml_rB34', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (850, 'Heart of Stone', 'An intelligence operative for a shadowy global peacekeeping agency races to stop a hacker from stealing its most valuable — and dangerous — weapon.', 'Tom Harper', 122, '2023-08-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vB8o2p4ETnrfiWEgVxHmHWP9yRl.jpg', 'https://www.youtube.com/watch?v=LOHrNvFH3F8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (851, '65', '65 million years ago, the only 2 survivors of a spaceship from Somaris that crash-landed on Earth, must fend off dinosaurs to reach the escape vessel in time before an imminent asteroid strike threatens to destroy the planet.', 'Bryan Woods, Scott Beck', 92, '2023-03-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/rzRb63TldOKdKydCvWJM8B6EkPM.jpg', 'https://www.youtube.com/watch?v=M6YfhX83Cj8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (852, 'Wonder Park', 'A young girl named June with a big imagination makes an incredible discovery -- the amusement park of her dreams has come to life. Filled with the world''s wildest rides operated by fun-loving animals, the excitement never ends. But when trouble hits, June and her misfit team of furry friends begin an unforgettable journey to save the park.', 'Dylan Brown', 86, '2019-03-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/8KomINZhIuJeB4oB7k7tkq8tmE.jpg', 'https://www.youtube.com/watch?v=5MRSBuQt51A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (853, 'Pizza Movie', 'A group of college students go downstairs to their dorm lobby to get a delivery pizza. There''s only one issue: They''re insanely high on a homemade drug, turning their simple journey down two sets of stairs into a mind-bendingly transformative quest.', 'Brian McElhaney, Nick Kocher', 98, '2026-03-13', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3rovbwvxJ5eQrWrQnF1VfJoPcMD.jpg', 'https://www.youtube.com/watch?v=fOzF87PFGnw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (854, 'Queen of Hearts', 'Anne, a brilliant and dedicated advocacy lawyer specialising in society’s most vulnerable, children and young adults, lives what appears to be the picture-perfect life with her doctor-husband, Peter, and their twin daughters. When her estranged teenage stepson, Gustav, moves in with them, Anne’s escalating desire leads her down a dangerous rabbit hole which, once exposed, unleashes a sequence of events destined to destroy her world.', 'May el-Toukhy', 127, '2019-03-27', 'P', 'da', 'https://image.tmdb.org/t/p/w500/dfFVDIgovEfQZn53VRKLV2JQnRJ.jpg', 'https://www.youtube.com/watch?v=kJmMCVN_6fw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (855, 'Teen Wolf: The Movie', 'The wolves are howling once again, as a terrifying ancient evil emerges in Beacon Hills. Scott McCall, no longer a teenager yet still an Alpha, must gather new allies and reunite trusted friends to fight back against this powerful and deadly enemy.', 'Russell Mulcahy', 140, '2023-01-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/wAkpPm3wcHRqZl8XjUI3Y2chYq2.jpg', 'https://www.youtube.com/watch?v=3NbHKvuvI5A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (856, 'Neighbors 2: Sorority Rising', 'A sorority moves in next door to the home of Mac and Kelly Radner who have a young child. The Radner''s enlist their former nemeses from the fraternity to help battle the raucous sisters.', 'Nicholas Stoller', 92, '2016-05-04', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/eyjcLLwxuRXACbglIbwWwaXK9DN.jpg', 'https://www.youtube.com/watch?v=EIe7nR0lvk4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (857, 'Monster', 'After an outburst at school involving her son, a concerned single mother demands answers, triggering a sequence of deepening suspicion and turmoil.', 'Hirokazu Kore-eda', 125, '2023-06-02', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/kvUJUyUGOhEoiWWNH04IXoExPE2.jpg', 'https://www.youtube.com/watch?v=Y8_KfdcIMBY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (858, 'You''re Cordially Invited', 'When two weddings are accidentally booked on the same day at the same venue, each bridal party is challenged with preserving their family''s special moment while making the most of the unanticipated tight quarters. In a hilarious battle of determination and grit, the father of the bride and sister of the other bride chaotically go head-to-head as they stop at nothing to uphold an unforgettable celebration for their loved ones.', 'Nicholas Stoller', 109, '2025-01-29', 'K', 'en', 'https://image.tmdb.org/t/p/w500/muXnwAdVdEEktto0NBNMyqK3uQH.jpg', 'https://www.youtube.com/watch?v=FTEqcrgsmzg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (859, 'The Witch: Part 2. The Other One', 'A girl wakes up in a huge secret laboratory, then accidentally meets another girl who is trying to protect her house from a gang. The mystery girl overthrows the gang with her unexpected powers, and laboratory staff set out to find her.', 'Park Hoon-jung', 137, '2022-06-15', 'T16', 'ko', 'https://image.tmdb.org/t/p/w500/9YTuscJXmr9Iua62amCgGSU8PDW.jpg', 'https://www.youtube.com/watch?v=EgOiCWTR_JU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (860, 'The Unholy', 'Alice is a young hearing-impaired girl who, after a supposed visitation from the Virgin Mary, is inexplicably able to hear, speak and heal the sick. As word spreads and people from near and far flock to witness her miracles, a disgraced journalist hoping to revive his career visits the small New England town to investigate. When terrifying events begin to happen all around, he starts to question if these phenomena are the works of the Virgin Mary or something much more sinister.', 'Evan Spiliotopoulos', 99, '2021-03-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bShgiEQoPnWdw4LBrYT5u18JF34.jpg', 'https://www.youtube.com/watch?v=NmQiJPLYzPI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (861, 'Extraction', 'A hardened gun-for-hire''s latest mission becomes a soul-searching race to survive when he''s sent into Bangladesh to rescue a drug lord''s kidnapped son.', 'Sam Hargrave', 116, '2020-04-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/nygOUcBKPHFTbxsYRFZVePqgPK6.jpg', 'https://www.youtube.com/watch?v=L6P3nI6VnlY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (862, 'The Unforgivable', 'A woman is released from prison after serving a sentence for a violent crime and re-enters a society that refuses to forgive her past.', 'Nora Fingscheidt', 112, '2021-11-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1b3dNFDuE7i05TJlXrIC571yR01.jpg', 'https://www.youtube.com/watch?v=JNUjx7LZoiU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (863, 'The Mule', 'Earl Stone, a man in his eighties, is broke, alone, and facing foreclosure of his business when he is offered a job that simply requires him to drive. Easy enough, but, unbeknownst to Earl, he''s just signed on as a drug courier for a Mexican cartel. He does so well that his cargo increases exponentially, and Earl hit the radar of hard-charging DEA agent Colin Bates.', 'Clint Eastwood', 116, '2018-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vkOfx5meJvFb4qmAJU7j6v8IIpZ.jpg', 'https://www.youtube.com/watch?v=0WhaleJ3Zik', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (864, 'Chaos Walking', 'Two unlikely companions embark on a perilous adventure through the badlands of an unexplored planet as they try to escape a dangerous and disorienting reality, where all inner thoughts are seen and heard by everyone.', 'Doug Liman', 109, '2021-02-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/xAYGdGBGptNkisXRpmhZSry6SPF.jpg', 'https://www.youtube.com/watch?v=nRf4ZgzHoVw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (865, 'Phantom Thread', 'In 1950s London, a renowned dressmaker''s meticulous lifestyle begins drastically changing as his relationship with his young muse intensifies.', 'Paul Thomas Anderson', 130, '2017-12-25', 'P', 'en', 'https://image.tmdb.org/t/p/w500/hgoWjp9Sh0MI97eAMZCnIoVfgvq.jpg', 'https://www.youtube.com/watch?v=xNsiQMeSvMk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (866, 'Good Boy', 'A loyal dog moves to a rural family home with his owner Todd, only to discover supernatural forces lurking in the shadows. As dark entities threaten his human companion, the brave pup must fight to protect the one he loves most.', 'Ben Leonberg', 73, '2025-10-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/daInKxjoRNLFWIus64fHAy91V0k.jpg', 'https://www.youtube.com/watch?v=q4-CRkd_74g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (867, 'Wrong Turn', 'Jen and a group of friends set out to hike the Appalachian Trail. Despite warnings to stick to the trail, the hikers stray off course—and cross into land inhabited by The Foundation, a hidden community of mountain dwellers who use deadly means to protect their way of life.', 'Mike P. Nelson', 110, '2021-01-26', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/4U1SBHmwHkNA0eHZ2n1CuiC1K1g.jpg', 'https://www.youtube.com/watch?v=rDdGpjjtq-o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (868, 'The Kissing Booth', 'When teenager Elle''s first kiss leads to a forbidden romance with the hottest boy in high school, she risks her relationship with her best friend.', 'Vince Marcello', 105, '2018-05-11', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/vcQNnnXgKLacoYF4LNWgkNiDXPd.jpg', 'https://www.youtube.com/watch?v=7bfS6seiLhk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (869, 'Rental Family', 'An American actor in Tokyo struggles to find purpose until he lands an unusual gig: working for a Japanese ''rental family'' agency, playing stand-in roles for strangers. As he immerses himself in his clients'' worlds, he begins to form genuine bonds that blur the lines between performance and reality.', 'Hikari', 110, '2025-11-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/A5lswNlytTUrnMWsuD0NFfhZlf3.jpg', 'https://www.youtube.com/watch?v=RP9QKdU0vvA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (870, 'Upgrade', 'A brutal mugging leaves Grey Trace paralyzed in the hospital and his beloved wife dead. A billionaire inventor soon offers Trace a cure — an artificial intelligence implant called STEM that will enhance his body. Now able to walk, Grey finds that he also has superhuman strength and agility — skills he uses to seek revenge against the thugs who destroyed his life.', 'Leigh Whannell', 100, '2018-05-31', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/woLGROUdPWdBnLVFKYdGD3kFkPY.jpg', 'https://www.youtube.com/watch?v=1hTLGlgZ4Z8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (871, 'Escape Room', 'Six strangers find themselves in circumstances beyond their control, and must use their wits to survive.', 'Adam Robitel', 99, '2019-01-03', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/8Ls1tZ6qjGzfGHjBB7ihOnf7f0b.jpg', 'https://www.youtube.com/watch?v=6dSKUoV0SNI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (872, 'Hit Man', 'A mild-mannered professor moonlighting as a fake hit man in police stings ignites a chain reaction of trouble when he falls for a potential client.', 'Richard Linklater', 116, '2024-05-16', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oil3EZwKFp3CWxZnfGfGglesvm9.jpg', 'https://www.youtube.com/watch?v=9a7C7Bxsm90', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (873, 'STRAW', 'What will be her last straw? A devastatingly bad day pushes a hardworking single mother to the breaking point — and into a shocking act of desperation.', 'Tyler Perry', 105, '2025-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/t3cmnXYtxJb9vVL1ThvT2CWSe1n.jpg', 'https://www.youtube.com/watch?v=k1vWhii4tkE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (874, 'American Assassin', 'Following the murder of his fiancée, Mitch Rapp trains under the instruction of Cold War veteran Stan Hurley. The pair then is enlisted to investigate a wave of apparently random attacks on military and civilian targets.', 'Michael Cuesta', 112, '2017-07-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/w6vjeHx3UEaBXIyc8VFqyZYKznD.jpg', 'https://www.youtube.com/watch?v=D9iWGcx4krg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (875, 'Ferrari', 'Set during the summer of 1957. Ex-racecar driver, Enzo Ferrari, is in crisis. Bankruptcy stalks the company he and his wife, Laura, built from nothing ten years earlier. Their tempestuous marriage struggles with the mourning for one son and the acknowledgement of another.', 'Michael Mann', 131, '2023-12-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/LyCOcGqOTyTmaXu2TK8LfGveIb.jpg', 'https://www.youtube.com/watch?v=8oOVNMjM1Jk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (876, 'The Call of the Wild', 'Buck is a big-hearted dog whose blissful domestic life is turned upside down when he is suddenly uprooted from his California home and transplanted to the exotic wilds of the Yukon during the Gold Rush of the 1890s. As the newest rookie on a mail delivery dog sled team—and later its leader—Buck experiences the adventure of a lifetime, ultimately finding his true place in the world and becoming his own master.', 'Chris Sanders', 100, '2020-02-19', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/33VdppGbeNxICrFUtW2WpGHvfYc.jpg', 'https://www.youtube.com/watch?v=5P8R2zAhEwg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (877, 'Atomic Blonde', 'An undercover MI6 agent is sent to Berlin during the Cold War to investigate the murder of a fellow agent and recover a missing list of double agents.', 'David Leitch', 115, '2017-07-26', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/kV9R5h0Yct1kR8Hf8sJ1nX0Vz4x.jpg', 'https://www.youtube.com/watch?v=IGDdv88uJsQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (878, 'Bones and All', 'Abandoned by her father, a young woman embarks on a thousand-mile odyssey through the backroads of America where she meets a disenfranchised drifter. But despite their best efforts, all roads lead back to their terrifying pasts and to a final stand that will determine whether their love can survive their otherness.', 'Luca Guadagnino', 131, '2022-11-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dBQuk2LkHjrDsSjueirPQg96GCc.jpg', 'https://www.youtube.com/watch?v=0Nu7Z9AxGNg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (879, 'Halloween Kills', 'Michael manages to free himself from Laurie Strode''s trap to resume his ritual bloodbath. As she fights for her life from injuries from their last encounter, she inspires her daughter Karen, her granddaughter Allyson, and all of Haddonfield to rise up against the unstoppable monster.', 'David Gordon Green', 105, '2021-10-14', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/ir9eyz1mtgsohjvo7UYtqUfFuES.jpg', 'https://www.youtube.com/watch?v=hL6R3HmQfPc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (880, 'Bad Moms', 'When three overworked and under-appreciated moms are pushed beyond their limits, they ditch their conventional responsibilities for a jolt of long overdue freedom, fun, and comedic self-indulgence.', 'Jon Lucas, Scott Moore', 100, '2016-07-28', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/u9q10ljhkLj0tNCjlVqe3DCjoU4.jpg', 'https://www.youtube.com/watch?v=2RZbwGItfd0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (881, 'I, Tonya', 'Competitive ice skater Tonya Harding rises amongst the ranks at the U.S. Figure Skating Championships, but her future in the sport is thrown into doubt when her ex-husband intervenes.', 'Craig Gillespie', 120, '2017-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/6gNXwSHxaksR1PjVZRqNapmkgj3.jpg', 'https://www.youtube.com/watch?v=d2iy5y0YjGM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (882, 'The Bikeriders', 'After a chance encounter, headstrong Kathy is drawn to Benny, member of Midwestern motorcycle club the Vandals. As the club transforms into a dangerous underworld of violence, Benny must choose between Kathy and his loyalty to the club.', 'Jeff Nichols', 116, '2024-06-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ApMuukdDAOR2rgaFDZIcjfigi64.jpg', 'https://www.youtube.com/watch?v=7W0ec8UMnfg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (883, 'Toxic', 'Dreaming of an escape from the bleakness of their hometown, two teens form a unique bond at a local modeling school, where the promise of a better life pushes girls to violate their bodies in increasingly extreme ways.', 'Saulė Bliuvaitė', 99, '2025-03-24', 'P', 'lt', 'https://image.tmdb.org/t/p/w500/knG84vSv8kRMeopgIcrTpsYYHSs.jpg', 'https://www.youtube.com/watch?v=ImMyk4qlN3o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (884, 'Sentimental Value', 'Sisters Nora and Agnes reunite with their estranged father, the charismatic Gustav, a once-renowned director who offers stage actress Nora a role in what he hopes will be his comeback film. When Nora turns it down, she soon discovers he has given her part to an eager young Hollywood star.', 'Joachim Trier', 133, '2025-08-20', 'T13', 'no', 'https://image.tmdb.org/t/p/w500/pz9NCWxxOk3o0W3v1Zkhawrwb4i.jpg', 'https://www.youtube.com/watch?v=CbHbW7De3W4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (885, 'Good Fortune', 'A well-meaning but rather inept angel named Gabriel meddles in the lives of a struggling gig worker and a wealthy capitalist.', 'Aziz Ansari', 97, '2025-10-14', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rywxUbd4zvHiRP7nOHeDzuQSLIZ.jpg', 'https://www.youtube.com/watch?v=SAMkXY2Ja80', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (886, 'The Instigators', 'Rory and Cobby are unlikely partners thrown together for a heist. But when it goes awry, they team up with an unusual accomplice — Rory''s therapist — to outrun police, backward bureaucrats, and a vengeful crime boss.', 'Doug Liman', 102, '2024-08-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dnYWsIFDmygCjNg65rY3uBymx81.jpg', 'https://www.youtube.com/watch?v=X5oqpxi3U7M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (887, 'Plane', 'After a heroic job of successfully landing his storm-damaged aircraft in a war zone, a fearless pilot finds himself between the agendas of multiple militias planning to take the plane and its passengers hostage.', 'Jean-François Richet', 107, '2023-01-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oJRsTQR47pyjSJCZYpOfbycpNBR.jpg', 'https://www.youtube.com/watch?v=7-6_Ulo7mdk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (888, 'Underworld: Blood Wars', 'Vampire death dealer Selene fends off brutal attacks from both the Lycan clan and the Vampire faction that betrayed her. With her only allies, David and his father Thomas, she must stop the eternal war between Lycans and Vampires, even if it means she has to make the ultimate sacrifice.', 'Anna Foerster', 91, '2016-11-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/v1ciDCWMG47gdT4kMyjyQbnLQQn.jpg', 'https://www.youtube.com/watch?v=AoRs8qZNFtc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (889, 'Dream Scenario', 'Hapless family man Paul Matthews finds his life turned upside down when millions of strangers suddenly start seeing him in their dreams. But when his nighttime appearances take a nightmarish turn, Paul is forced to navigate his newfound stardom.', 'Kristoffer Borgli', 102, '2023-11-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eMaAi8wTI5wON8pp33w3BDuGyZ8.jpg', 'https://www.youtube.com/watch?v=q3x9iUL-74w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (890, 'Mummies', 'Through a series of unfortunate events, three mummies end up in present-day London and embark on a wacky and hilarious journey in search of an old ring belonging to the Royal Family, stolen by ambitious archaeologist Lord Carnaby.', 'Juan Jesús García Galocha', 88, '2023-01-05', 'T13', 'es', 'https://image.tmdb.org/t/p/w500/18nabcSr5luPtdycpTZItffddbP.jpg', 'https://www.youtube.com/watch?v=WRB8YIc4U68', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (891, 'Skyscraper', 'Framed and on the run, a former FBI agent must save his family from a blazing fire in the world''s tallest building.', 'Rawson Marshall Thurber', 102, '2018-07-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/52ml62vClzrlqvXZq2FEW6UF6c1.jpg', 'https://www.youtube.com/watch?v=_pIEzZVqwFs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (892, 'Novocaine', 'When the girl of his dreams is kidnapped, everyman Nate turns his inability to feel pain into an unexpected strength in his fight to get her back.', 'Dan Berk, Robert Olsen', 110, '2025-03-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/xmMHGz9dVRaMY6rRAlEX4W0Wdhm.jpg', 'https://www.youtube.com/watch?v=-PyOIlJEdqA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (893, 'Escape Room: Tournament of Champions', 'Six people unwittingly find themselves locked in another series of escape rooms, slowly uncovering what they have in common to survive... and discovering they''ve all played the games before.', 'Adam Robitel', 88, '2021-07-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/jGYJyPzVgrVV2bgClI9uvEZgVLE.jpg', 'https://www.youtube.com/watch?v=KlfUbZJVInA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (894, 'Nightborn', 'In Finnish forest, Saga and her husband Jon embark on a new chapter as parents. But Saga''s joy is overshadowed by a chilling suspicion about their newborn, unbeknownst to Jon, causing a rift as she alone grapples with the disturbing truth.', 'Hanna Bergholm', 92, '2026-07-01', 'T18', 'fi', 'https://image.tmdb.org/t/p/w500/e9ALgOANOJbcFpw84MbafK3xvD2.jpg', 'https://www.youtube.com/watch?v=dWePsu_Kd9c', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (895, 'Terrifier', 'A maniacal clown named Art terrorizes three young women on Halloween night and everyone else who stands in his way.', 'Damien Leone', 84, '2018-01-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fjXqhGmaeQpB73WerhrYU6HlyV5.jpg', 'https://www.youtube.com/watch?v=1EyzlnWsZCk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (896, 'Old', 'A group of families on a tropical holiday discover that the secluded beach where they are staying is somehow causing them to age rapidly – reducing their entire lives into a single day.', 'M. Night Shyamalan', 108, '2021-07-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vclShucpUmPhdAOmKgf3B3Z4POD.jpg', 'https://www.youtube.com/watch?v=A4U2pMRV9_k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (897, 'Hocus Pocus 2', '29 years since the Black Flame Candle was last lit, the 17th-century Sanderson sisters are resurrected, and they are looking for revenge. Now it''s up to three high school students to stop the ravenous witches from wreaking a new kind of havoc on Salem before dawn on All Hallow''s Eve.', 'Anne Fletcher', 104, '2022-09-27', 'P', 'en', 'https://image.tmdb.org/t/p/w500/7ze7YNmUaX81ufctGqt0AgHxRtL.jpg', 'https://www.youtube.com/watch?v=ecJRvz9nk-U', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (898, 'The Passenger', 'Hassan, a Somali-American airport shuttle driver in Minneapolis, is struggling to make ends meet. When Lloyd, a stranded twenty-something at the airport, offers to pay Hassan to take him overland to Chicago, it seems worth the risk. But as the realization grows that his passenger is not what he seems, Hassan finds himself trapped in a terrifying ride that he can’t escape, knowing that saving himself might put countless others in danger.', 'Vadim Perelman', 93, '2026-06-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/i9XqCdF0jrgqveYUaLjOSiRepIq.jpg', 'https://www.youtube.com/watch?v=jMOow9j8oEw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (899, 'Diary of a Wimpy Kid Christmas: Cabin Fever', 'A hilarious and heartfelt holiday tale centered around everyone''s favorite disaster-prone middle school student, Greg Heffley, which finds him desperately fighting to stay off Santa''s naughty list as the family prepares for a major winter snowstorm.', 'Luke Cormican', 64, '2023-12-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/CgWUleumTXrFL6AsQKjpcuwWyN.jpg', 'https://www.youtube.com/watch?v=Ny-Z8-iuZxE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (900, 'The Shallows', 'While surfing on a secluded beach, Nancy finds herself in the feeding grounds of a great white shark. Though stranded only 200 yards from shore, survival proves to be the ultimate test of wills, requiring all of her ingenuity, resourcefulness, and fortitude.', 'Jaume Collet-Serra', 86, '2016-06-24', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/bnBV7hZmLuA0Si5Aop481sPF2RY.jpg', 'https://www.youtube.com/watch?v=EgdxIlSuB70', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
