  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (901, 'The Girl on the Train', 'Rachel Watson, devastated by her recent divorce, spends her daily commute fantasizing about the seemingly perfect couple who live in a house that her train passes every day, until one morning she sees something shocking happen there and becomes entangled in the mystery that unfolds.', 'Tate Taylor', 112, '2016-10-05', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/AhTO2QWG0tug7yDoh0XoaMhPt3J.jpg', 'https://www.youtube.com/watch?v=-CKPj4O5_9s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (902, '12 Strong', 'A team of special forces head into Afghanistan in the aftermath of the September 11th attacks in an attempt to dismantle the Taliban.', 'Nicolai Fuglsig', 130, '2018-01-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/37Qwani2g0jVPU7N4OkkTZ7aERz.jpg', 'https://www.youtube.com/watch?v=-Denciie5oA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (903, 'The Strangers: Chapter 1', 'After their car breaks down in an eerie small town, a young couple are forced to spend the night in a remote cabin. Panic ensues as they are terrorized by three masked strangers who strike with no mercy and seemingly no motives.', 'Renny Harlin', 91, '2024-05-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/oYsCNpW4k7Pd7ac3uQfBhr2ihtW.jpg', 'https://www.youtube.com/watch?v=3pZUQmZdOi4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (904, 'Strange World', 'A journey deep into an uncharted and treacherous land, where fantastical creatures await the legendary Clades—a family of explorers whose differences threaten to topple their latest, and by far most crucial, mission.', 'Don Hall', 102, '2022-11-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/a9x70QUXs6uEwtin1SGNKoFXoia.jpg', 'https://www.youtube.com/watch?v=5lR0pkUjzb4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (905, 'Zombieland: Double Tap', 'Columbus, Tallahassee, Wichita, and Little Rock move to the American heartland as they face off against evolved zombies, fellow survivors, and the growing pains of the snarky makeshift family.', 'Ruben Fleischer', 99, '2019-10-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/dtRbVsUb5O12WWO54SRpiMtHKC0.jpg', 'https://www.youtube.com/watch?v=ZlW9yhUKlkQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (906, 'Underwater', 'After an earthquake destroys their underwater station, six researchers must navigate two miles along the dangerous, unknown depths of the ocean floor to make it to safety in a race against time.', 'William Eubank', 95, '2020-01-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/gzlbb3yeVISpQ3REd3Ga1scWGTU.jpg', 'https://www.youtube.com/watch?v=jCFWEzIVILc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (907, 'Selena Gomez: My Mind & Me', 'After years in the limelight, Selena Gomez achieves unimaginable stardom. But just as she reaches a new peak, an unexpected turn pulls her into darkness. This uniquely raw and intimate documentary spans her six-year journey into a new light.', 'Alek Keshishian', 95, '2022-11-04', 'P', 'en', 'https://image.tmdb.org/t/p/w500/oMpsswJv8x4vnOnIKqs4xJs2Kn3.jpg', 'https://www.youtube.com/watch?v=of32sI9jw5Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (908, 'Patriots Day', 'In the aftermath of an unspeakable act of terror, Police Sergeant Tommy Saunders joins courageous survivors, first responders and investigators in a race against the clock to hunt down the Boston Marathon bombers before they strike again.', 'Peter Berg', 133, '2016-12-12', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/mIDxsJTrOC7NhgOo3GziiHyKfsQ.jpg', 'https://www.youtube.com/watch?v=_c9IpI_pNGI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (909, 'Hellfire', 'A drifter with a mysterious past arrives in a small town and finds the residents in the grip of a ruthless crime boss and realizes he has to help them.', 'Isaac Florentine', 94, '2026-05-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/tQti9QTf13MfzNpXguijgNh7ojE.jpg', 'https://www.youtube.com/watch?v=S_uvyNNCiMc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (910, 'Marriage Story', 'A stage director and an actress struggle through a grueling, coast-to-coast divorce that pushes them to their personal extremes.', 'Noah Baumbach', 137, '2019-09-28', 'P', 'en', 'https://image.tmdb.org/t/p/w500/2JRyCKaRKyJAVpsIHeLvPw5nHmw.jpg', 'https://www.youtube.com/watch?v=BHi-a1n8t7M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (911, 'Den of Thieves 2: Pantera', 'Big Nick is back on the hunt in Europe and closing in on Donnie, who is embroiled in the treacherous and unpredictable world of diamond thieves and the infamous Panther mafia, as they plot a massive heist of the world''s largest diamond exchange.', 'Christian Gudegast', 144, '2025-01-08', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/rxcyxxarD17xMliStDEhM6y2AYQ.jpg', 'https://www.youtube.com/watch?v=1kmjAnvFw3I', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (912, 'My Spy The Eternal City', 'JJ, a veteran CIA agent, reunites with his protégé Sophie, in order to prevent a catastrophic nuclear plot targeting the Vatican.', 'Peter Segal', 113, '2024-07-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fRBfkzSrcyrnUfVgpEtTurEEiac.jpg', 'https://www.youtube.com/watch?v=6xJ1F7yFsnU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (913, 'Havoc', 'When a drug heist swerves lethally out of control, a jaded cop fights his way through a corrupt city''s criminal underworld to save a politician''s son.', 'Gareth Evans', 107, '2025-04-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/r46leE6PSzLR3pnVzaxx5Q30yUF.jpg', 'https://www.youtube.com/watch?v=6txjTWLoSc8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (914, 'Goosebumps 2: Haunted Halloween', 'Be careful what you wish for. With their after school junk business, best friends Sonny and Sam hope to find treasure in other people’s trash. But when cleaning out the old Stine house, they open a locked book that frees a supernatural nightmare – Slappy! Now, with the help of Sonny’s sister Sarah, they’re in a race against time to get the sinister dummy and all the creatures he’s brought to life back into the pages before he unleashes total pandemonium!', 'Ari Sandel', 90, '2018-10-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/t2wy38iiMpB8WsgJi3lYeDnGh2H.jpg', 'https://www.youtube.com/watch?v=3mT-BdZQ4Uc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (915, 'Jackpot!', 'In the near future, a ''Grand Lottery'' has been established - the catch: kill the winner before sundown to legally claim their multi-billion dollar jackpot. When Katie Kim mistakenly finds herself with the winning ticket, she reluctantly joins forces with amateur lottery protection agent Noel Cassidy who must get her to sundown in exchange for a piece of her prize.', 'Paul Feig', 107, '2024-08-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/7vv0NTaQGOO7M5ZMerp1vMFJsby.jpg', 'https://www.youtube.com/watch?v=IW7pIYtpp50', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (916, 'Fly Me to the Moon', 'Sparks fly in all directions as marketing maven Kelly Jones, brought in to fix NASA''s public image, wreaks havoc on Apollo 11 launch director Cole Davis'' already difficult task of putting a man on the moon. When the White House deems the mission too important to fail, Jones is directed to stage a fake moon landing as backup, and the countdown truly begins.', 'Greg Berlanti', 132, '2024-07-10', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gjk8YdXpItoC1in53FCrZMFIuBx.jpg', 'https://www.youtube.com/watch?v=1ZO5k948MkY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (917, 'The Platform 2', 'After a mysterious leader imposes his law in a brutal system of vertical cells, a new arrival battles against a dubious food distribution method.', 'Galder Gaztelu-Urrutia', 101, '2024-09-27', 'T16', 'es', 'https://image.tmdb.org/t/p/w500/tvIpBg12IIA5Dr9Sjn38ygS1vQp.jpg', 'https://www.youtube.com/watch?v=UKFMYWNatQM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (918, 'Crazy Rich Asians', 'An American-born Chinese economics professor accompanies her boyfriend to Singapore for his best friend''s wedding, only to get thrust into the lives of Asia''s rich and famous.', 'Jon M. Chu', 121, '2018-08-15', 'K', 'en', 'https://image.tmdb.org/t/p/w500/1XxL4LJ5WHdrcYcihEZUCgNCpAW.jpg', 'https://www.youtube.com/watch?v=ZQ-YX-5bAs0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (919, 'Licorice Pizza', 'The story of Gary Valentine and Alana Kane growing up, running around and going through the treacherous navigation of first love in the San Fernando Valley, 1973.', 'Paul Thomas Anderson', 133, '2021-11-26', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ivXtvzfliGvoJ1DhSHIGyYBToWe.jpg', 'https://www.youtube.com/watch?v=ofnXPwUPENo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (920, 'The Magic Faraway Tree', 'A modern family relocates to the countryside where the children discover a magical tree with eccentric residents. They''re transported to fantastical lands, rekindling their family bond through adventures.', 'Ben Gregor', 110, '2026-03-26', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/udXvLxC5gAqN8SinemyFBEcHpTf.jpg', 'https://www.youtube.com/watch?v=PAUEwUhAjzg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (921, 'The Strangers: Chapter 2', 'After learning that one of their victims, Maya, is still alive, The Strangers return to finish the job. With nowhere to run and no one to trust, Maya soon finds herself in a brutal fight for survival against psychopaths more than willing to kill anyone who stands in their way.', 'Renny Harlin', 98, '2025-09-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/pqADzs5SJvI2jC0DThPVMuNJcWS.jpg', 'https://www.youtube.com/watch?v=Y3dXWFcoVqg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (922, 'Monster Summer', 'When a mysterious force begins to disrupt their big summer fun, Noah and his friends team up with a retired police detective to embark on a monstrous adventure to save their island.', 'David Henrie', 98, '2024-10-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/zD2UZkh0DwbDEMuOKIR7jgwgulZ.jpg', 'https://www.youtube.com/watch?v=1FdRdExhrRQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (923, 'The Crow', 'Soulmates Eric and Shelly are brutally murdered when the demons of her dark past catch up with them. Given the chance to save his true love by sacrificing himself, Eric sets out to seek merciless revenge on their killers, traversing the worlds of the living and the dead to put the wrong things right.', 'Rupert Sanders', 111, '2024-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/g8TbOXrNMuqq7AaKqdvqS2oG4ob.jpg', 'https://www.youtube.com/watch?v=4CLE3pWAAr8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (924, 'Candy Cane Lane', 'Determined to win the neighborhood''s annual Christmas decorating contest, family man Chris makes a pact with an elf to help him out-do the competition. However, the elf casts a spell bringing the twelve days of Christmas to life, unleashing chaos on the small unsuspecting town.', 'Reginald Hudlin', 117, '2023-11-29', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/of6Ds591FJTKoBHYjDFzH6jlTyK.jpg', 'https://www.youtube.com/watch?v=Y9d2G3l3UO4', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (925, 'Smallfoot', 'A bright young yeti finds something he thought didn''t exist—a human. News of this “smallfoot” throws the simple yeti community into an uproar over what else might be out there in the big world beyond their snowy village.', 'Karey Kirkpatrick', 96, '2018-09-20', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zfaiO7QgpcvR8XDOMokWLRfKeTE.jpg', 'https://www.youtube.com/watch?v=34cHO5_LX9g', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (926, 'Clown in a Cornfield', 'Quinn and her father have just moved to the quiet town of Kettle Springs hoping for a fresh start. Instead, she discovers a fractured community that has fallen on hard times after the treasured Baypen Corn Syrup Factory burned down. As the locals bicker amongst themselves and tensions boil over, a sinister, grinning figure emerges from the cornfields to cleanse the town of its burdens, one bloody victim at a time.', 'Eli Craig', 96, '2025-05-02', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6ep6gw90TJ8bYvJC6hEDo8SxjoJ.jpg', 'https://www.youtube.com/watch?v=8tBSOKyyZT8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (927, 'Young Woman and the Sea', 'This is the extraordinary true story of Trudy Ederle, the first woman to successfully swim the English Channel. Through the steadfast support of her older sister and supportive trainers, she overcame adversity and the animosity of a patriarchal society to rise through the ranks of the Olympic swimming team and complete the 21-mile trek from France to England.', 'Joachim Rønning', 129, '2024-05-31', 'P', 'en', 'https://image.tmdb.org/t/p/w500/bZlecCuBVvKuarNGvchBwaOsQ3c.jpg', 'https://www.youtube.com/watch?v=7tNvrYzPUrk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (928, 'The Ritual', 'Two priests, one in crisis with his faith and the other confronting a turbulent past, must overcome their differences to perform a risky exorcism.', 'David Midell', 98, '2025-04-18', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/uubL8yvtEBjz3V7DFQHjCuSQO8w.jpg', 'https://www.youtube.com/watch?v=Y8zUTpO3JAo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (929, 'Oh. What. Fun.', 'Claire Clauster is the glue that holds her chaotic, lovable family together at the holidays. But this year, after planning a special outing for them, they make a crucial mistake and leave her home alone. Fed up and feeling under appreciated, she sets off on an impromptu adventure of her own. As her family scrambles to find her, Claire discovers the unexpected magic of a Christmas gone off-script.', 'Michael Showalter', 108, '2025-12-03', 'P', 'en', 'https://image.tmdb.org/t/p/w500/qynCyBKCJUUcj4wo4PE2aQVvote.jpg', 'https://www.youtube.com/watch?v=FRfj0OHlcvo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (930, 'The Post', 'A cover-up that spanned four U.S. Presidents pushed the country''s first female newspaper publisher and a hard-driving editor to join an unprecedented battle between journalist and government. Inspired by true events.', 'Steven Spielberg', 116, '2017-12-22', 'K', 'en', 'https://image.tmdb.org/t/p/w500/h4XG3g6uMMPIBPjAoQhC2QIMdkl.jpg', 'https://www.youtube.com/watch?v=nrXlY6gzTTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (931, 'Honey Don''t!', 'Honey O''Donahue, a small-town private investigator, delves into a series of strange deaths tied to a mysterious church.', 'Ethan Coen', 89, '2025-08-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/fJm3kmd9NLZWypMas7g34oNFgbk.jpg', 'https://www.youtube.com/watch?v=Jzr6pHIZAI0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (932, 'Strays', 'When Reggie is abandoned on the mean city streets by his lowlife owner, Doug, Reggie is certain that his beloved owner would never leave him on purpose. But once Reggie falls in with Bug, a fast-talking, foul-mouthed stray who loves his freedom and believes that owners are for suckers, Reggie finally realizes he was in a toxic relationship and begins to see Doug for the heartless sleazeball that he is.', 'Josh Greenbaum', 93, '2023-08-17', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/n1hqbSCtyBAxaXEl1Dj3ipXJAJG.jpg', 'https://www.youtube.com/watch?v=26Xq6_g2r6Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (933, 'The Ballad of Buster Scruggs', 'Vignettes weaving together the stories of six individuals in the old West at the end of the Civil War. Following the tales of a sharp-shooting songster, a wannabe bank robber, two weary traveling performers, a lone gold prospector, a woman traveling the West to an uncertain future, and a motley crew of strangers undertaking a carriage ride.', 'Ethan Coen, Joel Coen', 132, '2018-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/voxl654m7p36y8FLu8oQD7dfwwK.jpg', 'https://www.youtube.com/watch?v=_2PyxzSH1HM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (934, 'The Ice Road', 'After a remote diamond mine collapses in far northern Canada, an ice road driver must lead an impossible rescue mission over a frozen ocean to save the trapped miners.', 'Jonathan Hensleigh', 108, '2021-06-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/gl1dlX9sKYpiKujq80Yxve7l4yg.jpg', 'https://www.youtube.com/watch?v=-zjikObAJHk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (935, 'My Hero Academia: You''re Next', 'In a society devastated by the effects of an all-out war between heroes and villains, a mysterious giant fortress suddenly appears, engulfing towns and people one after another. Then, a man reminiscent of All Might, the ''symbol of peace'', stands in front of Izuku and his friends...', 'Tensai Okamura', 110, '2024-08-02', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/tTrI6PwqzxkgO3dvQ7BEKXM7SYR.jpg', 'https://www.youtube.com/watch?v=22hBq1cvemE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (936, 'Stolen Girl', 'In 1993, Maureen’s six-year-old daughter Amina is snuck out of the country by her ex-husband, Karim. After years of unsuccessful attempts to find her, Maureen intersects with a professional retriever of internationally abducted children who promises to help her find Amina in exchange for her collaboration.', 'James Kent', 110, '2025-09-04', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/njU663VbT88zZjsJYizfWcam6sS.jpg', 'https://www.youtube.com/watch?v=V4bQuYwFtOQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (937, 'A Monster Calls', '12-year-old Conor encounters an ancient tree monster who proceeds to help him cope with his mother''s terminal illness and being bullied in school.', 'J. A. Bayona', 108, '2016-10-07', 'P', 'en', 'https://image.tmdb.org/t/p/w500/vNzWJwVqjszWwXrA7ZfsrJmhgV9.jpg', 'https://www.youtube.com/watch?v=8q-7trUd8Vw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (938, 'Why Him?', 'A dad forms a bitter rivalry with his daughter''s young rich boyfriend.', 'John Hamburg', 111, '2016-12-22', 'P', 'en', 'https://image.tmdb.org/t/p/w500/eezFoKz7bXgdbjeieeCYJFXPKSu.jpg', 'https://www.youtube.com/watch?v=CO6qLC4cL8E', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (939, 'Wolfs', 'Hired to cover up a high-profile crime, a fixer soon finds his night spiralling out of control when he''s forced to work with an unexpected counterpart.', 'Jon Watts', 108, '2024-09-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/vOX1Zng472PC2KnS0B9nRfM8aaZ.jpg', 'https://www.youtube.com/watch?v=5RSUcuGIiI0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (940, 'Honest Thief', 'A bank robber tries to turn himself in because he''s falling in love and wants to live an honest life...but when he realizes the Feds are more corrupt than him, he must fight back to clear his name.', 'Mark Williams', 99, '2020-09-03', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/zeD4PabP6099gpE0STWJrJrCBCs.jpg', 'https://www.youtube.com/watch?v=_TLtcw7ixRc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (941, 'The Amazing Maurice', 'Maurice is a streetwise ginger cat who comes up with a money-making scam by befriending a group of self-taught talking rats. When Maurice and the rodents meet a bookworm called Malicia, their little con soon goes down the drain.', 'Toby Genkel', 93, '2022-12-16', 'P', 'en', 'https://image.tmdb.org/t/p/w500/ydhZeUjbzVEFclUpMhLfDZSavUY.jpg', 'https://www.youtube.com/watch?v=fotvV-Ty9rU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (942, 'The Protégé', 'Rescued as a child by the legendary assassin Moody and trained in the family business, Anna is the world’s most skilled contract killer. When Moody, the man who was like a father to her and taught her everything she needs to know about trust and survival, is brutally killed, Anna vows revenge. As she becomes entangled with an enigmatic killer whose attraction to her goes way beyond cat and mouse, their confrontation turns deadly and the loose ends of a life spent killing will weave themselves ever tighter.', 'Martin Campbell', 109, '2021-08-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/iQUj7MptHUlcXpaMLrqRNZRxGA9.jpg', 'https://www.youtube.com/watch?v=fSqa0a3mGk8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (943, 'We Bury the Dead', 'After a catastrophic military disaster reanimates the dead, Ava searches for her missing husband amidst an increasingly hostile world.', 'Zak Hilditch', 95, '2026-01-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/xZqo0yPARmyF8TACVNyaOACkYWG.jpg', 'https://www.youtube.com/watch?v=YmPyNvrzF0A', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (944, 'A Beautiful Day in the Neighborhood', 'An award-winning cynical journalist, Lloyd Vogel, begrudgingly accepts an assignment to write an Esquire profile piece on the beloved television icon Fred Rogers. After his encounter with Rogers, Vogel''s perspective on life is transformed.', 'Marielle Heller', 109, '2019-09-07', 'K', 'en', 'https://image.tmdb.org/t/p/w500/pgxn1siPnWbSOKUeovfC86OwhWU.jpg', 'https://www.youtube.com/watch?v=-VLEPhfEN2M', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (945, 'Rebel Moon - Part Two: The Scargiver', 'The rebels gear up for battle against the ruthless forces of the Motherworld as unbreakable bonds are forged, heroes emerge — and legends are made.', 'Zack Snyder', 121, '2024-04-19', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/95gnJZIk2rEkMO0Ch46x5CVjnms.jpg', 'https://www.youtube.com/watch?v=UEJuNHOd8Dw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (946, 'All of Us Strangers', 'One night in his near-empty tower block in contemporary London, Adam has a chance encounter with a mysterious neighbor, which punctures the rhythm of his everyday life.', 'Andrew Haigh', 105, '2023-12-22', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/aviJMFZSnnCAsCVyJGaPNx4Ef3i.jpg', 'https://www.youtube.com/watch?v=1SMz_C9lI1o', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (947, 'Silence', 'In the 17th century, two Portuguese Jesuit priests travel to Japan in an attempt to locate their mentor, who is rumored to have committed apostasy, and to propagate Catholicism.', 'Martin Scorsese', 161, '2016-12-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/x5T0cQDYws0xRBVG4Q3wpcrcmax.jpg', 'https://www.youtube.com/watch?v=IqrgxZLd_gE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (948, 'Wolf Man', 'With his marriage fraying, Blake persuades his wife Charlotte to take a break from the city and visit his remote childhood home in rural Oregon. As they arrive at the farmhouse in the dead of night, they''re attacked by an unseen animal and barricade themselves inside the home as the creature prowls the perimeter. But as the night stretches on, Blake begins to behave strangely, transforming into something unrecognizable.', 'Leigh Whannell', 103, '2025-01-15', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/wpSDzTBfF0Eeo5lzu2w9FTujGqd.jpg', 'https://www.youtube.com/watch?v=kAw4PH2IQgo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (949, 'The Rivals of Amziah King', 'Deep within the backwoods of rural Oklahoma, charismatic and musically gifted Amziah King herds a bluegrass-playing band of misfits while overseeing the premier honey-making operation in town. When Amziah’s estranged foster daughter unexpectedly returns, Amziah leaps at the possibility to renew connection and create a family business. But the honey game is ruthless, and Amziah’s rivals threaten to destroy everything he has built.', 'Andrew Patterson', 131, '2026-08-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/3iVDCDS1VwHIm95PjWEPwsfdhaf.jpg', 'https://www.youtube.com/watch?v=GwSvAyaMGMo', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (950, 'The Apprentice', 'A young Donald Trump, eager to make his name as a hungry scion of a wealthy family in 1970s New York, comes under the spell of Roy Cohn, the cutthroat attorney who would help create the Donald Trump we know today. Cohn sees in Trump the perfect protégé—someone with raw ambition, a hunger for success, and a willingness to do whatever it takes to win.', 'Ali Abbasi', 122, '2024-10-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/549Hdul2BgPnZMhqFxp6npp2opr.jpg', 'https://www.youtube.com/watch?v=0tXEN0WNJUg', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;
INSERT INTO movies (id, title, description, director, duration_minutes, release_date, age_rating, original_language, poster_url, trailer_url, status, created_at, updated_at) VALUES
  (951, 'Rumble', 'In a world where monster wrestling is a global sport and monsters are superstar athletes, teenage Winnie seeks to follow in her father’s footsteps by coaching a loveable underdog monster into a champion.', 'Hamish Grieve', 95, '2021-02-12', 'P', 'en', 'https://image.tmdb.org/t/p/w500/3eZRgjfFWTpejRvRKyKe1EKgt9s.jpg', 'https://www.youtube.com/watch?v=hrkGNaYOv5k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (952, 'Grand Jete', 'Dance teacher and mother Nadja left her son Mario with her own mother when he was little. Now she has reappeared on his doorstep, seeking a closeness that knows fewer and fewer boundaries. An uncompromising film about family relationships.', 'Isabelle Stever', 105, '2022-09-20', 'T13', 'de', 'https://image.tmdb.org/t/p/w500/awpPWrE5kqIURHotysiR2yBg9Ty.jpg', 'https://www.youtube.com/watch?v=xz7SwtnM0KY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (953, 'Juror #2', 'While serving as a juror in a high profile murder trial, family man Justin Kemp finds himself struggling with a serious moral dilemma…one he could use to sway the jury verdict and potentially convict—or free—the accused killer.', 'Clint Eastwood', 114, '2024-10-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ugQkpGajKFQ8eyOEhGheR0HfWQ.jpg', 'https://www.youtube.com/watch?v=EhkkBFhW-MM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (954, 'Mechanic: Resurrection', 'Arthur Bishop thought he had put his murderous past behind him when his most formidable foe kidnaps the love of his life. Now he is forced to travel the globe to complete three impossible assassinations, and do what he does best, make them look like accidents.', 'Dennis Gansel', 99, '2016-08-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bG3Q6EFcngpPn7uPuQTzTuq9DgV.jpg', 'https://www.youtube.com/watch?v=QF903RaKLvs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (955, 'Inferno', 'After waking up in a hospital with amnesia, professor Robert Langdon and a doctor must race against time to foil a deadly global plot.', 'Ron Howard', 122, '2016-10-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5T6iVetK5AB1kgwAEKbDM2hTZJU.jpg', 'https://www.youtube.com/watch?v=RH2BD49sEZI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (956, 'Grimsby', 'Wrongfully accused and on the run, a top MI6 assassin joins forces with his long-lost, football hooligan brother to save the world from a sinister plot.', 'Louis Leterrier', 83, '2016-02-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/2jQGFmShpdflApc5oidJZ97m1d1.jpg', 'https://www.youtube.com/watch?v=_YtclB_02wA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (957, 'The Empty Man', 'On the trail of a missing girl, an ex-cop comes across a secretive group attempting to summon a terrifying supernatural entity.', 'David Prior', 137, '2020-10-22', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/8apzu9JFTUMtOpYkHk6LNPOs3pY.jpg', 'https://www.youtube.com/watch?v=aistYRvIml0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (958, 'I Feel Pretty', 'A head injury causes a woman to develop an extraordinary amount of confidence and believe she''s drop dead gorgeous.', 'Abby Kohn, Marc Silverstein', 110, '2018-04-19', 'P', 'en', 'https://image.tmdb.org/t/p/w500/iuPs45XIxfARKPLEkCGXWUrBrTR.jpg', 'https://www.youtube.com/watch?v=cVx9EFK3DWE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (959, 'Palm Springs', 'When carefree Nyles and reluctant maid of honor Sarah have a chance encounter at a Palm Springs wedding, things get complicated when they find themselves unable to escape the venue, themselves, or each other.', 'Max Barbakow', 90, '2020-07-10', 'P', 'en', 'https://image.tmdb.org/t/p/w500/gnAfqiV7yO3Jq9IntTmwkcaICqc.jpg', 'https://www.youtube.com/watch?v=CpBLtXduh_k', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (960, 'Girls Like Girls', 'After her mother''s passing, 17-year-old Coley navigates new feelings of intimacy with Sonya in rural Oregon, where both girls must overcome their mutual uncertainties and self-doubt to embrace their connection.', 'Hayley Kiyoko', 95, '2026-06-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/gbP30EOIwUW0HZY9BwQMTRrk8uX.jpg', 'https://www.youtube.com/watch?v=ZC1kEknG2ro', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (961, 'Knock at the Cabin', 'While vacationing at a remote cabin, a young girl and her two fathers are taken hostage by four armed strangers who demand that the family make an unthinkable choice to avert the apocalypse. With limited access to the outside world, the family must decide what they believe before all is lost.', 'M. Night Shyamalan', 100, '2023-02-01', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/dm06L9pxDOL9jNSK4Cb6y139rrG.jpg', 'https://www.youtube.com/watch?v=0wiBHEACNHs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (962, 'Dog Man', 'When a faithful police dog and his human police officer owner are injured together on the job, a harebrained but life-saving surgery fuses the two of them together and Dog Man is born. Dog Man is sworn to protect and serve—and fetch, sit and roll over. As Dog Man embraces his new identity and strives to impress his Chief, he must stop the pretty evil plots of feline supervillain Petey the Cat.', 'Peter Hastings', 89, '2025-01-24', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/89wNiexZdvLQ41OQWIsQy4O6jAQ.jpg', 'https://www.youtube.com/watch?v=QaJbAennB_Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (963, 'The Bricklayer', 'Someone is blackmailing the CIA by assassinating foreign journalists and making it look like the agency is responsible. As the world begins to unite against the U.S., the CIA must lure its most brilliant – and rebellious – operative out of retirement, forcing him to confront his checkered past while unraveling an international conspiracy.', 'Renny Harlin', 110, '2023-12-14', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/36pYugctLa70NmwMEgXTR1G31Kq.jpg', 'https://www.youtube.com/watch?v=G6YfPaucph8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (964, 'Mowgli: Legend of the Jungle', 'A human child raised by wolves, must face off against a menacing tiger named Shere Khan, as well as his own origins.', 'Andy Serkis', 105, '2018-11-25', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/clRnzMsFoMIdC7I5JsG6dnnHH8l.jpg', 'https://www.youtube.com/watch?v=OVBjPpUlQrE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (965, 'El Camino: A Breaking Bad Movie', 'In the wake of his dramatic escape from captivity, Jesse Pinkman must come to terms with his past in order to forge some kind of future.', 'Vince Gilligan', 123, '2019-10-11', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ePXuKdXZuJx8hHMNr2yM4jY2L7Z.jpg', 'https://www.youtube.com/watch?v=1JLUn2DFW4w', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (966, 'Money Monster', 'Financial TV host Lee Gates and his producer Patty are put in an extreme situation when an irate investor takes over their studio.', 'Jodie Foster', 99, '2016-05-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/DlgdAkAKirD01R1mBejhFjS6nQ.jpg', 'https://www.youtube.com/watch?v=qr_nGAbFkmk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (967, 'The Autopsy of Jane Doe', 'Father and son coroners receive a mysterious unidentified corpse with no apparent cause of death. As they attempt to examine the "Jane Doe," they discover increasingly bizarre clues that hold the key to her terrifying secrets.', 'André Øvredal', 86, '2016-12-21', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/6K0wjP8kPCiPYy9PtXBGuypyt5I.jpg', 'https://www.youtube.com/watch?v=BNxsaFCzqxc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (968, 'Renfield', 'Having grown sick and tired of his centuries as Dracula''s lackey, Renfield finds a new lease on life — and maybe even redemption — when he falls for feisty, perennially angry traffic cop Rebecca Quincy.', 'Chris McKay', 93, '2023-04-07', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/p6yUjhvNGQpFZilKwOKbxQ1eHlo.jpg', 'https://www.youtube.com/watch?v=6LmO6rmDW08', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (969, 'Swan Song', 'In the near future, Cameron Turner is diagnosed with a terminal illness. Presented with an experimental solution to shield his wife and son from grief, he grapples with altering their fate in this thought-provoking exploration of love, loss, and sacrifice.', 'Benjamin Cleary', 112, '2021-12-17', 'P', 'en', 'https://image.tmdb.org/t/p/w500/zzCdikGD9Qa5NT8lZtUv9dXNgsm.jpg', 'https://www.youtube.com/watch?v=LxftqrrlSqc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (970, 'MaXXXine', 'In 1980s Hollywood, adult film star and aspiring actress Maxine Minx finally gets her big break. But as a mysterious killer stalks the starlets of Hollywood, a trail of blood threatens to reveal her sinister past.', 'Ti West', 103, '2024-07-04', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/ArvoFK6nlouZRxYmtIOUzKIrg90.jpg', 'https://www.youtube.com/watch?v=adax3nfU6HU', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (971, 'Crawl', 'When a huge hurricane hits her hometown in Florida, Haley ignores evacuation orders to look for her father. After finding him badly wounded, both are trapped by the flood. With virtually no time to escape the storm, they discover that rising water levels are the least of their problems.', 'Alexandre Aja', 87, '2019-07-10', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/4WH6AZd473lRZ3hUp8TYiv2LfZW.jpg', 'https://www.youtube.com/watch?v=H6MLJG0RdDE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (972, 'Just Mercy', 'The powerful true story of Harvard-educated lawyer Bryan Stevenson, who goes to Alabama to defend the disenfranchised and wrongly condemned — including Walter McMillian, a man sentenced to death despite evidence proving his innocence. Bryan fights tirelessly for Walter with the system stacked against them.', 'Destin Daniel Cretton', 137, '2019-12-25', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/2bDZl3PzFLFWe4gaFUQnnaslqT3.jpg', 'https://www.youtube.com/watch?v=GVQbeG5yW78', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (973, 'Moonfall', 'A mysterious force knocks the moon from its orbit around Earth and sends it hurtling on a collision course with life as we know it.', 'Roland Emmerich', 131, '2022-02-02', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/odVv1sqVs0KxBXiA8bhIBlPgalx.jpg', 'https://www.youtube.com/watch?v=ivIwdQBlS10', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (974, 'Shoplifters', 'In the outskirts of Tokyo, a poor but close-knit group living on the fringes of society survives through shoplifting and odd jobs. When Osamu and his son take in a neglected young girl, their already fragile existence begins to unravel. As the family grows attached to her, buried secrets surface, forcing them to confront the true meaning of love, belonging, and what makes a family.', 'Hirokazu Kore-eda', 120, '2018-06-02', 'T16', 'ja', 'https://image.tmdb.org/t/p/w500/4nfRUOv3LX5zLn98WS1WqVBk9E9.jpg', 'https://www.youtube.com/watch?v=9382rwoMiRc', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (975, 'Daddy''s Home 2', 'Father and stepfather Dusty and Brad join forces to make Christmastime perfect for the children. Their newfound partnership soon gets put to the test when Dusty''s old-school, macho dad and Brad''s gentle father arrive to turn the holiday upside down. After a sudden change in plans, the four men decide to take the kids to a luxury resort for a fun-filled getaway that turns into a hilarious and chaotic adventure.', 'Sean Anders', 100, '2017-11-09', 'P', 'en', 'https://image.tmdb.org/t/p/w500/rF2IoKL0IFmumEXQFUuB8LajTYP.jpg', 'https://www.youtube.com/watch?v=hTKMUn87SxA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (976, 'The Internship', 'A CIA-trained assassin recruits other graduates from her secret childhood program, The Internship, to violently destroy the organization. The CIA fights back with deadly force.', 'James Bamford', 91, '2026-01-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/fYqSOkix4rbDiZW0ACNnvZCpT6X.jpg', 'https://www.youtube.com/watch?v=uXRFha7MLTM', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (977, 'Alpha', 'When Sita, a highly trained assassin raised in isolation as a super-soldier by a rogue commander, discovers the dark truth about her family and her stolen childhood, she teams up with her long lost sister to take down her creator and his illicit military program.', 'Shiv Rawail', 141, '2026-07-02', 'T16', 'hi', 'https://image.tmdb.org/t/p/w500/bPtRt3ajQ0EkyeQ1O6iJwAIi9Py.jpg', 'https://www.youtube.com/watch?v=YP1uSAggr6Y', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (978, 'Richard Jewell', 'Richard Jewell thinks quick, works fast, and saves hundreds, perhaps thousands, of lives after a domestic terrorist plants several pipe bombs and they explode during a concert, only to be falsely suspected of the crime by sloppy FBI work and sensational media coverage.', 'Clint Eastwood', 131, '2019-12-13', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/5Lgkm8jt4roAFPZQ52fKMhVmDaZ.jpg', 'https://www.youtube.com/watch?v=gSMxBLlA8qY', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (979, 'Murder Mystery', 'On a long-awaited trip to Europe, a New York City cop and his hairdresser wife scramble to solve a baffling murder aboard a billionaire''s yacht.', 'Kyle Newacheck', 98, '2019-05-25', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/bSMSO9xupd4R4vwTPqigHn2quLN.jpg', 'https://www.youtube.com/watch?v=5YEVQDr2f3Q', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (980, 'Come from Away', 'Filmed live on Broadway, the Tony Award-winning musical tells the remarkable true story of 38 flights grounded in a small Canadian town on September 11, 2001. As the locals host these “come from aways,” they come together and find hope.', 'Christopher Ashley', 107, '2021-09-09', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/9hAdtFyiRPyUYtWHzlPIDVsIUQ2.jpg', 'https://www.youtube.com/watch?v=Af77C4zUkjs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (981, 'The Hustle', 'Two female scam artists, one low rent and the other high class, compete to swindle a naïve tech prodigy out of his fortune. A remake of the 1988 comedy "Dirty Rotten Scoundrels."', 'Chris Addison', 94, '2019-05-09', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/qZniBGQRESLIfxw6GeZLZ2G1osa.jpg', 'https://www.youtube.com/watch?v=_j5hwooOHVE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (982, 'The Dink', 'Desperate to save a struggling country club and earn his father''s respect, a washed-up tennis pro is compelled to break a sacred vow and do the unthinkable: play pickleball.', 'Josh Greenbaum', 103, '2026-07-23', 'P', 'en', 'https://image.tmdb.org/t/p/w500/8dq7vaUkXPqwqKxBFW4qJNBWeop.jpg', 'https://www.youtube.com/watch?v=YyVNFzx5Pl8', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (983, 'One Mile: Chapter One', 'After being released from special forces, a father tries to reconnect with his daughter by taking her on a tour of college, but they soon find themselves fighting for more than their lost relationship when a murderous cult pursues them.', 'Adam Davidson', 90, '2026-02-20', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/1GZaoYe0mQy211DgDSAxAXr30ul.jpg', 'https://www.youtube.com/watch?v=868HlmpAhtQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (984, 'Father Stu', 'The true-life story of boxer-turned-priest. When an injury ends his amateur boxing career, Stuart Long moves to Los Angeles to find money and fame. While scraping by as a supermarket clerk, he meets Carmen, a Sunday school teacher who seems immune to his bad-boy charm. Determined to win her over, the longtime agnostic starts going to church to impress her. However, a motorcycle accident leaves him wondering if he can use his second chance to help others, leading to the surprising realization that he''s meant to be a Catholic priest.', 'Rosalind Ross', 124, '2022-04-13', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/pLAeWgqXbTeJ2gQtNvRmdIncYsk.jpg', 'https://www.youtube.com/watch?v=DHREzAdyCPs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (985, 'Code 8 Part II', 'In a world where superpowered people are heavily policed by robots, an ex-con teams up with a drug lord he despises to protect a teen from a corrupt cop.', 'Jeff Chan', 101, '2024-02-27', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/h89INyaoH16CdlT7q7BtKikIFRy.jpg', 'https://www.youtube.com/watch?v=omBi2KxEcRk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (986, 'Fatherland', 'In 1949, German writer Thomas Mann and his daughter Erika embark on a road trip across a Germany in ruins, from US-dominated Frankfurt to Soviet-controlled Weimar.', 'Paweł Pawlikowski', 82, '2026-06-19', 'P', 'pl', 'https://image.tmdb.org/t/p/w500/oNejN1l69nBF8LdQwy5FkAQZT44.jpg', 'https://www.youtube.com/watch?v=4pGI64qP0Bw', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (987, 'Purple Hearts', 'An aspiring musician agrees to a marriage of convenience with a soon-to-deploy Marine, but a tragedy soon turns their fake relationship all too real.', 'Elizabeth Allen Rosenbaum', 122, '2022-07-29', 'P', 'en', 'https://image.tmdb.org/t/p/w500/4JyNWkryifWbWXJyxcWh3pVya6N.jpg', 'https://www.youtube.com/watch?v=WTLgg8oRSBE', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (988, 'Happy Death Day', 'Caught in a bizarre and terrifying time warp, college student Tree finds herself repeatedly reliving the day of her murder, ultimately realizing that she must identify the killer and the reason for her death before her chances of survival run out.', 'Christopher Landon', 97, '2017-10-12', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/cTaEIUYTt52ooq9quVbAQ7NpGwo.jpg', 'https://www.youtube.com/watch?v=v3lXYAzf5TQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (989, 'Attack on Titan: THE LAST ATTACK', 'A colossal-sized omnibus film bringing together the last two episodes of Attack on Titan in the franchise''s first-ever theatrical experience. After venturing beyond the walls and separated from his comrades, Eren finds himself inspired by this new truth and plots the "Rumbling," a terrifying plan to eradicate every living thing in the world. With the fate of the world hanging in the balance, a motley crew of Eren''s former comrades and enemies scramble to halt his deadly mission. The only question is, can they stop him?', 'Yuichiro Hayashi', 145, '2024-03-20', 'T13', 'ja', 'https://image.tmdb.org/t/p/w500/wgwldDDlTDDMrluOMkpSA8lyKjv.jpg', 'https://www.youtube.com/watch?v=3xNH23QkNpk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (990, 'Lion', 'A five-year-old Indian boy gets lost on the streets of Calcutta, thousands of kilometers from home. He survives many challenges before being adopted by a couple in Australia; 25 years later, he sets out to find his lost family.', 'Garth Davis', 118, '2016-11-24', 'K', 'en', 'https://image.tmdb.org/t/p/w500/kCELJH1tCmaRLqvwIgKDb09aEaw.jpg', 'https://www.youtube.com/watch?v=GKkk-hDigTk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (991, 'House of Gucci', 'When Patrizia Reggiani, an outsider from humble beginnings, marries into the Gucci family, her unbridled ambition begins to unravel the family legacy and triggers a reckless spiral of betrayal, decadence, revenge, and ultimately… murder.', 'Ridley Scott', 158, '2021-11-24', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/oJCQjD2byiVF1EG408F9dBn9ndU.jpg', 'https://www.youtube.com/watch?v=eGNnpVKxV6s', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (992, 'Desert Warrior', 'In 7th-century Arabia, Princess Hind becomes a warrior to defy the ruthless Emperor Kisra. Forged into a warrior and aided by legendary bandit Hanzala, Hind unites warring tribes for a last stand—the historic Battle of Dhi Qar—that will change history.', 'Rupert Wyatt', 127, '2026-04-23', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/waxnw1NpzTPY5JkqWvu0muSopRJ.jpg', 'https://www.youtube.com/watch?v=fraAGOuT3sA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (993, 'Late Night with the Devil', 'A live broadcast of a late-night talk show in 1977 goes horribly wrong, unleashing evil into the nation''s living rooms.', 'Cameron Cairnes, Colin Cairnes', 93, '2024-03-19', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/mu8LRWT9GHkfiyHm7kgxT6YNvMW.jpg', 'https://www.youtube.com/watch?v=TiwvEtimLzQ', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (994, 'Sisu', 'When an ex-soldier who discovers gold in the Lapland wilderness tries to take the loot into the city, German soldiers led by a brutal SS officer battle him.', 'Jalmari Helander', 91, '2022-09-09', 'T16', 'fi', 'https://image.tmdb.org/t/p/w500/xgb30M1wL4nibyFvlHh3w4XlDYq.jpg', 'https://www.youtube.com/watch?v=d2k4QAItiSA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (995, 'Mile 22', 'An elite group of American operatives, aided by a top-secret tactical command team, must transport an asset who holds life-threatening information to an extraction point 22 miles away through the hostile streets of an Asian city.', 'Peter Berg', 94, '2018-08-16', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/2L8ehd95eSW9x7KINYtZmRkAlrZ.jpg', 'https://www.youtube.com/watch?v=3CVV8X01824', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (996, 'The Neon Demon', 'When aspiring model Jesse moves to Los Angeles, her youth and vitality are devoured by a group of beauty-obsessed women who will take any means necessary to get what she has.', 'Nicolas Winding Refn', 118, '2016-06-08', 'T18', 'en', 'https://image.tmdb.org/t/p/w500/d93h9dHIez9zRg4ooG6o1ZiQ776.jpg', 'https://www.youtube.com/watch?v=YqFhKdRFPvA', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (997, 'Iron Lung', 'In a post-apocalyptic future where an event known as "The Quiet Rapture" caused all known stars and habitable planets in the universe to disappear, a convict is sent to search an ocean of blood discovered on a desolate moon, using a small submarine nicknamed the "Iron Lung".', 'Mark Fischbach', 125, '2026-01-30', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sIwakdbMGS1krtgendTWpxTY9Hw.jpg', 'https://www.youtube.com/watch?v=7qRf_f_bbUk', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (998, 'Allied', 'In 1942, an intelligence officer in North Africa encounters a female French Resistance fighter on a deadly mission behind enemy lines. When they reunite in London, their relationship is tested by the pressures of war.', 'Robert Zemeckis', 124, '2016-11-23', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/sV4lXM32quwminL3TP36nlNPp7Q.jpg', 'https://www.youtube.com/watch?v=-hQGiozwHiI', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (999, 'Murder Mystery 2', 'After starting their own detective agency, Nick and Audrey Spitz land a career-making case when their billionaire pal is kidnapped from his wedding.', 'Jeremy Garelick', 91, '2023-03-28', 'T16', 'en', 'https://image.tmdb.org/t/p/w500/s1VzVhXlqsevi8zeCMG9A16nEUf.jpg', 'https://www.youtube.com/watch?v=LM2F56uK0fs', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (1000, 'Little Brother', 'A tightly wound realtor''s picture-perfect life gets an extreme makeover when his lovably chaotic "little brother" suddenly reappears.', 'Matt Spicer', 102, '2026-06-18', 'T13', 'en', 'https://image.tmdb.org/t/p/w500/hIJpXb7Xaje2mebN9ylsS7blQzP.jpg', 'https://www.youtube.com/watch?v=bWtrFcerKE0', 'ENDED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE 
  title = VALUES(title),
  description = VALUES(description),
  director = VALUES(director),
  duration_minutes = VALUES(duration_minutes),
  release_date = VALUES(release_date),
  age_rating = VALUES(age_rating),
  original_language = VALUES(original_language),
  poster_url = VALUES(poster_url),
  trailer_url = VALUES(trailer_url),
  status = VALUES(status),
  updated_at = CURRENT_TIMESTAMP;

